throws":[{"name":"STR","index":"str"},{"name":"CON","index":"con"}],"schema_version":2,"subclass_label":"Fight Club","subclass_level":3,"feature_details":[{"desc":["You use a scaling damage die for unarmed strikes and 'Pugilist Weapons' (simple melee, whips, improvised). You can make one unarmed strike or grapple as a bonus action when you attack."],"name":"Fisticuffs","index":"fisticuffs","level":1,"effects":[{"desc":"Make one unarmed strike as a bonus action.","name":"Fisticuffs (Bonus Unarmed Strike)","type":"bonus_action","description":"Make one unarmed strike as a bonus action."},{"type":"bonus_action","name":"Fisticuffs","description":"Make an unarmed strike as a bonus action."}]},{"desc":["While wearing light or no armor (and no shield), your AC is 12 + Constitution modifier."],"name":"Iron Chin","index":"iron-chin","level":1,"effects":[{"name":"Iron Chin","rule":"If NOT Heavy Armor AND No Shield Held","stat":"ac","type":"stat_bonus_attribute","target":"ac","attribute":"con","condition":"If NOT Heavy Armor AND No Shield Held","conditions":["not:heavy_armor","no_shield"]}]},{"desc":["You have a pool of Moxie points (regained on a Short or Long rest). Spend points for: Brace Up (Temp HP), The Old One-Two (Two unarmed strikes), or Stick and Move (Dash/Shove)."],"name":"Moxie","index":"moxie","level":2,"effects":[]},{"desc":["You are at home in the urban sprawl. You have advantage on checks to find food, shelter, or information in settlements."],"name":"Street Smart","index":"street-smart","level":2,"effects":[]},{"desc":["When reduced to half HP or less, use your reaction to regain all Moxie and gain Temp HP equal to Level + Con mod. (1/Short Rest)"],"name":"Bloodied but Unbowed","index":"bloodied-but-unbowed","level":3,"effects":[{"desc":"When reduced to half HP or less, regain all Moxie and gain temporary HP equal to your level.","name":"Bloodied but Unbowed","type":"reaction","description":"When reduced to half HP or less, regain all Moxie and gain temporary HP equal to your level."}]},{"desc":["Choose a Fight Club that defines your specific brawling style."],"name":"Fight Club","index":"fight-club","level":3,"effects":[]},{"desc":["Bonus action to gain resistance to Bludgeoning, Piercing, and Slashing for 1 minute. You gain a level of exhaustion when it ends."],"name":"Dig Deep","index":"dig-deep","level":4,"effects":[{"desc":"Gain resistance to bludgeoning, piercing and slashing damage for 1 minute.","name":"Dig Deep","type":"bonus_action","description":"Gain resistance to bludgeoning, piercing and slashing damage for 1 minute."}]},{"desc":["You can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":4,"effects":[]},{"desc":["You can choose to take Disadvantage on all attacks this turn to deal Maximum Damage on hits with unarmed strikes or pugilist weapons."],"name":"Haymaker","index":"haymaker","level":5,"effects":[]},{"desc":["Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn."],"name":"Extra Attack","index":"extra-attack","level":5,"effects":[{"mode":"set","name":"Extra Attack","type":"extra_attack","value":2}]},{"desc":["Your unarmed strikes and pugilist weapons count as magical for the purpose of overcoming resistance."],"name":"Moxie-Fueled Fists","index":"moxie-fueled-fists","level":6,"effects":[{"name":"Moxie-Fueled Fists","type":"feature","description":"Your unarmed strikes improve."}]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":6,"effects":[]},{"desc":["You gain proficiency in Dexterity saving throws. If you already have it, you gain proficiency in another save of your choice."],"name":"Fancy Footwork","index":"fancy-footwork","level":7,"effects":[{"name":"DEX","type":"proficiency","value":"DEX","target":"DEX","category":"save"}]},{"desc":["You can use a bonus action to end one of the following conditions on yourself: Charmed, Frightened, or Poisoned."],"name":"Shake It Off","index":"shake-it-off","level":7,"effects":[{"name":"Shake It Off","type":"bonus_action","description":"End a condition affecting you."}]},{"desc":["You can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":8,"effects":[]},{"desc":["When using Bloodied But Unbowed, you can also add your Proficiency Bonus to damage for 1 minute (1/Long Rest)."],"name":"Down but Not Out","index":"down-but-not-out","level":9,"effects":[]},{"desc":["You have resistance to psychic damage and have advantage on saves against being charmed."],"name":"School of Hard Knocks","index":"school-of-hard-knocks","level":10,"effects":[{"name":"School of Hard Knocks","type":"resistance","value":"Psychic","damage_type":"Psychic"},{"name":"School of Hard Knocks","stat":"saves","type":"advantage","filter":"Charmed","target":"saves","condition":"against being charmed"}]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":11,"effects":[]},{"desc":["You can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":12,"effects":[]},{"desc":["You can find enough volunteers to perform non-specialized labor for you in any settlement."],"name":"Rabble Rouser","index":"rabble-rouser","level":13,"effects":[]},{"desc":["When you are reduced to 0 HP but not killed outright, you can spend 1 Moxie to drop to 1 HP instead."],"name":"Unbreakable","index":"unbreakable","level":14,"effects":[]},{"desc":["Your carrying capacity doubles. You have advantage on Strength checks to break, lift, or move objects."],"name":"Herculean","index":"herculean","level":15,"effects":[]},{"desc":["You can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":16,"effects":[]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":17,"effects":[]},{"desc":["At the start of each of your turns, you regain 1 Moxie point if you have 0 points."],"name":"Fighting Spirit","index":"fighting-spirit","level":18,"effects":[]},{"desc":["You can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can't increase an ability score above 20 using this feature."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":19,"effects":[]},{"desc":["Str and Con increase by 2 (max 22). Recover 2 levels of exhaustion and all Hit Dice on a long rest."],"name":"Peak Physical Condition","index":"peak-physical-condition","level":20,"effects":[{"type":"bonus","value":2,"target":"str"},{"type":"bonus","value":2,"target":"con"}]}]}$persona_content_migration$::jsonb,
