-- Warlock (warlock)
update public.custom_classes
   set data = $persona_content_migration${"id":"9721e9d2-61cc-4661-87cc-e5de9ce32ecd","ui":{},"desc":["Warlocks quest for knowledge that lies hidden in the fabric of the multiverse. They often begin their search for magical power by delving into tomes of forbidden lore, dabbling in invocations meant to attract the power of extraplanar beings, or seeking places of power where the influence of these beings can be felt. Once a Warlock has gained their patron's power, they can cast spells, bind themselves to a pact, and learn dreadful invocations."],"name":"Warlock","index":"warlock","rules":[],"caster":{"type":"pact","ability":"cha"},"source":"Player's Handbook 2024","choices":[{"id":"warlock-proficiency-0","kind":"proficiency","count":2,"source":"class","options":[{"name":"Arcana","index":"arcana","rawName":"Skill: Arcana","category":"skill"},{"name":"Deception","index":"deception","rawName":"Skill: Deception","category":"skill"},{"name":"History","index":"history","rawName":"Skill: History","category":"skill"},{"name":"Intimidation","index":"intimidation","rawName":"Skill: Intimidation","category":"skill"},{"name":"Investigation","index":"investigation","rawName":"Skill: Investigation","category":"skill"},{"name":"Nature","index":"nature","rawName":"Skill: Nature","category":"skill"},{"name":"Religion","index":"religion","rawName":"Skill: Religion","category":"skill"}]}],"hit_die":8,"options":{"invocations":[{"name":"Agonizing Blast","desc":"Add your Charisma modifier to Eldritch Blast damage.","effects":[{"type":"attack_rider","name":"Agonizing Blast","condition":"spell:eldritch blast","description":"Add your Charisma modifier to the damage Eldritch Blast deals on a hit."},{"type":"spell_damage_bonus","name":"Agonizing Blast","ability":"cha","spell":"Eldritch Blast"}]},{"name":"Armor of Shadows","desc":"Cast Mage Armor on yourself at will.","effects":[{"type":"set","stat":"ac","target":"ac","value":13,"condition":"no_armor"}]},{"name":"Devil's Sight","desc":"See normally in darkness, both magical and nonmagical, to 120 feet.","effects":[{"type":"set","target":"darkvision","value":120}]},{"name":"Eldritch Mind","desc":"Advantage on Constitution saving throws to maintain concentration.","effects":[{"type":"advantage","target":"saves","filter":"Concentration"}]},{"name":"Eldritch Spear","desc":"Eldritch Blast range becomes 300 feet."},{"name":"Fiendish Vigor","desc":"Cast False Life on yourself at will.","effects":[{"type":"feature","name":"Fiendish Vigor","description":"Cast False Life on yourself at will as a 1st-level spell."}]},{"name":"Mask of Many Faces","desc":"Cast Disguise Self at will.","effects":[{"type":"spell_access","spell":"Disguise Self","cast_free":true}]},{"name":"Misty Visions","desc":"Cast Silent Image at will.","effects":[{"type":"spell_access","spell":"Silent Image","cast_free":true}]},{"name":"Repelling Blast","desc":"Push a creature 10 feet when Eldritch Blast hits.","effects":[{"type":"attack_rider","name":"Repelling Blast","condition":"spell:eldritch blast","description":"When you hit a creature with Eldritch Blast, you can push it up to 10 feet away from you."}]},{"name":"Thirsting Blade","desc":"Attack twice with your pact weapon when you take the Attack action.","effects":[{"type":"extra_attack","mode":"set","value":2,"name":"Thirsting Blade"}]}]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"resources":[],"spell_list":["warlock"],"is_homebrew":false,"level_table":[{"level":1,"features":["Eldritch Invocations","Pact Magic"],"prof_bonus":2,"class_specific":{"slots":1,"cantrips":2,"prepared":2,"slot_level":1,"invocations":1}},{"level":2,"features":["Magical Cunning"],"prof_bonus":2,"class_specific":{"slots":2,"cantrips":2,"prepared":3,"slot_level":1,"invocations":3}},{"level":3,"features":["Warlock Subclass"],"prof_bonus":2,"class_specific":{"slots":2,"cantrips":2,"prepared":4,"slot_level":2,"invocations":3}},{"level":4,"features":["Ability Score Improvement"],"prof_bonus":2,"class_specific":{"slots":2,"cantrips":3,"prepared":5,"slot_level":2,"invocations":3}},{"level":5,"features":[],"prof_bonus":3,"class_specific":{"slots":2,"cantrips":3,"prepared":6,"slot_level":3,"invocations":5}},{"level":6,"features":["Subclass feature"],"prof_bonus":3,"class_specific":{"slots":2,"cantrips":3,"prepared":7,"slot_level":3,"invocations":5}},{"level":7,"features":[],"prof_bonus":3,"class_specific":{"slots":2,"cantrips":3,"prepared":8,"slot_level":4,"invocations":6}},{"level":8,"features":["Ability Score Improvement"],"prof_bonus":3,"class_specific":{"slots":2,"cantrips":3,"prepared":9,"slot_level":4,"invocations":6}},{"level":9,"features":["Contact Patron"],"prof_bonus":4,"class_specific":{"slots":2,"cantrips":3,"prepared":10,"slot_level":5,"invocations":7}},{"level":10,"features":["Subclass feature"],"prof_bonus":4,"class_specific":{"slots":2,"cantrips":4,"prepared":10,"slot_level":5,"invocations":7}},{"level":11,"features":["Mystic Arcanum (level 6 spell)"],"prof_bonus":4,"class_specific":{"slots":3,"cantrips":4,"prepared":11,"slot_level":5,"invocations":7}},{"level":12,"features":["Ability Score Improvement"],"prof_bonus":4,"class_specific":{"slots":3,"cantrips":4,"prepared":11,"slot_level":5,"invocations":8}},{"level":13,"features":["Mystic Arcanum (level 7 spell)"],"prof_bonus":5,"class_specific":{"slots":3,"cantrips":4,"prepared":12,"slot_level":5,"invocations":8}},{"level":14,"features":["Subclass feature"],"prof_bonus":5,"class_specific":{"slots":3,"cantrips":4,"prepared":12,"slot_level":5,"invocations":8}},{"level":15,"features":["Mystic Arcanum (level 8 spell)"],"prof_bonus":5,"class_specific":{"slots":3,"cantrips":4,"prepared":13,"slot_level":5,"invocations":9}},{"level":16,"features":["Ability Score Improvement"],"prof_bonus":5,"class_specific":{"slots":3,"cantrips":4,"prepared":13,"slot_level":5,"invocations":9}},{"level":17,"features":["Mystic Arcanum (level 9 spell)"],"prof_bonus":6,"class_specific":{"slots":4,"cantrips":4,"prepared":14,"slot_level":5,"invocations":9}},{"level":18,"features":[],"prof_bonus":6,"class_specific":{"slots":4,"cantrips":4,"prepared":14,"slot_level":5,"invocations":10}},{"level":19,"features":["Epic Boon"],"prof_bonus":6,"class_specific":{"slots":4,"cantrips":4,"prepared":15,"slot_level":5,"invocations":10}},{"level":20,"features":["Eldritch Master"],"prof_bonus":6,"class_specific":{"slots":4,"cantrips":4,"prepared":15,"slot_level":5,"invocations":10}}],"spellcasting":{"info":[],"level":1,"progression":"pact","spellcasting_ability":{"name":"CHA","index":"cha"}},"proficiencies":[{"name":"Light Armor"},{"name":"Simple Weapons"}],"saving_throws":[{"name":"WIS","index":"wis"},{"name":"CHA","index":"cha"}],"schema_version":2,"subclass_label":"Otherworldly Patron","subclass_level":3,"feature_details":[{"desc":["You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome.\nPrerequisites. If an invocation has a prerequisite, you must meet it to learn that invocation.\nReplacing and Gaining Invocations. Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can't replace an invocation if it's a prerequisite for another invocation that you have. You gain more invocations as you gain levels: 3 at level 2, 5 at 5, 6 at 7, 7 at 9, 8 at 12, 9 at 15, 10 at 17.\nYou can't pick the same invocation more than once unless its description says otherwise."],"name":"Eldritch Invocations","index":"eldritch-invocations","level":1,"effects":[{"name":"Eldritch Invocations","type":"feature","description":"Learn fragments of forbidden knowledge."}]},{"desc":["Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers.\nCantrips. You know two Warlock cantrips of your choice (Eldritch Blast and Prestidigitation are recommended). Whenever you gain a Warlock level, you can replace one of your cantrips with another Warlock cantrip. You learn another cantrip at Warlock levels 4 and 10.\nSpell Slots. The Warlock table shows how many spell slots you have to cast your Warlock spells of levels 1–5 and the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast. To start, choose two level 1 Warlock spells. The number of prepared spells increases as you gain Warlock levels (3 at level 2, 4 at 3, 5 at 4, 6 at 5, 7 at 6, 8 at 7, 9 at 8, 10 at 9, 11 at 11, 12 at 13, 13 at 15, 14 at 17). The chosen spells must be of a level no higher than your slot level. Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.\nSpellcasting Ability. Charisma is the spellcasting ability for your Warlock spells.\nSpellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells."],"name":"Pact Magic","index":"pact-magic","level":1,"effects":[{"name":"Pact Magic","type":"feature","description":"Your spell slots recharge on a short rest."}]},{"desc":["You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can't do so again until you finish a Long Rest."],"name":"Magical Cunning","index":"magical-cunning","level":2,"effects":[{"name":"Magical Cunning","type":"feature","description":"Regain expended Pact Magic slots."}]},{"desc":["You gain a Warlock subclass of your choice. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass's features that are of your Warlock level or lower."],"name":"Warlock Subclass","index":"warlock-subclass","level":3,"effects":[]},{"desc":["You gain the Ability Score Improvement feat or another feat of your choice for which you qualify."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":4,"effects":[]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":6,"effects":[]},{"desc":["You gain the Ability Score Improvement feat or another feat of your choice for which you qualify."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":8,"effects":[]},{"desc":["In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell's saving throw.\nOnce you cast the spell with this feature, you can't do so in this way again until you finish a Long Rest."],"name":"Contact Patron","index":"contact-patron","level":9,"effects":[{"name":"Contact Other Plane","type":"spell_access","spell":"Contact Other Plane","condition":"Always prepared; 1/Long Rest without a slot (auto-succeed save)","free_casts":1,"free_cast_reset":"long"}]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":10,"effects":[]},{"desc":["Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.\nYou can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.\nYou gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest.\nWhenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level."],"name":"Mystic Arcanum (level 6 spell)","index":"mystic-arcanum-(level-6-spell)","level":11,"effects":[{"name":"Mystic Arcanum (level 6)","type":"spell_access","count":1,"level":6,"condition":"1/Long Rest without a slot","filter_class":"Warlock"}]},{"desc":["You gain the Ability Score Improvement feat or another feat of your choice for which you qualify."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":12,"effects":[]},{"desc":["Choose one level 7 Warlock spell as an additional arcanum. You can cast it once without expending a spell slot per Long Rest."],"name":"Mystic Arcanum (level 7 spell)","index":"mystic-arcanum-(level-7-spell)","level":13,"effects":[{"name":"Mystic Arcanum (level 7)","type":"spell_access","count":1,"level":7,"condition":"1/Long Rest without a slot","filter_class":"Warlock"}]},{"desc":[""],"name":"Subclass feature","index":"subclass-feature","level":14,"effects":[]},{"desc":["Choose one level 8 Warlock spell as an additional arcanum. You can cast it once without expending a spell slot per Long Rest."],"name":"Mystic Arcanum (level 8 spell)","index":"mystic-arcanum-(level-8-spell)","level":15,"effects":[{"name":"Mystic Arcanum (level 8)","type":"spell_access","count":1,"level":8,"condition":"1/Long Rest without a slot","filter_class":"Warlock"}]},{"desc":["You gain the Ability Score Improvement feat or another feat of your choice for which you qualify."],"name":"Ability Score Improvement","index":"ability-score-improvement","level":16,"effects":[]},{"desc":["Choose one level 9 Warlock spell as an additional arcanum. You can cast it once without expending a spell slot per Long Rest."],"name":"Mystic Arcanum (level 9 spell)","index":"mystic-arcanum-(level-9-spell)","level":17,"effects":[{"name":"Mystic Arcanum (level 9)","type":"spell_access","count":1,"level":9,"condition":"1/Long Rest without a slot","filter_class":"Warlock"}]},{"desc":["You gain an Epic Boon feat or another feat of your choice for which you qualify. Boon of Fate is recommended."],"name":"Epic Boon","index":"epic-boon","level":19,"effects":[]},{"desc":["When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots."],"name":"Eldritch Master","index":"eldritch-master","level":20,"effects":[]}]}$persona_content_migration$::jsonb,
