-- Magic Specialization (magic-specialization)
update public.custom_subclasses
   set data = $persona_content_migration${"id":"8b299638-b8d1-477a-bb43-d9a170f1c6e8","ui":{},"desc":["Focusing on magical / elemental effects, this specialization gives you access to magical arrows."],"name":"Magic Specialization","class":{"name":"Arrowsmith","index":"arrowsmith"},"index":"magic-specialization","source":"Arrowsmith Specialization","choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"resources":[],"spell_list":[],"class_index":"arrowsmith","is_homebrew":false,"schema_version":2,"subclass_label":"Specialization","subclass_level":5,"feature_details":[{"desc":["Gain proficiency in Calligrapher's Supplies. You gain access to the Magic Arrows table: Elemental Arrow, Spectral Arrow, Cursed Arrow, Seeking Arrow, and Shifter Arrow."],"name":"Magic Arrowsmith","index":"magic-arrowsmith","level":5,"effects":[{"type":"proficiency","target":"Calligrapher's Supplies","category":"tool"}]},{"desc":["At 8th level, all Custom Arrows now count as magical for the sake of overcoming resistances."],"name":"Arcane Shot","index":"arcane-shot","level":8,"effects":[]},{"desc":["At 11th level, whenever you crit on a ranged attack with a Custom Arrow, the arrow returns to your quiver."],"name":"Magic Trick","index":"magic-trick","level":11,"effects":[]},{"desc":["At 14th level, you can add your wisdom modifier plus your proficiency bonus to the damage of a ranged attack as psychic damage."],"name":"Wise Aim","index":"wise-aim","level":14,"effects":[{"desc":"Add WIS modifier + proficiency bonus as psychic damage to a ranged attack.","name":"Wise Aim","type":"feature","description":"Add WIS modifier + proficiency bonus as psychic damage to a ranged attack."}]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'magic-specialization'),
       source = 'Arrowsmith Specialization',
       migrated_at = now()
 where id = '8b299638-b8d1-477a-bb43-d9a170f1c6e8';

-- Support Specialization (support-specialization)
update public.custom_subclasses
   set data = $persona_content_migration${"id":"a31a0d38-0c5e-4e5c-bc92-750e4099a048","ui":{},"desc":["Focuses on Custom Arrows that can be helpful to their target."],"name":"Support Specialization","class":{"name":"Arrowsmith","index":"arrowsmith"},"index":"support-specialization","source":"Arrowsmith Specialization","choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"resources":[],"spell_list":[],"class_index":"arrowsmith","is_homebrew":false,"schema_version":2,"subclass_label":"Specialization","subclass_level":5,"feature_details":[{"desc":["Gain proficiency in healing tools. You gain access to the Support Arrows table: Healing Arrow, Vigorous Arrow, Anti-Healing Arrow, Adrenaline Arrow, and Affection Arrow. Effects are doubled on a crit."],"name":"Support Arrowsmith","index":"support-arrowsmith","level":5,"effects":[{"name":"Healer's Kit","type":"proficiency","value":"Healer's Kit","target":"Healer's Kit","category":"tool"}]},{"desc":["At 8th level, you never miss a friendly creature with an arrow unless it is impossible to hit them."],"name":"Hold Still","index":"hold-still","level":8,"effects":[]},{"desc":["At 11th level, as a reaction, you can shoot a teammate who is being attacked by an enemy with a special arrow."],"name":"Medical Reaction","index":"medical-reaction","level":11,"effects":[{"desc":"Shoot a teammate who is being attacked with a special arrow.","name":"Medical Reaction","type":"reaction","description":"Shoot a teammate who is being attacked with a special arrow."}]},{"desc":["At 14th level, when hitting yourself with one of your arrows, you always crit, doubling the effects."],"name":"Self Care","index":"self-care","level":14,"effects":[]}]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'support-specialization'),
       source = 'Arrowsmith Specialization',
