-- Owlin (owlin)
update public.custom_races
   set data = $persona_content_migration${"id":"bec22e53-024f-409b-b820-f77b0b0c389e","age":"Owlin mature and age at about the same rate as humans.","desc":["Owlin are owl-like humanoids who glide silently through the night. With feathered wings, superb night vision, and nearly soundless flight, they make natural scouts, scholars, and watchers in the dark."],"name":"Owlin","size":"Small or Medium","index":"owlin","speed":30,"source":"Strixhaven: A Curriculum of Chaos","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}]},{"desc":["Thanks to your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."],"name":"Flight","index":"flight","effects":[{"desc":"Fly Speed equal to your walking speed; not usable in medium or heavy armor.","name":"Flight","type":"feature","description":"Fly Speed equal to your walking speed; not usable in medium or heavy armor."}],"modifiers":[{"desc":"Fly Speed equal to your walking speed; not usable in medium or heavy armor.","name":"Flight","type":"feature","description":"Fly Speed equal to your walking speed; not usable in medium or heavy armor."}]},{"desc":["You have proficiency in the Stealth skill."],"name":"Silent Feathers","index":"silent-feathers","effects":[{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"},{"type":"proficiency","target":"Stealth","category":"skill"}],"modifiers":[{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"}]}],"choices":[{"id":"owlin-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"owlin-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","fly_speed":30,"is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small (about 3–4 feet tall), chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'owlin'),
       source = 'Strixhaven: A Curriculum of Chaos',
       migrated_at = now()
 where id = 'bec22e53-024f-409b-b820-f77b0b0c389e';

-- Centaur (centaur)
update public.custom_races
   set data = $persona_content_migration${"id":"9a3e2655-588f-434c-a3f6-0f714cff67f4","age":"Centaurs mature and age at about the same rate as humans.","desc":["Centaurs gallop across the plains and forests of many worlds, their upper bodies humanoid and their lower bodies those of powerful horses. Fey in nature, they are swift, strong, and deeply tied to the wild places they roam."],"name":"Centaur","size":"Medium","index":"centaur","speed":40,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Fey."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}]},{"desc":["If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."],"name":"Charge","index":"charge","effects":[{"desc":"After moving 30+ ft. straight toward a target and hitting it with a melee weapon attack, make a hooves attack.","name":"Charge","type":"bonus_action","description":"After moving 30+ ft. straight toward a target and hitting it with a melee weapon attack, make a hooves attack."}],"modifiers":[{"desc":"After moving 30+ ft. straight toward a target and hitting it with a melee weapon attack, make a hooves attack.","name":"Charge","type":"bonus_action","description":"After moving 30+ ft. straight toward a target and hitting it with a melee weapon attack, make a hooves attack."}]},{"desc":["You count as one size larger when determining your carrying capacity and the weight you can push or drag. In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet instead of the normal 1 extra foot."],"name":"Equine Build","index":"equine-build","effects":[{"desc":"Count as one size larger for carrying capacity; climbing with hands and feet costs 4 extra feet per foot.","name":"Equine Build","type":"feature","description":"Count as one size larger for carrying capacity; climbing with hands and feet costs 4 extra feet per foot."}],"modifiers":[{"desc":"Count as one size larger for carrying capacity; climbing with hands and feet costs 4 extra feet per foot.","name":"Equine Build","type":"feature","description":"Count as one size larger for carrying capacity; climbing with hands and feet costs 4 extra feet per foot."}]},{"desc":["You have hooves that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Hooves","index":"hooves","effects":[{"die":"1d6","name":"Hooves","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Bludgeoning"}],"modifiers":[{"die":"1d6","name":"Hooves","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Bludgeoning"}]},{"desc":["Your fey connection to nature gives you an intuitive connection to the natural world and the animals within it. You have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."],"name":"Natural Affinity","index":"natural-affinity","effects":[],"modifiers":[]}],"choices":[{"id":"centaur-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"centaur-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"centaur-skill","kind":"skill","count":1,"label":"Natural Affinity skill","source":"race","options":["Animal Handling","Medicine","Nature","Survival"]},{"id":"centaur-survivor","kind":"skill","count":1,"source":"race","options":["Animal Handling","Medicine","Nature","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; centaurs are often neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'centaur'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '9a3e2655-588f-434c-a3f6-0f714cff67f4';

-- Gith (gith)
update public.custom_races
   set data = $persona_content_migration${"id":"a2296832-4f2c-4ba8-a3e4-7151024dd600","age":"Gith reach adulthood in their late teens and live for about a century.","desc":["The gith — githyanki and githzerai — were once a single people enslaved by mind flayers. They rose up, won their freedom, and split into two cultures: the astral raiders of the githyanki and the monastic, ordered githzerai of Limbo."],"name":"Gith","size":"Medium","index":"gith","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["Choose Githyanki or Githzerai (see subraces). Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with your gith traits (choose when you select this race)."],"name":"Gith Heritage","index":"gith-heritage","effects":[]}],"choices":[{"id":"gith-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"gith-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"gith-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Githyanki tend toward evil and law; githzerai tend toward lawful neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Gith","index":"gith"}],"is_homebrew":false,"language_desc":"Common, Gith","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 6 feet tall).","subraces_details":[{"desc":["Githyanki are astral raiders who ride red dragons and plunder the planes."],"name":"Githyanki","index":"githyanki","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Whenever you finish a Long Rest, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the Player's Handbook, as you momentarily project your consciousness into the Astral Plane. These proficiencies last until the end of your next Long Rest."],"name":"Astral Knowledge","index":"astral-knowledge","effects":[{"desc":"After each Long Rest, gain proficiency in one skill and one weapon or tool until your next Long Rest.","name":"Astral Knowledge","type":"feature","description":"After each Long Rest, gain proficiency in one skill and one weapon or tool until your next Long Rest."}]},{"url":"","desc":["You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. Starting at 3rd level, you can cast the Jump spell with this trait. Starting at 5th level, you can also cast Misty Step with it. Once you cast Jump or Misty Step with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using spell slots you have of the appropriate level. The spells' spellcasting ability is Intelligence, Wisdom, or Charisma when you cast them with this trait (choose when you select this race)."],"name":"Githyanki Psionics","index":"githyanki-psionics","effects":[{"name":"Mage Hand","type":"spell_access","spell":"Mage Hand","condition":"Cantrip (invisible hand)"},{"name":"Jump","type":"spell_access","spell":"Jump","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Misty Step","type":"spell_access","spell":"Misty Step","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"url":"","desc":["You have resistance to psychic damage."],"name":"Psychic Resilience","index":"psychic-resilience","effects":[{"name":"Psychic","type":"resistance","value":"Psychic","condition":"","damage_type":"Psychic"}]}],"choices":[{"id":"githyanki-decadent-mastery-skill-tool","kind":"proficiency","count":1,"source":"subrace","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival","Alchemist's supplies","Brewer's supplies","Calligrapher's supplies","Carpenter's tools","Cartographer's tools","Cobbler's tools","Cook's utensils","Glassblower's tools","Jeweler's tools","Leatherworker's tools","Mason's tools","Painter's supplies","Potter's tools","Smith's tools","Tinker's tools","Weaver's tools","Woodcarver's tools"]},{"id":"githyanki-decadent-mastery-language","kind":"language","count":1,"source":"subrace","options":["Abyssal","Aquan","Auran","Celestial","Common","Deep Speech","Draconic","Dwarvish","Elvish","Giant","Gnomish","Goblin","Halfling","Ignan","Infernal","Orc","Primordial","Sylvan","Terran","Undercommon"]}],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Githzerai are ascetic monks who order their minds against the chaos of Limbo."],"name":"Githzerai","index":"githzerai","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. Starting at 3rd level, you can cast the Shield spell with this trait. Starting at 5th level, you can also cast the Detect Thoughts spell with it. Once you cast Shield or Detect Thoughts with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using spell slots you have of the appropriate level. The spells' spellcasting ability is Intelligence, Wisdom, or Charisma when you cast them with this trait (choose when you select this race)."],"name":"Githzerai Psionics","index":"githzerai-psionics","effects":[{"name":"Mage Hand","type":"spell_access","spell":"Mage Hand","condition":"Cantrip (invisible hand)"},{"name":"Shield","type":"spell_access","spell":"Shield","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Detect Thoughts","type":"spell_access","spell":"Detect Thoughts","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"url":"","desc":["You have resistance to psychic damage. You also have advantage on saving throws made to avoid or end the charmed or frightened condition."],"name":"Mental Discipline","index":"mental-discipline","effects":[{"name":"Psychic","type":"resistance","value":"Psychic","condition":"","damage_type":"Psychic"},{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'gith'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'a2296832-4f2c-4ba8-a3e4-7151024dd600';

-- Orc (orc)
update public.custom_races
   set data = $persona_content_migration${"id":"bb906264-2f49-4b86-8113-f3870cd3ef43","age":"Orcs reach adulthood around 12 and live up to 80 years.","desc":["Orcs trace their creation to Gruumsh, the one-eyed god of conquest and survival, who gave them endurance and a fury that lets them push through any hardship. Found across the multiverse, orcs are hardy, driven, and fiercely loyal to those they call kin."],"name":"Orc","size":"Medium","index":"orc","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You can take the Dash action as a Bonus Action. When you do so, you gain a number of Temporary Hit Points equal to your Proficiency Bonus. You can use this trait a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Short or Long Rest."],"name":"Adrenaline Rush","index":"adrenaline-rush","effects":[{"desc":"Dash as a Bonus Action and gain PB Temporary Hit Points. PB uses per Short or Long Rest.","name":"Adrenaline Rush","type":"bonus_action","description":"Dash as a Bonus Action and gain PB Temporary Hit Points. PB uses per Short or Long Rest."}],"modifiers":[{"desc":"Dash as a Bonus Action and gain PB Temporary Hit Points. PB uses per Short or Long Rest.","name":"Adrenaline Rush","type":"bonus_action","description":"Dash as a Bonus Action and gain PB Temporary Hit Points. PB uses per Short or Long Rest."}]},{"desc":["You have Darkvision with a range of 120 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}]},{"desc":["When you are reduced to 0 Hit Points but not killed outright, you can drop to 1 Hit Point instead. Once you use this trait, you can't do so again until you finish a Long Rest."],"name":"Relentless Endurance","index":"relentless-endurance","effects":[{"desc":"Drop to 1 HP instead of 0. 1/Long Rest.","name":"Relentless Endurance","type":"feature","description":"Drop to 1 HP instead of 0. 1/Long Rest."}],"modifiers":[{"desc":"Drop to 1 HP instead of 0. 1/Long Rest.","name":"Relentless Endurance","type":"feature","description":"Drop to 1 HP instead of 0. 1/Long Rest."}]}],"choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","ability_bonuses":[],"language_options":2,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'orc'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'bb906264-2f49-4b86-8113-f3870cd3ef43';

-- Deep Gnome (deep-gnome)
update public.custom_races
   set data = $persona_content_migration${"id":"1d634545-cb80-4ff5-9e5b-06a16c6a8721","age":"Deep gnomes mature at about 25 and live 200 to 250 years.","desc":["Deep gnomes, or svirfneblin, live in the lightless caverns of the Underdark, far from their surface cousins. Wiry, wary, and gifted with earth magic, they are masters of hiding in stone and going unnoticed."],"name":"Deep Gnome","size":"Small","index":"deep-gnome","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid. You are also considered a gnome for any prerequisite or effect that requires you to be a gnome."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}]},{"desc":["Starting at 3rd level, you can cast the Disguise Self spell with this trait. Starting at 5th level, you can also cast the Nondetection spell with this trait, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Gift of the Svirfneblin","index":"gift-of-the-svirfneblin","effects":[{"name":"Disguise Self","type":"spell_access","spell":"Disguise Self","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Nondetection","type":"spell_access","spell":"Nondetection","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"desc":["You have advantage on Intelligence, Wisdom, and Charisma saving throws against spells."],"name":"Gnomish Magic Resistance","index":"gnomish-magic-resistance","effects":[{"name":"Advantage on saves: Intelligence","type":"advantage","value":1,"filter":"Intelligence","target":"saves"},{"name":"Advantage on saves: Wisdom","type":"advantage","value":1,"filter":"Wisdom","target":"saves"},{"name":"Advantage on saves: Charisma","type":"advantage","value":1,"filter":"Charisma","target":"saves"}]},{"desc":["When you make a Dexterity (Stealth) check, you can make the check with advantage. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Svirfneblin Camouflage","index":"svirfneblin-camouflage","effects":[{"desc":"Make a Stealth check with advantage. PB uses per Long Rest.","name":"Svirfneblin Camouflage","type":"feature","description":"Make a Stealth check with advantage. PB uses per Long Rest."}]}],"choices":[{"id":"deep-gnome-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"deep-gnome-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"deep-gnome-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; deep gnomes tend toward neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Small (about 3 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
