-- Duergar (duergar)
update public.custom_races
   set data = $persona_content_migration${"id":"ec3848f7-f2a6-43e2-bd1f-8af575a7f705","age":"Duergar mature at the same rate as humans but live about 350 years.","desc":["Duergar are dwarves whose ancestors were transformed by centuries of servitude to mind flayers in the Underdark. Grim and tireless, they retained the dwarven gift for stone and smithcraft and gained psionic powers of growth and invisibility."],"name":"Duergar","size":"Medium","index":"duergar","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid. You are also considered a dwarf for any prerequisite or effect that requires you to be a dwarf."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}]},{"desc":["Starting at 3rd level, you can cast the Enlarge/Reduce spell on yourself with this trait, without requiring a material component. Starting at 5th level, you can also cast the Invisibility spell on yourself with this trait, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Duergar Magic","index":"duergar-magic","effects":[{"name":"Enlarge/Reduce","type":"spell_access","spell":"Enlarge/Reduce","condition":"From level 3; self only, 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Invisibility","type":"spell_access","spell":"Invisibility","condition":"From level 5; self only, 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"desc":["You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."],"name":"Dwarven Resilience","index":"dwarven-resilience","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed or stunned condition on yourself."],"name":"Psionic Fortitude","index":"psionic-fortitude","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Advantage on saves: Stunned","type":"advantage","value":1,"filter":"Stunned","target":"saves"}]}],"choices":[{"id":"duergar-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"duergar-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"duergar-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; duergar tend toward lawful.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 4–5 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'duergar'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'ec3848f7-f2a6-43e2-bd1f-8af575a7f705';

-- Tortle (tortle)
update public.custom_races
   set data = $persona_content_migration${"id":"893dd54c-cfe7-4c74-a5ee-c8e2ea3e2c9f","age":"Tortles reach adulthood by 15 and live about 50 years.","desc":["Tortles are turtle-like humanoids who carry their homes on their backs. Born on beaches and raised to wander, they are patient, hardy survivors whose shells grant remarkable protection."],"name":"Tortle","size":"Small or Medium","index":"tortle","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You have claws that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Claws","index":"claws","effects":[{"die":"1d6","name":"Claws","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Slashing"}],"modifiers":[{"die":"1d6","name":"Claws","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Slashing"}]},{"desc":["You can hold your breath for up to 1 hour."],"name":"Hold Breath","index":"hold-breath","effects":[{"desc":"Hold your breath for up to 1 hour.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 1 hour."}],"modifiers":[{"desc":"Hold your breath for up to 1 hour.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 1 hour."}]},{"desc":["Your shell provides you a base AC of 17 (your Dexterity modifier doesn't affect this number). You can't wear light, medium, or heavy armor, but if you are using a shield, you can apply the shield's bonus as normal."],"name":"Natural Armor","index":"natural-armor","effects":[{"name":"Natural Armor","type":"set","value":17,"target":"ac"},{"desc":"Base AC 17 with no Dexterity modifier (the sheet adds Dex — subtract it manually); no armor can be worn, shields allowed.","name":"Natural Armor (flat)","type":"feature","description":"Base AC 17 with no Dexterity modifier (the sheet adds Dex — subtract it manually); no armor can be worn, shields allowed."}],"modifiers":[{"name":"Natural Armor","type":"set","value":17,"target":"ac"},{"desc":"Base AC 17 with no Dexterity modifier (the sheet adds Dex — subtract it manually); no armor can be worn, shields allowed.","name":"Natural Armor (flat)","type":"feature","description":"Base AC 17 with no Dexterity modifier (the sheet adds Dex — subtract it manually); no armor can be worn, shields allowed."}]},{"desc":["Thanks to your connection to the natural world, you have proficiency in two of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."],"name":"Nature's Intuition","index":"nature's-intuition","effects":[],"modifiers":[]},{"desc":["You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to your AC and have advantage on Strength and Constitution saving throws. While in your shell, you are prone, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge."],"name":"Shell Defense","index":"shell-defense","effects":[{"desc":"Withdraw into your shell: +4 AC, advantage on STR/CON saves, but prone, speed 0, disadvantage on DEX saves, no reactions. Bonus action to emerge.","name":"Shell Defense","type":"action","description":"Withdraw into your shell: +4 AC, advantage on STR/CON saves, but prone, speed 0, disadvantage on DEX saves, no reactions. Bonus action to emerge."}],"modifiers":[{"desc":"Withdraw into your shell: +4 AC, advantage on STR/CON saves, but prone, speed 0, disadvantage on DEX saves, no reactions. Bonus action to emerge.","name":"Shell Defense","type":"action","description":"Withdraw into your shell: +4 AC, advantage on STR/CON saves, but prone, speed 0, disadvantage on DEX saves, no reactions. Bonus action to emerge."}]}],"choices":[{"id":"tortle-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"tortle-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"tortle-skills","kind":"skill","count":2,"label":"Nature's Intuition skills","source":"race","options":["Animal Handling","Medicine","Nature","Perception","Stealth","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; tortles tend toward lawful good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'tortle'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '893dd54c-cfe7-4c74-a5ee-c8e2ea3e2c9f';

-- Kender (kender)
update public.custom_races
   set data = $persona_content_migration${"id":"90c755ab-1b8f-4a89-a43e-ac9e21308f5a","age":"Kender mature at the same rate as humans and live about a century.","desc":["Kender are a small, fearless people of Krynn, famed for their insatiable curiosity, their knack for \"finding\" other people's belongings, and taunts so infuriating that they can throw a foe off balance."],"name":"Kender","size":"Small","index":"kender","speed":30,"source":"Dragonlance: Shadow of the Dragon Queen","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You have advantage on saving throws you make to avoid or end the frightened condition on yourself. When you fail a saving throw to avoid or end the frightened condition on yourself, you can choose to succeed instead. Once you succeed on a saving throw in this way, you can't do so again until you finish a Long Rest."],"name":"Fearless","index":"fearless","effects":[{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"},{"desc":"Once per Long Rest, turn a failed save against the Frightened condition into a success.","name":"Fearless","type":"feature","description":"Once per Long Rest, turn a failed save against the Frightened condition into a success."}],"modifiers":[{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"},{"desc":"Once per Long Rest, turn a failed save against the Frightened condition into a success.","name":"Fearless","type":"feature","description":"Once per Long Rest, turn a failed save against the Frightened condition into a success."}]},{"desc":["Thanks to the mixture of fey magic and your natural curiosity, you gain proficiency with one of the following skills of your choice: Insight, Investigation, Sleight of Hand, Stealth, or Survival."],"name":"Kender Aptitude","index":"kender-aptitude","effects":[],"modifiers":[]},{"desc":["You have an extraordinary ability to fluster creatures. As a bonus action, you can unleash a string of provoking words at a creature within 60 feet of yourself. If the target can hear and understand you, it must succeed on a Wisdom saving throw (DC equals 8 + your proficiency bonus + your Charisma modifier) or have disadvantage on attack rolls against targets other than you until the start of your next turn. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Taunt","index":"taunt","effects":[{"desc":"A creature within 60 ft. makes a WIS save (8 + PB + CHA) or has disadvantage on attacks against others until your next turn. PB uses per Long Rest.","name":"Taunt","type":"bonus_action","description":"A creature within 60 ft. makes a WIS save (8 + PB + CHA) or has disadvantage on attacks against others until your next turn. PB uses per Long Rest."}],"modifiers":[{"desc":"A creature within 60 ft. makes a WIS save (8 + PB + CHA) or has disadvantage on attacks against others until your next turn. PB uses per Long Rest.","name":"Taunt","type":"bonus_action","description":"A creature within 60 ft. makes a WIS save (8 + PB + CHA) or has disadvantage on attacks against others until your next turn. PB uses per Long Rest."}]}],"choices":[{"id":"kender-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kender-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kender-skill","kind":"skill","count":1,"label":"Kender Aptitude skill","source":"race","options":["Insight","Investigation","Sleight of Hand","Stealth","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; kender lean toward chaotic.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Small (about 3–4 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'kender'),
       source = 'Dragonlance: Shadow of the Dragon Queen',
       migrated_at = now()
 where id = '90c755ab-1b8f-4a89-a43e-ac9e21308f5a';

-- Shadar-kai (shadar-kai)
update public.custom_races
   set data = $persona_content_migration${"id":"c8556c84-1ff3-42c5-9c6d-58c3918d05ce","age":"Shadar-kai reach physical maturity around 20 and can live to be 750 years old.","desc":["Shadar-kai are elves of the Shadowfell, bound to the Raven Queen. Long exposure to that gloomy plane has made them resistant to the necrotic energies of death and granted them the power to blink through shadow."],"name":"Shadar-kai","size":"Medium","index":"shadar-kai","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You have proficiency in the Perception skill."],"name":"Keen Senses","index":"keen-senses","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}]},{"desc":["You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. Whenever you finish this trance, you can gain two proficiencies that you don't have, each one with a weapon or a tool of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."],"name":"Trance","index":"trance","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}],"modifiers":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}]},{"desc":["As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. Starting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."],"name":"Blessing of the Raven Queen","index":"blessing-of-the-raven-queen","effects":[{"desc":"Teleport up to 30 ft.; from level 3, gain resistance to all damage until your next turn. PB uses per Long Rest.","name":"Blessing of the Raven Queen","type":"bonus_action","description":"Teleport up to 30 ft.; from level 3, gain resistance to all damage until your next turn. PB uses per Long Rest."}],"modifiers":[{"desc":"Teleport up to 30 ft.; from level 3, gain resistance to all damage until your next turn. PB uses per Long Rest.","name":"Blessing of the Raven Queen","type":"bonus_action","description":"Teleport up to 30 ft.; from level 3, gain resistance to all damage until your next turn. PB uses per Long Rest."}]},{"desc":["You have resistance to necrotic damage."],"name":"Necrotic Resistance","index":"necrotic-resistance","effects":[{"name":"Necrotic","type":"resistance","value":"Necrotic","condition":"","damage_type":"Necrotic"}],"modifiers":[{"name":"Necrotic","type":"resistance","value":"Necrotic","condition":"","damage_type":"Necrotic"}]}],"choices":[{"id":"shadar-kai-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"shadar-kai-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; shadar-kai tend toward neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'shadar-kai'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'c8556c84-1ff3-42c5-9c6d-58c3918d05ce';

-- Eladrin (eladrin)
update public.custom_races
   set data = $persona_content_migration${"id":"06fc8c7f-901c-4d7f-a9ce-939ca37d2af5","age":"Eladrin reach physical maturity around 20 and can live to be 750 years old.","desc":["Eladrin are elves native to the Feywild, a realm of beauty, unpredictable emotion, and boundless magic. Each eladrin is associated with one of the four seasons, and their mood and appearance shift with it — and with it the magic of their fey step."],"name":"Eladrin","size":"Medium","index":"eladrin","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You have proficiency in the Perception skill."],"name":"Keen Senses","index":"keen-senses","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}]},{"desc":["You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. Whenever you finish this trance, you can gain two proficiencies that you don't have, each one with a weapon or a tool of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."],"name":"Trance","index":"trance","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}],"modifiers":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}]},{"desc":["As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. When you reach 3rd level, your Fey Step gains an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race). Autumn: immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute, or until you or your companions deal any damage to the creatures. Winter: when you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn. Spring: when you use your Fey Step, you can touch one willing creature within 5 feet of you; that creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you. Summer: immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your Intelligence, Wisdom, or Charisma modifier (minimum of 1 damage)."],"name":"Fey Step","index":"fey-step","effects":[{"desc":"Teleport up to 30 ft.; from level 3 add your season's effect (Autumn charm, Winter fear, Spring swap, Summer fire). PB uses per Long Rest.","name":"Fey Step","type":"bonus_action","description":"Teleport up to 30 ft.; from level 3 add your season's effect (Autumn charm, Winter fear, Spring swap, Summer fire). PB uses per Long Rest."}],"modifiers":[{"desc":"Teleport up to 30 ft.; from level 3 add your season's effect (Autumn charm, Winter fear, Spring swap, Summer fire). PB uses per Long Rest.","name":"Fey Step","type":"bonus_action","description":"Teleport up to 30 ft.; from level 3 add your season's effect (Autumn charm, Winter fear, Spring swap, Summer fire). PB uses per Long Rest."}]},{"desc":["You can change your season whenever you finish a long rest. Choose Autumn (peace and goodwill), Winter (contemplation and dolor), Spring (cheerfulness and celebration), or Summer (boldness and aggression)."],"name":"Season","index":"season","effects":[],"modifiers":[]}],"choices":[{"id":"eladrin-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"eladrin-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"eladrin-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; eladrin are often chaotic.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
