-- Sea Elf (sea-elf)
update public.custom_races
   set data = $persona_content_migration${"id":"7992287c-54e2-4dfe-bab4-e5e2c2fae0c8","age":"Sea elves reach physical maturity around 20 and can live to be 750 years old.","desc":["Sea elves fell in love with the wild beauty of the ocean in the earliest days of the multiverse. They live in the deeps and along the coasts, breathing water as easily as air and speaking with the creatures of the sea."],"name":"Sea Elf","size":"Medium","index":"sea-elf","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You have proficiency in the Perception skill."],"name":"Keen Senses","index":"keen-senses","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}]},{"desc":["You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. Whenever you finish this trance, you can gain two proficiencies that you don't have, each one with a weapon or a tool of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."],"name":"Trance","index":"trance","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}],"modifiers":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest.","name":"Trance","type":"feature","description":"Long rest in 4 hours; afterwards gain two weapon/tool proficiencies until your next long rest."}]},{"desc":["You have a swimming speed of 30 feet, and you can breathe air and water."],"name":"Child of the Sea","index":"child-of-the-sea","effects":[{"desc":"Swim Speed 30 ft.; breathe air and water.","name":"Child of the Sea","type":"feature","description":"Swim Speed 30 ft.; breathe air and water."}],"modifiers":[{"desc":"Swim Speed 30 ft.; breathe air and water.","name":"Child of the Sea","type":"feature","description":"Swim Speed 30 ft.; breathe air and water."}]},{"desc":["Aquatic animals have an extraordinary affinity with your people. You can communicate simple ideas to any Beast that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."],"name":"Friend of the Sea","index":"friend-of-the-sea","effects":[{"desc":"Communicate simple ideas to Beasts with a swimming speed.","name":"Friend of the Sea","type":"feature","description":"Communicate simple ideas to Beasts with a swimming speed."}],"modifiers":[{"desc":"Communicate simple ideas to Beasts with a swimming speed.","name":"Friend of the Sea","type":"feature","description":"Communicate simple ideas to Beasts with a swimming speed."}]}],"choices":[{"id":"sea-elf-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"sea-elf-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"swim_speed":30,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'sea-elf'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '7992287c-54e2-4dfe-bab4-e5e2c2fae0c8';

-- Bugbear (bugbear)
update public.custom_races
   set data = $persona_content_migration${"id":"d168a156-9885-422f-88fc-350df32a48d0","age":"Bugbears reach adulthood at 16 and live up to 80 years.","desc":["Bugbears are hulking, hairy goblinoids with a fey origin. Despite their size they move with eerie stealth, their long arms give them unexpected reach, and they strike with devastating surprise."],"name":"Bugbear","size":"Medium","index":"bugbear","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."],"name":"Long-Limbed","index":"long-limbed","effects":[{"desc":"+5 ft. reach on melee attacks made on your turn.","name":"Long-Limbed","type":"feature","description":"+5 ft. reach on melee attacks made on your turn."}],"modifiers":[{"desc":"+5 ft. reach on melee attacks made on your turn.","name":"Long-Limbed","type":"feature","description":"+5 ft. reach on melee attacks made on your turn."}]},{"desc":["You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."],"name":"Powerful Build","index":"powerful-build","effects":[{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}],"modifiers":[{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}]},{"desc":["You are proficient in the Stealth skill. In addition, without squeezing, you can move through and stop in a space large enough for a Small creature."],"name":"Sneaky","index":"sneaky","effects":[{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"},{"desc":"Move through and stop in Small-sized spaces without squeezing.","name":"Sneaky","type":"feature","description":"Move through and stop in Small-sized spaces without squeezing."}],"modifiers":[{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"},{"desc":"Move through and stop in Small-sized spaces without squeezing.","name":"Sneaky","type":"feature","description":"Move through and stop in Small-sized spaces without squeezing."}]},{"desc":["If you hit a creature with an attack roll, the creature takes an extra 2d6 damage if it hasn't taken a turn yet in the current combat."],"name":"Surprise Attack","index":"surprise-attack","effects":[{"desc":"+2d6 damage against creatures that haven't taken a turn yet this combat.","name":"Surprise Attack","type":"feature","description":"+2d6 damage against creatures that haven't taken a turn yet this combat."}],"modifiers":[{"desc":"+2d6 damage against creatures that haven't taken a turn yet this combat.","name":"Surprise Attack","type":"feature","description":"+2d6 damage against creatures that haven't taken a turn yet this combat."}]}],"choices":[{"id":"bugbear-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"bugbear-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; bugbears often lean chaotic.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 6–8 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'bugbear'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'd168a156-9885-422f-88fc-350df32a48d0';

-- Goblin (goblin)
update public.custom_races
   set data = $persona_content_migration${"id":"17832d16-1ba1-4e4a-b49f-8d0944f24c4c","age":"Goblins reach adulthood at 8 and live up to 60 years.","desc":["Goblins are small, quick goblinoids with a fey heritage and a knack for survival. Fury drives their attacks on bigger foes, and nimble escape keeps them alive when the fight turns against them."],"name":"Goblin","size":"Small","index":"goblin","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."],"name":"Fury of the Small","index":"fury-of-the-small","effects":[{"desc":"Once per turn, +PB damage against a larger creature. PB uses per Long Rest.","name":"Fury of the Small","type":"feature","description":"Once per turn, +PB damage against a larger creature. PB uses per Long Rest."}],"modifiers":[{"desc":"Once per turn, +PB damage against a larger creature. PB uses per Long Rest.","name":"Fury of the Small","type":"feature","description":"Once per turn, +PB damage against a larger creature. PB uses per Long Rest."}]},{"desc":["You can take the Disengage or Hide action as a bonus action on each of your turns."],"name":"Nimble Escape","index":"nimble-escape","effects":[{"desc":"Disengage or Hide as a bonus action.","name":"Nimble Escape","type":"bonus_action","description":"Disengage or Hide as a bonus action."}],"modifiers":[{"desc":"Disengage or Hide as a bonus action.","name":"Nimble Escape","type":"bonus_action","description":"Disengage or Hide as a bonus action."}]}],"choices":[{"id":"goblin-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"goblin-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Small (about 3–4 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'goblin'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '17832d16-1ba1-4e4a-b49f-8d0944f24c4c';

-- Hobgoblin (hobgoblin)
update public.custom_races
   set data = $persona_content_migration${"id":"371bc11e-ac69-4e79-9684-6e76a37755a6","age":"Hobgoblins mature at the same rate as humans and live about as long.","desc":["Hobgoblins are disciplined goblinoids whose fey origins show in their gift for fellowship — they draw strength from allies and repay help in kind. Many form tight-knit war bands or legions, valuing honor and cooperation above all."],"name":"Hobgoblin","size":"Medium","index":"hobgoblin","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You can take the Help action as a bonus action. You can do so a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. Starting at 3rd level, choose one of the options below each time you take the Help action with this trait: Hospitality — you and the creature you help each gain a number of temporary hit points equal to 1d6 plus your proficiency bonus; Passage — you and the creature you help each increase your walking speeds by 10 feet until the start of your next turn; Spite — until the start of your next turn, the first time the creature you help hits a target with an attack roll, that target has disadvantage on the next attack roll it makes within the next minute."],"name":"Fey Gift","index":"fey-gift","effects":[{"desc":"Help as a bonus action; from level 3 add Hospitality (temp HP), Passage (+10 ft. speed), or Spite (target disadvantage). PB uses per Long Rest.","name":"Fey Gift","type":"bonus_action","description":"Help as a bonus action; from level 3 add Hospitality (temp HP), Passage (+10 ft. speed), or Spite (target disadvantage). PB uses per Long Rest."}],"modifiers":[{"desc":"Help as a bonus action; from level 3 add Hospitality (temp HP), Passage (+10 ft. speed), or Spite (target disadvantage). PB uses per Long Rest.","name":"Fey Gift","type":"bonus_action","description":"Help as a bonus action; from level 3 add Hospitality (temp HP), Passage (+10 ft. speed), or Spite (target disadvantage). PB uses per Long Rest."}]},{"desc":["If you miss with an attack roll or fail an ability check or a saving throw, you can draw on your bonds of reciprocity to gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +3). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."],"name":"Fortune from the Many","index":"fortune-from-the-many","effects":[{"desc":"Add up to +3 (one per visible ally within 30 ft.) to a missed attack, failed check, or failed save. PB uses per Long Rest.","name":"Fortune from the Many","type":"feature","description":"Add up to +3 (one per visible ally within 30 ft.) to a missed attack, failed check, or failed save. PB uses per Long Rest."}],"modifiers":[{"desc":"Add up to +3 (one per visible ally within 30 ft.) to a missed attack, failed check, or failed save. PB uses per Long Rest.","name":"Fortune from the Many","type":"feature","description":"Add up to +3 (one per visible ally within 30 ft.) to a missed attack, failed check, or failed save. PB uses per Long Rest."}]}],"choices":[{"id":"hobgoblin-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"hobgoblin-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; hobgoblins tend toward lawful.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'hobgoblin'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '371bc11e-ac69-4e79-9684-6e76a37755a6';

-- Kobold (kobold)
update public.custom_races
   set data = $persona_content_migration${"id":"17d7c368-a555-4df2-9975-d9277e0d6660","age":"Kobolds reach adulthood at 6 and can live up to 120 years.","desc":["Kobolds are small, draconic humanoids who claim kinship with dragons. Clever and cooperative, they fight best in packs, and many carry a spark of their ancestors' legacy — a frightening roar, a knack for crafting, or a touch of magic."],"name":"Kobold","size":"Small","index":"kobold","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["As a bonus action, you let out a cry at your enemies within 10 feet of you. Until the start of your next turn, you and your allies have advantage on attack rolls against any of those enemies who could hear you. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."],"name":"Draconic Cry","index":"draconic-cry","effects":[{"desc":"You and allies gain advantage on attacks against enemies within 10 ft. who heard you, until your next turn. PB uses per Long Rest.","name":"Draconic Cry","type":"bonus_action","description":"You and allies gain advantage on attacks against enemies within 10 ft. who heard you, until your next turn. PB uses per Long Rest."}],"modifiers":[{"desc":"You and allies gain advantage on attacks against enemies within 10 ft. who heard you, until your next turn. PB uses per Long Rest.","name":"Draconic Cry","type":"bonus_action","description":"You and allies gain advantage on attacks against enemies within 10 ft. who heard you, until your next turn. PB uses per Long Rest."}]},{"desc":["Kobolds' connection to dragons can manifest in unpredictable ways. Choose one legacy (see ancestries): Craftiness, Defiance, or Draconic Sorcery."],"name":"Kobold Legacy","index":"kobold-legacy","effects":[],"modifiers":[]}],"choices":[{"id":"kobold-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kobold-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kobold-legacy","kind":"ancestry","count":1,"label":"Kobold Legacy","source":"race","options":[{"desc":"You have proficiency in one of the following skills of your choice: Arcana, Investigation, Medicine, Sleight of Hand, or Survival.","name":"Craftiness","effects":[{"name":"Craftiness","type":"proficiency_choice","count":1,"options":["Arcana","Investigation","Medicine","Sleight of Hand","Survival"],"category":"skill"}]},{"desc":"You have advantage on saving throws to avoid or end the frightened condition on yourself.","name":"Defiance","effects":[{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}]},{"desc":"You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for it.","name":"Draconic Sorcery","effects":[{"name":"Draconic Sorcery cantrip","type":"spell_access","count":1,"level":0,"condition":"Cantrip","filter_class":"sorcerer"}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Small (about 2–3 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'kobold'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '17d7c368-a555-4df2-9975-d9277e0d6660';

-- Gem Dragonborn (gem-dragonborn)
update public.custom_races
   set data = $persona_content_migration${"id":"d2973cc6-deb6-436f-a7c3-22d4f981107f","age":"Dragonborn reach adulthood by 15 and live about 80 years.","desc":["Gem dragonborn descend from amethyst, crystal, emerald, sapphire, and topaz dragons. Their crystalline scales glitter, and their minds are touched by psionic power that lets them speak telepathically and, in time, rise on wings of crystal light."],"name":"Gem Dragonborn","size":"Medium","index":"gem-dragonborn","speed":30,"source":"Fizban's Treasury of Dragons","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You trace your ancestry to a gem dragon. Choose your ancestor (see ancestries); its damage type determines your Breath Weapon and Draconic Resistance."],"name":"Gem Ancestry","index":"gem-ancestry","effects":[],"modifiers":[]},{"desc":["When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Breath Weapon","index":"breath-weapon","effects":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}],"modifiers":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}]},{"desc":["You have resistance to the damage type associated with your ancestry."],"name":"Draconic Resistance","index":"draconic-resistance","effects":[],"modifiers":[]},{"desc":["You can telepathically speak to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand your telepathic messages, but the creature must be able to understand at least one language or be telepathic itself."],"name":"Psionic Mind","index":"psionic-mind","effects":[{"desc":"Telepathy with creatures you can see within 30 ft.","name":"Psionic Mind","type":"feature","description":"Telepathy with creatures you can see within 30 ft."}],"modifiers":[{"desc":"Telepathy with creatures you can see within 30 ft.","name":"Psionic Mind","type":"feature","description":"Telepathy with creatures you can see within 30 ft."}]},{"desc":["Starting at 5th level, you can use a bonus action to manifest spectral wings on your body. These wings last for 1 minute. For the duration, you gain a flying speed equal to your walking speed. Once you use this trait, you can't do so again until you finish a Long Rest."],"name":"Gem Flight","index":"gem-flight","effects":[{"desc":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 1 minute. 1/Long Rest.","name":"Gem Flight","type":"bonus_action","description":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 1 minute. 1/Long Rest."}],"modifiers":[{"desc":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 1 minute. 1/Long Rest.","name":"Gem Flight","type":"bonus_action","description":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 1 minute. 1/Long Rest."}]}],"choices":[{"id":"gem-dragonborn-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"gem-dragonborn-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"gem-ancestry","kind":"ancestry","count":1,"label":"Draconic Ancestry","source":"race","options":[{"desc":"Amethyst dragon ancestry: Force breath weapon and resistance.","name":"Amethyst (Force)","effects":[{"name":"Force Resistance","type":"resistance","value":"Force","damage_type":"Force"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Force damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Force)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Force damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Crystal dragon ancestry: Radiant breath weapon and resistance.","name":"Crystal (Radiant)","effects":[{"name":"Radiant Resistance","type":"resistance","value":"Radiant","damage_type":"Radiant"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Radiant damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Radiant)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Radiant damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Emerald dragon ancestry: Psychic breath weapon and resistance.","name":"Emerald (Psychic)","effects":[{"name":"Psychic Resistance","type":"resistance","value":"Psychic","damage_type":"Psychic"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Psychic damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Psychic)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Psychic damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Sapphire dragon ancestry: Thunder breath weapon and resistance.","name":"Sapphire (Thunder)","effects":[{"name":"Thunder Resistance","type":"resistance","value":"Thunder","damage_type":"Thunder"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Thunder damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Thunder)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Thunder damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Topaz dragon ancestry: Necrotic breath weapon and resistance.","name":"Topaz (Necrotic)","effects":[{"name":"Necrotic Resistance","type":"resistance","value":"Necrotic","damage_type":"Necrotic"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Necrotic damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Necrotic)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Necrotic damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Draconic","index":"draconic"}],"is_homebrew":false,"language_desc":"Common, Draconic","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
