 where id = 'd2973cc6-deb6-436f-a7c3-22d4f981107f';

-- Yuan-ti (yuan-ti)
update public.custom_races
   set data = $persona_content_migration${"id":"1392a507-bb14-4749-bb46-6b1f99e3b8db","age":"Yuan-ti mature at the same rate as humans and live 80 to 120 years.","desc":["Yuan-ti are serpentfolk, the heirs of a human empire whose rituals transformed them into something no longer human. Cool, calculating, and resistant to both poison and magic, they can shed their skin and call on serpentine sorcery."],"name":"Yuan-ti","size":"Medium","index":"yuan-ti","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws against spells."],"name":"Magic Resistance","index":"magic-resistance","effects":[{"name":"Advantage on saves: Spells","type":"advantage","value":1,"filter":"Spells","target":"saves"}]},{"desc":["You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."],"name":"Poison Resilience","index":"poison-resilience","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}]},{"desc":["You know the Poison Spray cantrip. You can cast Animal Friendship an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast Suggestion with this trait. Once you cast it, you can't do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Serpentine Spellcasting","index":"serpentine-spellcasting","effects":[{"name":"Poison Spray","type":"spell_access","spell":"Poison Spray","condition":"Cantrip"},{"name":"Animal Friendship","type":"spell_access","spell":"Animal Friendship","condition":"At will, snakes only"},{"name":"Suggestion","type":"spell_access","spell":"Suggestion","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[{"id":"yuan-ti-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"yuan-ti-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"yuan-ti-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; yuan-ti often lean toward evil.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[],"schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'yuan-ti'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '1392a507-bb14-4749-bb46-6b1f99e3b8db';

-- Tabaxi (tabaxi)
update public.custom_races
   set data = $persona_content_migration${"id":"c6dd9d47-db60-4dce-802c-5393935590f8","age":"Tabaxi have lifespans equivalent to humans.","desc":["Tabaxi are feline humanoids driven by curiosity. Born in distant lands, many of them leave home to collect stories, secrets, and treasures, trusting their claws, agility, and sharp senses to see them through."],"name":"Tabaxi","size":"Small or Medium","index":"tabaxi","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You can use your claws to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike. Because of your claws, you have a climbing speed equal to your walking speed."],"name":"Cat's Claws","index":"cat's-claws","effects":[{"die":"1d6","name":"Cat's Claws","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Slashing"}],"modifiers":[{"die":"1d6","name":"Cat's Claws","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Slashing"}]},{"desc":["You have proficiency in the Perception and Stealth skills."],"name":"Cat's Talent","index":"cat's-talent","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"},{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"},{"type":"proficiency","target":"Perception","category":"skill"},{"type":"proficiency","target":"Stealth","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"},{"name":"Stealth","type":"proficiency","value":"Stealth","target":"Stealth","category":"skill"}]},{"desc":["Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."],"name":"Feline Agility","index":"feline-agility","effects":[{"desc":"Double your speed for a turn; recharges after a turn in which you move 0 feet.","name":"Feline Agility","type":"feature","description":"Double your speed for a turn; recharges after a turn in which you move 0 feet."}],"modifiers":[{"desc":"Double your speed for a turn; recharges after a turn in which you move 0 feet.","name":"Feline Agility","type":"feature","description":"Double your speed for a turn; recharges after a turn in which you move 0 feet."}]}],"choices":[{"id":"tabaxi-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"tabaxi-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; tabaxi tend toward chaotic.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"climb_speed":30,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
