-- Shifter (shifter)
update public.custom_races
   set data = $persona_content_migration${"id":"05016336-b391-4468-a795-c9e4cd3217b6","age":"Shifters mature and age at about the same rate as humans.","desc":["Shifters are sometimes called weretouched, as their lineage traces back to lycanthropes. They can't fully change shape, but they can temporarily enhance their animalistic features by shifting — becoming tougher, faster, fiercer, or keener-sensed."],"name":"Shifter","size":"Medium","index":"shifter","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["Channeling the beast within, you have proficiency in one of the following skills of your choice: Acrobatics, Athletics, Intimidation, or Survival."],"name":"Bestial Instincts","index":"bestial-instincts","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus. You can shift a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest. Whenever you shift, you also gain an additional benefit based on your chosen shifter trait (see subraces)."],"name":"Shifting","index":"shifting","effects":[{"desc":"Shift for 1 minute: gain 2 × PB temp HP plus your subrace's shifting benefit. PB uses per Long Rest.","name":"Shifting","type":"bonus_action","description":"Shift for 1 minute: gain 2 × PB temp HP plus your subrace's shifting benefit. PB uses per Long Rest."}],"modifiers":[{"desc":"Shift for 1 minute: gain 2 × PB temp HP plus your subrace's shifting benefit. PB uses per Long Rest.","name":"Shifting","type":"bonus_action","description":"Shift for 1 minute: gain 2 × PB temp HP plus your subrace's shifting benefit. PB uses per Long Rest."}]}],"choices":[{"id":"shifter-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"shifter-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"shifter-skill","kind":"skill","count":1,"label":"Bestial Instincts skill","source":"race","options":["Acrobatics","Athletics","Intimidation","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; shifters tend toward neutrality.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[{"desc":["Beasthide shifters are stalwart and tough, taking on the hide of a bear or boar."],"name":"Beasthide","index":"beasthide","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Whenever you shift, you gain 1d6 additional temporary hit points. While shifted, you have a +1 bonus to your Armor Class."],"name":"Beasthide Shifting","index":"beasthide-shifting","effects":[{"desc":"+1d6 extra temp HP when shifting; +1 AC while shifted.","name":"Beasthide Shifting","type":"feature","description":"+1d6 extra temp HP when shifting; +1 AC while shifted."}],"modifiers":[{"desc":"+1d6 extra temp HP when shifting; +1 AC while shifted.","name":"Beasthide Shifting","type":"feature","description":"+1d6 extra temp HP when shifting; +1 AC while shifted."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Longtooth shifters are ferocious, their jaws elongating into a fanged maw."],"name":"Longtooth","index":"longtooth","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["While shifted, you can use your elongated fangs to make an unarmed strike as a bonus action. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Longtooth Shifting","index":"longtooth-shifting","effects":[{"desc":"While shifted, make an unarmed strike with your fangs (1d6 + STR piercing).","name":"Longtooth Shifting","type":"bonus_action","description":"While shifted, make an unarmed strike with your fangs (1d6 + STR piercing)."}],"modifiers":[{"desc":"While shifted, make an unarmed strike with your fangs (1d6 + STR piercing).","name":"Longtooth Shifting","type":"bonus_action","description":"While shifted, make an unarmed strike with your fangs (1d6 + STR piercing)."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Swiftstride shifters are graceful and quick, evading foes with ease."],"name":"Swiftstride","index":"swiftstride","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke opportunity attacks."],"name":"Swiftstride Shifting","index":"swiftstride-shifting","effects":[{"desc":"While shifted: +10 ft. speed, and a reaction to move 10 ft. when a creature ends its turn within 5 ft.","name":"Swiftstride Shifting","type":"feature","description":"While shifted: +10 ft. speed, and a reaction to move 10 ft. when a creature ends its turn within 5 ft."}],"modifiers":[{"desc":"While shifted: +10 ft. speed, and a reaction to move 10 ft. when a creature ends its turn within 5 ft.","name":"Swiftstride Shifting","type":"feature","description":"While shifted: +10 ft. speed, and a reaction to move 10 ft. when a creature ends its turn within 5 ft."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Wildhunt shifters are sharp-eyed trackers who never lose their prey."],"name":"Wildhunt","index":"wildhunt","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you, unless you're incapacitated."],"name":"Wildhunt Shifting","index":"wildhunt-shifting","effects":[{"desc":"While shifted: advantage on Wisdom checks; creatures within 30 ft. can't attack you with advantage.","name":"Wildhunt Shifting","type":"feature","description":"While shifted: advantage on Wisdom checks; creatures within 30 ft. can't attack you with advantage."}],"modifiers":[{"desc":"While shifted: advantage on Wisdom checks; creatures within 30 ft. can't attack you with advantage.","name":"Wildhunt Shifting","type":"feature","description":"While shifted: advantage on Wisdom checks; creatures within 30 ft. can't attack you with advantage."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'shifter'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '05016336-b391-4468-a795-c9e4cd3217b6';

-- Plasmoid (plasmoid)
update public.custom_races
   set data = $persona_content_migration${"id":"d56aa116-c565-4ffd-a232-bc319167867d","age":"Plasmoids mature and age at about the same rate as humans.","desc":["Plasmoids are amorphous beings who can take a roughly humanoid shape at will. Their bodies are made of flexible, resilient ooze, letting them squeeze through narrow gaps, hold their breath for an hour, and shrug off acid and poison."],"name":"Plasmoid","size":"Small or Medium","index":"plasmoid","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are an Ooze."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Ooze (not Humanoid).","name":"Ooze","type":"feature","description":"Your creature type is Ooze (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Ooze (not Humanoid).","name":"Ooze","type":"feature","description":"Your creature type is Ooze (not Humanoid)."}]},{"desc":["You can squeeze through a space as narrow as 1 inch wide, provided you are wearing and carrying nothing. You have advantage on ability checks you make to initiate or escape a grapple."],"name":"Amorphous","index":"amorphous","effects":[{"desc":"Squeeze through 1-inch gaps (unequipped); advantage on checks to initiate or escape a grapple.","name":"Amorphous","type":"feature","description":"Squeeze through 1-inch gaps (unequipped); advantage on checks to initiate or escape a grapple."}],"modifiers":[{"desc":"Squeeze through 1-inch gaps (unequipped); advantage on checks to initiate or escape a grapple.","name":"Amorphous","type":"feature","description":"Squeeze through 1-inch gaps (unequipped); advantage on checks to initiate or escape a grapple."}]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You can hold your breath for 1 hour."],"name":"Hold Breath","index":"hold-breath","effects":[{"desc":"Hold your breath for up to 1 hour.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 1 hour."}],"modifiers":[{"desc":"Hold your breath for up to 1 hour.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 1 hour."}]},{"desc":["You have resistance to acid and poison damage, and you have advantage on saving throws against being poisoned."],"name":"Natural Resilience","index":"natural-resilience","effects":[{"name":"Acid","type":"resistance","value":"Acid","condition":"","damage_type":"Acid"},{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}],"modifiers":[{"name":"Acid","type":"resistance","value":"Acid","condition":"","damage_type":"Acid"},{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}]},{"desc":["As an action, you can reshape your body to give yourself a head, one or two arms, one or two legs, and makeshift hands and feet, or you can revert to a limbless blob. While you have a humanlike shape, you can wear clothing and armor made for a Humanoid of your size. As a bonus action, you can extrude a pseudopod that is up to 6 inches wide and 10 feet long or reabsorb it into your body. As part of the same bonus action, you can use this pseudopod to manipulate an object, open or close a door or container, or pick up or set down a Tiny object. The pseudopod contains no sensory organs and can't attack, activate magic items, or lift more than 10 pounds."],"name":"Shape Self","index":"shape-self","effects":[{"desc":"Reshape into a humanlike form or a blob.","name":"Shape Self","type":"action","description":"Reshape into a humanlike form or a blob."},{"desc":"Extrude or reabsorb a 10-ft. pseudopod to manipulate objects.","name":"Pseudopod","type":"bonus_action","description":"Extrude or reabsorb a 10-ft. pseudopod to manipulate objects."}],"modifiers":[{"desc":"Reshape into a humanlike form or a blob.","name":"Shape Self","type":"action","description":"Reshape into a humanlike form or a blob."},{"desc":"Extrude or reabsorb a 10-ft. pseudopod to manipulate objects.","name":"Pseudopod","type":"bonus_action","description":"Extrude or reabsorb a 10-ft. pseudopod to manipulate objects."}]}],"choices":[{"id":"plasmoid-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"plasmoid-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
