-- Metallic Dragonborn (metallic-dragonborn)
update public.custom_races
   set data = $persona_content_migration${"id":"07ec448b-5da4-431f-8581-cc2b3f20df58","age":"Dragonborn reach adulthood by 15 and live about 80 years.","desc":["Metallic dragonborn descend from brass, bronze, copper, gold, and silver dragons. Their burnished scales shine like polished metal, and alongside their elemental breath they inherit a second, subtler breath that can repel or enfeeble foes."],"name":"Metallic Dragonborn","size":"Medium","index":"metallic-dragonborn","speed":30,"source":"Fizban's Treasury of Dragons","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You trace your ancestry to a metallic dragon. Choose your ancestor (see ancestries); its damage type determines your Breath Weapon and Draconic Resistance."],"name":"Metallic Ancestry","index":"metallic-ancestry","effects":[],"modifiers":[]},{"desc":["When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Breath Weapon","index":"breath-weapon","effects":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}],"modifiers":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}]},{"desc":["You have resistance to the damage type associated with your ancestry."],"name":"Draconic Resistance","index":"draconic-resistance","effects":[],"modifiers":[]},{"desc":["At 5th level, you gain a second breath weapon. When you take the Attack action on your turn, you can replace one of your attacks with an exhalation in a 15-foot cone. The save DC for this breath is 8 + your Constitution modifier + your proficiency bonus. Whenever you use this trait, choose one: Enervating Breath — each creature in the cone must succeed on a Constitution saving throw or become incapacitated until the start of your next turn; or Repulsion Breath — each creature in the cone must succeed on a Strength saving throw or be pushed 20 feet away from you and be knocked prone. Once you use your Metallic Breath Weapon, you can't do so again until you finish a Long Rest."],"name":"Metallic Breath Weapon","index":"metallic-breath-weapon","effects":[{"desc":"From level 5: replace an attack with a 15-ft. cone — Enervating (CON save or incapacitated) or Repulsion (STR save or pushed 20 ft. and prone). 1/Long Rest.","name":"Metallic Breath Weapon","type":"feature","description":"From level 5: replace an attack with a 15-ft. cone — Enervating (CON save or incapacitated) or Repulsion (STR save or pushed 20 ft. and prone). 1/Long Rest."}],"modifiers":[{"desc":"From level 5: replace an attack with a 15-ft. cone — Enervating (CON save or incapacitated) or Repulsion (STR save or pushed 20 ft. and prone). 1/Long Rest.","name":"Metallic Breath Weapon","type":"feature","description":"From level 5: replace an attack with a 15-ft. cone — Enervating (CON save or incapacitated) or Repulsion (STR save or pushed 20 ft. and prone). 1/Long Rest."}]}],"choices":[{"id":"metallic-dragonborn-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"metallic-dragonborn-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"metallic-ancestry","kind":"ancestry","count":1,"label":"Draconic Ancestry","source":"race","options":[{"desc":"Brass dragon ancestry: Fire breath weapon and resistance.","name":"Brass (Fire)","effects":[{"name":"Fire Resistance","type":"resistance","value":"Fire","damage_type":"Fire"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Fire)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Bronze dragon ancestry: Lightning breath weapon and resistance.","name":"Bronze (Lightning)","effects":[{"name":"Lightning Resistance","type":"resistance","value":"Lightning","damage_type":"Lightning"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Lightning damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Lightning)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Lightning damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Copper dragon ancestry: Acid breath weapon and resistance.","name":"Copper (Acid)","effects":[{"name":"Acid Resistance","type":"resistance","value":"Acid","damage_type":"Acid"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Acid damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Acid)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Acid damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Gold dragon ancestry: Fire breath weapon and resistance.","name":"Gold (Fire)","effects":[{"name":"Fire Resistance","type":"resistance","value":"Fire","damage_type":"Fire"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Fire)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Silver dragon ancestry: Cold breath weapon and resistance.","name":"Silver (Cold)","effects":[{"name":"Cold Resistance","type":"resistance","value":"Cold","damage_type":"Cold"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Cold damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Cold)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Cold damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Draconic","index":"draconic"}],"is_homebrew":false,"language_desc":"Common, Draconic","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
