 where id = '07ec448b-5da4-431f-8581-cc2b3f20df58';

-- Half-Elf (half-elf)
update public.custom_races
   set data = $persona_content_migration${"id":"3f84e2d1-b67b-4079-bbba-f115b367cbff","age":"Half-elves mature at the same rate humans do and reach adulthood around 20; they live much longer than humans, often exceeding 180 years.","desc":["Walking in two worlds but truly belonging to neither, half-elves combine what some say are the best qualities of their elf and human parents: human curiosity, inventiveness, and ambition tempered by the refined senses, love of nature, and artistic tastes of the elves."],"name":"Half-Elf","size":"Medium","index":"half-elf","speed":30,"source":"Player's Handbook (2014)","traits":[{"desc":["Your Charisma score increases by 2, and two other ability scores of your choice increase by 1 (or, using the flexible rule, increase one score by 2 and another by 1)."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["Thanks to your elf blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws against being charmed, and magic can't put you to sleep."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"}]},{"desc":["You gain proficiency in two skills of your choice."],"name":"Skill Versatility","index":"skill-versatility","effects":[],"modifiers":[]}],"choices":[{"id":"half-elf-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"half-elf-asi-1","kind":"ability","count":2,"label":"+1 to 2 ability scores","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"half-elf-skills","kind":"skill","count":2,"source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]},{"id":"half-elf-asi","kind":"ability","count":2,"amount":1,"source":"race","options":["str","dex","con","int","wis"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; half-elves share the chaotic bent of their elven heritage.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Elvish","index":"elvish"}],"is_homebrew":false,"language_desc":"Common, Elvish and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
