-- Minotaur (minotaur)
update public.custom_races
   set data = $persona_content_migration${"id":"a7b6ffd5-1d33-40c9-be9a-b4ba2fddec52","age":"Minotaurs mature and age at about the same rate as humans.","desc":["Minotaurs are barrel-chested humanoids with the heads of bulls and a thunderous charge. Across the multiverse they are found as raiders, soldiers, and guardians of labyrinths, and they carry an imposing presence wherever they go."],"name":"Minotaur","size":"Medium","index":"minotaur","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You have horns that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier piercing damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Horns","index":"horns","effects":[{"die":"1d6","name":"Horns","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Piercing"}],"modifiers":[{"die":"1d6","name":"Horns","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Piercing"}]},{"desc":["Immediately after you take the Dash action on your turn and move at least 20 feet, you can make one attack with your Horns as a bonus action."],"name":"Goring Rush","index":"goring-rush","effects":[{"desc":"After Dashing and moving 20+ ft., make one Horns attack.","name":"Goring Rush","type":"bonus_action","description":"After Dashing and moving 20+ ft., make one Horns attack."}],"modifiers":[{"desc":"After Dashing and moving 20+ ft., make one Horns attack.","name":"Goring Rush","type":"bonus_action","description":"After Dashing and moving 20+ ft., make one Horns attack."}]},{"desc":["Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to push that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."],"name":"Hammering Horns","index":"hammering-horns","effects":[{"desc":"After a melee hit, push the target up to 10 ft. (STR save DC 8 + PB + STR).","name":"Hammering Horns","type":"bonus_action","description":"After a melee hit, push the target up to 10 ft. (STR save DC 8 + PB + STR)."}],"modifiers":[{"desc":"After a melee hit, push the target up to 10 ft. (STR save DC 8 + PB + STR).","name":"Hammering Horns","type":"bonus_action","description":"After a melee hit, push the target up to 10 ft. (STR save DC 8 + PB + STR)."}]},{"desc":["You have proficiency in one of the following skills of your choice: Intimidation or Persuasion."],"name":"Imposing Presence","index":"imposing-presence","effects":[],"modifiers":[]}],"choices":[{"id":"minotaur-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"minotaur-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"minotaur-skill","kind":"skill","count":1,"label":"Imposing Presence skill","source":"race","options":["Intimidation","Persuasion"]},{"id":"minotaur-imposing-presence","kind":"skill","count":1,"source":"race","options":["Intimidation","Persuasion"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
