-- Dragonborn (dragonborn)
update public.custom_races
   set data = $persona_content_migration${"id":"d1ba8953-91bf-4693-be20-50170a7ecd28","age":"Dragonborn mature quickly, reaching adulthood by 15, and live about 80 years.","desc":["The ancestors of dragonborn hatched from the eggs of chromatic and metallic dragons. Their scales, breath weapon, and draconic resilience reflect that ancestry, and many dragonborn have become legendary for their honor and their fierce loyalty to clan."],"name":"Dragonborn","size":"Medium","index":"dragonborn","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["Your lineage stems from a dragon progenitor. Choose the kind of dragon from the Draconic Ancestors table. Your choice affects your Breath Weapon and Damage Resistance traits as well as your appearance."],"name":"Draconic Ancestry","index":"draconic-ancestry","effects":[],"modifiers":[]},{"desc":["When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 damage of the type determined by your Draconic Ancestry trait. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10). You can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Breath Weapon","index":"breath-weapon","effects":[{"desc":"Replace one attack with a 15-ft. Cone or 30-ft. Line: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. Cone or 30-ft. Line: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}],"modifiers":[{"desc":"Replace one attack with a 15-ft. Cone or 30-ft. Line: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. Cone or 30-ft. Line: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":["You have Resistance to the damage type determined by your Draconic Ancestry trait."],"name":"Damage Resistance","index":"damage-resistance","effects":[],"modifiers":[]},{"desc":["You have Darkvision with a range of 60 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["When you reach character level 5, you can channel draconic magic to give yourself temporary flight. As a Bonus Action, you sprout spectral wings on your back that last for 10 minutes or until you retract the wings (no action required) or have the Incapacitated condition. During that time, you have a Fly Speed equal to your Speed. Your wings appear to be made of the same energy as your Breath Weapon. Once you use this trait, you can't use it again until you finish a Long Rest."],"name":"Draconic Flight","index":"draconic-flight","effects":[{"desc":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 10 minutes. 1/Long Rest.","name":"Draconic Flight","type":"bonus_action","description":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 10 minutes. 1/Long Rest."}],"modifiers":[{"desc":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 10 minutes. 1/Long Rest.","name":"Draconic Flight","type":"bonus_action","description":"From level 5: spectral wings grant a Fly Speed equal to your Speed for 10 minutes. 1/Long Rest."}]}],"choices":[{"id":"dragonborn-ancestry","kind":"ancestry","count":1,"source":"race","options":[{"name":"Black","effects":[{"type":"resistance","value":"Acid","damage_type":"Acid"}]},{"name":"Blue","effects":[{"type":"resistance","value":"Lightning","damage_type":"Lightning"}]},{"name":"Brass","effects":[{"type":"resistance","value":"Fire","damage_type":"Fire"}]},{"name":"Bronze","effects":[{"type":"resistance","value":"Lightning","damage_type":"Lightning"}]},{"name":"Copper","effects":[{"type":"resistance","value":"Acid","damage_type":"Acid"}]},{"name":"Gold","effects":[{"type":"resistance","value":"Fire","damage_type":"Fire"}]},{"name":"Green","effects":[{"type":"resistance","value":"Poison","damage_type":"Poison"}]},{"name":"Red","effects":[{"type":"resistance","value":"Fire","damage_type":"Fire"}]},{"name":"Silver","effects":[{"type":"resistance","value":"Cold","damage_type":"Cold"}]},{"name":"White","effects":[{"type":"resistance","value":"Cold","damage_type":"Cold"}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; many dragonborn value honor and tend toward law.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 5–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'dragonborn'),
       source = 'Player''s Handbook (2024)',
