-- Dwarf (dwarf)
update public.custom_races
   set data = $persona_content_migration${"id":"d61fc8aa-ee08-4746-963f-42a53fbcf40e","age":"Dwarves mature at the same rate as humans but live about 350 years.","desc":["Dwarves were raised from the earth in the elder days by a deity of the forge. Squat, sturdy, and strong, they have an affinity for stone and metal, and they live for centuries — long enough to see their great halls and clan traditions outlast kingdoms."],"name":"Dwarf","size":"Medium","index":"dwarf","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Darkvision with a range of 120 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"}]},{"desc":["You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition."],"name":"Dwarven Resilience","index":"dwarven-resilience","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}],"modifiers":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"}]},{"desc":["Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level."],"name":"Dwarven Toughness","index":"dwarven-toughness","effects":[{"name":"HP per level","type":"bonus","value":1,"target":"hp_per_level"}],"modifiers":[{"name":"HP per level","type":"bonus","value":1,"target":"hp_per_level"}]},{"desc":["As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes. You must be on a stone surface or touching a stone surface to use this Tremorsense. The stone can be natural or worked. You can use this Bonus Action a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Stonecunning","index":"stonecunning","effects":[{"desc":"Gain Tremorsense 60 ft. for 10 minutes while on or touching stone. PB uses per Long Rest.","name":"Stonecunning","type":"bonus_action","description":"Gain Tremorsense 60 ft. for 10 minutes while on or touching stone. PB uses per Long Rest."}],"modifiers":[{"desc":"Gain Tremorsense 60 ft. for 10 minutes while on or touching stone. PB uses per Long Rest.","name":"Stonecunning","type":"bonus_action","description":"Gain Tremorsense 60 ft. for 10 minutes while on or touching stone. PB uses per Long Rest."}]}],"choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most dwarves lean toward law.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 4–5 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'dwarf'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'd61fc8aa-ee08-4746-963f-42a53fbcf40e';

-- Aasimar (aasimar)
update public.custom_races
   set data = $persona_content_migration${"id":"5d23406a-0028-4953-ad1d-d90ee5191178","age":"Aasimar mature at the same rate as humans and can live up to 160 years.","desc":["Aasimar are mortals who carry a spark of the Upper Planes within their souls. Whether descended from an angelic being or infused with celestial power, they can unleash that light in a moment of revelation — manifesting wings, a necrotic shroud, or a searing inner radiance."],"name":"Aasimar","size":"Small or Medium","index":"aasimar","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Resistance to Necrotic damage and Radiant damage."],"name":"Celestial Resistance","index":"celestial-resistance","effects":[{"name":"Necrotic","type":"resistance","value":"Necrotic","condition":"","damage_type":"Necrotic"},{"name":"Radiant","type":"resistance","value":"Radiant","condition":"","damage_type":"Radiant"}],"modifiers":[{"name":"Necrotic","type":"resistance","value":"Necrotic","condition":"","damage_type":"Necrotic"},{"name":"Radiant","type":"resistance","value":"Radiant","condition":"","damage_type":"Radiant"}]},{"desc":["You have Darkvision with a range of 60 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["As a Magic action, you touch a creature and roll a number of d4s equal to your Proficiency Bonus. The creature regains a number of Hit Points equal to the total rolled. Once you use this trait, you can't use it again until you finish a Long Rest."],"name":"Healing Hands","index":"healing-hands","effects":[{"desc":"Touch a creature to heal it PB × d4 Hit Points. 1/Long Rest.","name":"Healing Hands","type":"action","description":"Touch a creature to heal it PB × d4 Hit Points. 1/Long Rest."}],"modifiers":[{"desc":"Touch a creature to heal it PB × d4 Hit Points. 1/Long Rest.","name":"Healing Hands","type":"action","description":"Touch a creature to heal it PB × d4 Hit Points. 1/Long Rest."}]},{"desc":["You know the Light cantrip. Charisma is your spellcasting ability for it."],"name":"Light Bearer","index":"light-bearer","effects":[{"name":"Light","type":"spell_access","spell":"Light","condition":"Cantrip (CHA)"}],"modifiers":[{"name":"Light","type":"spell_access","spell":"Light","condition":"Cantrip (CHA)"}]},{"desc":["When you reach character level 3, you can transform as a Bonus Action using one of the options below (choose the option each time you transform). The transformation lasts for 1 minute or until you end it (no action required). Once you transform, you can't do so again until you finish a Long Rest. Once on each of your turns before the transformation ends, you can deal extra damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your Proficiency Bonus, and the extra damage's type is either Necrotic for Necrotic Shroud or Radiant for Heavenly Wings and Inner Radiance. Heavenly Wings: two spectral wings sprout from your back temporarily; until the transformation ends, you have a Fly Speed equal to your Speed. Inner Radiance: searing light temporarily radiates from your eyes and mouth; for the duration, you shed Bright Light in a 10-foot radius and Dim Light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes Radiant damage equal to your Proficiency Bonus. Necrotic Shroud: your eyes briefly become pools of darkness, and flightless wings sprout from your back temporarily; creatures other than your allies within 10 feet of you must succeed on a Charisma saving throw (DC 8 plus your Charisma modifier and Proficiency Bonus) or have the Frightened condition until the end of your next turn."],"name":"Celestial Revelation","index":"celestial-revelation","effects":[{"desc":"From level 3: transform for 1 minute (Heavenly Wings, Inner Radiance, or Necrotic Shroud) and deal +PB Radiant/Necrotic damage once per turn. 1/Long Rest.","name":"Celestial Revelation","type":"bonus_action","description":"From level 3: transform for 1 minute (Heavenly Wings, Inner Radiance, or Necrotic Shroud) and deal +PB Radiant/Necrotic damage once per turn. 1/Long Rest."}],"modifiers":[{"desc":"From level 3: transform for 1 minute (Heavenly Wings, Inner Radiance, or Necrotic Shroud) and deal +PB Radiant/Necrotic damage once per turn. 1/Long Rest.","name":"Celestial Revelation","type":"bonus_action","description":"From level 3: transform for 1 minute (Heavenly Wings, Inner Radiance, or Necrotic Shroud) and deal +PB Radiant/Necrotic damage once per turn. 1/Long Rest."}]}],"choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most aasimar are good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 4–7 feet tall) or Small (about 3–4 feet tall), chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'aasimar'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = '5d23406a-0028-4953-ad1d-d90ee5191178';

-- Half-Orc (half-orc)
update public.custom_races
   set data = $persona_content_migration${"id":"677cff61-36f7-4f62-9e44-f8e84abfce55","age":"Half-orcs mature a little faster than humans, reaching adulthood around 14, and rarely live longer than 75 years.","desc":["Whether united under the leadership of a mighty warlock or having fought to a standstill after years of conflict, orc and human communities sometimes form alliances, and half-orcs are born of those unions. They are strong, relentless, and quick to anger — and quick to laugh."],"name":"Half-Orc","size":"Medium","index":"half-orc","speed":30,"source":"Player's Handbook (2014)","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["Thanks to your orc blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You gain proficiency in the Intimidation skill."],"name":"Menacing","index":"menacing","effects":[{"name":"Intimidation","type":"proficiency","value":"Intimidation","target":"Intimidation","category":"skill"},{"type":"proficiency","target":"Intimidation","category":"skill"}],"modifiers":[{"name":"Intimidation","type":"proficiency","value":"Intimidation","target":"Intimidation","category":"skill"}]},{"desc":["When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a Long Rest."],"name":"Relentless Endurance","index":"relentless-endurance","effects":[{"desc":"Drop to 1 HP instead of 0. 1/Long Rest.","name":"Relentless Endurance","type":"feature","description":"Drop to 1 HP instead of 0. 1/Long Rest."}],"modifiers":[{"desc":"Drop to 1 HP instead of 0. 1/Long Rest.","name":"Relentless Endurance","type":"feature","description":"Drop to 1 HP instead of 0. 1/Long Rest."}]},{"desc":["When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."],"name":"Savage Attacks","index":"savage-attacks","effects":[{"desc":"Roll one extra weapon damage die on a melee critical hit.","name":"Savage Attacks","type":"feature","description":"Roll one extra weapon damage die on a melee critical hit."}],"modifiers":[{"desc":"Roll one extra weapon damage die on a melee critical hit.","name":"Savage Attacks","type":"feature","description":"Roll one extra weapon damage die on a melee critical hit."}]}],"choices":[{"id":"half-orc-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"half-orc-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; half-orcs inherit a tendency toward chaos and are not strongly inclined toward good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Orc","index":"orc"}],"is_homebrew":false,"language_desc":"Common, Orc","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'half-orc'),
       source = 'Player''s Handbook (2014)',
       migrated_at = now()
 where id = '677cff61-36f7-4f62-9e44-f8e84abfce55';

-- Halfling (halfling)
update public.custom_races
   set data = $persona_content_migration${"id":"afa1d330-109f-4157-b84a-6eb143eacc7f","age":"Halflings reach adulthood at 20 and live about 150 years.","desc":["Cherished and guided by gods who value home and hearth, halflings are a people of comfort and community — small, nimble, and remarkably lucky, with a courage that belies their stature."],"name":"Halfling","size":"Small","index":"halfling","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Advantage on saving throws you make to avoid or end the Frightened condition."],"name":"Brave","index":"brave","effects":[{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}]},{"desc":["You can move through the space of any creature that is a size larger than you, but you can't stop in the same space."],"name":"Halfling Nimbleness","index":"halfling-nimbleness","effects":[{"desc":"Move through the space of any creature one size larger than you.","name":"Halfling Nimbleness","type":"feature","description":"Move through the space of any creature one size larger than you."}],"modifiers":[{"desc":"Move through the space of any creature one size larger than you.","name":"Halfling Nimbleness","type":"feature","description":"Move through the space of any creature one size larger than you."}]},{"desc":["When you roll a 1 on the d20 of a D20 Test, you can reroll the die, and you must use the new roll."],"name":"Luck","index":"luck","effects":[{"desc":"Reroll a natural 1 on any D20 Test (must use the new roll).","name":"Luck","type":"feature","description":"Reroll a natural 1 on any D20 Test (must use the new roll)."}],"modifiers":[{"desc":"Reroll a natural 1 on any D20 Test (must use the new roll).","name":"Luck","type":"feature","description":"Reroll a natural 1 on any D20 Test (must use the new roll)."}]},{"desc":["You can take the Hide action even when you are obscured only by a creature that is at least one size larger than you."],"name":"Naturally Stealthy","index":"naturally-stealthy","effects":[{"desc":"Hide behind creatures at least one size larger than you.","name":"Naturally Stealthy","type":"feature","description":"Hide behind creatures at least one size larger than you."}],"modifiers":[{"desc":"Hide behind creatures at least one size larger than you.","name":"Naturally Stealthy","type":"feature","description":"Hide behind creatures at least one size larger than you."}]}],"choices":[],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most halflings are lawful good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Small (about 2–3 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'halfling'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'afa1d330-109f-4157-b84a-6eb143eacc7f';

-- Firbolg (firbolg)
update public.custom_races
   set data = $persona_content_migration${"id":"903d0d4e-68c8-4d22-b75c-5bffb2750d96","age":"Firbolgs reach adulthood around 30 and can live up to 500 years.","desc":["Distant cousins of giants, the first firbolgs wandered the primeval forests of the multiverse, and the magic of those forests entwined itself with the firbolgs' souls. Reclusive and gentle, they are guardians of the wild and can speak with its beasts and plants."],"name":"Firbolg","size":"Medium","index":"firbolg","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["You can cast the Detect Magic and Disguise Self spells with this trait. When you use this version of Disguise Self, you can seem up to 3 feet shorter or taller. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Firbolg Magic","index":"firbolg-magic","effects":[{"name":"Detect Magic","type":"spell_access","spell":"Detect Magic","condition":"1/Long Rest without a slot","free_casts":1,"free_cast_reset":"long"},{"name":"Disguise Self","type":"spell_access","spell":"Disguise Self","condition":"1/Long Rest without a slot","free_casts":1,"free_cast_reset":"long"}]},{"desc":["As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Hidden Step","index":"hidden-step","effects":[{"desc":"Become invisible until the start of your next turn or until you attack, deal damage, or force a save. PB uses per Long Rest.","name":"Hidden Step","type":"bonus_action","description":"Become invisible until the start of your next turn or until you attack, deal damage, or force a save. PB uses per Long Rest."}]},{"desc":["You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."],"name":"Powerful Build","index":"powerful-build","effects":[{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}]},{"desc":["You have the ability to communicate in a limited manner with Beasts, Plants, and vegetation. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."],"name":"Speech of Beast and Leaf","index":"speech-of-beast-and-leaf","effects":[{"desc":"Beasts and plants understand you; advantage on Charisma checks to influence them.","name":"Speech of Beast and Leaf","type":"feature","description":"Beasts and plants understand you; advantage on Charisma checks to influence them."}]}],"choices":[{"id":"firbolg-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"firbolg-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"firbolg-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most firbolgs are neutral good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 7–8 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'firbolg'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '903d0d4e-68c8-4d22-b75c-5bffb2750d96';

-- Human (human)
update public.custom_races
   set data = $persona_content_migration${"id":"e5ee1f81-6f23-47b2-9b71-e23208edd236","age":"Humans reach adulthood in their late teens and live less than a century.","desc":["Found throughout the multiverse, humans are perhaps the most varied of all peoples — a little of everything is found in them, and they are known for their adaptability, ambition, and restless drive to explore, build, and leave a legacy."],"name":"Human","size":"Small or Medium","index":"human","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You gain Heroic Inspiration whenever you finish a Long Rest."],"name":"Resourceful","index":"resourceful","effects":[{"desc":"Gain Heroic Inspiration whenever you finish a Long Rest.","name":"Resourceful","type":"feature","description":"Gain Heroic Inspiration whenever you finish a Long Rest."}],"modifiers":[{"desc":"Gain Heroic Inspiration whenever you finish a Long Rest.","name":"Resourceful","type":"feature","description":"Gain Heroic Inspiration whenever you finish a Long Rest."}]},{"desc":["You gain proficiency in one skill of your choice."],"name":"Skillful","index":"skillful","effects":[],"modifiers":[]},{"desc":["You gain an Origin feat of your choice. Skilled is recommended."],"name":"Versatile","index":"versatile","effects":[{"desc":"Gain one Origin feat of your choice.","name":"Versatile","type":"feature","description":"Gain one Origin feat of your choice."}],"modifiers":[{"desc":"Gain one Origin feat of your choice.","name":"Versatile","type":"feature","description":"Gain one Origin feat of your choice."}]}],"choices":[{"id":"human-skill","kind":"skill","count":1,"label":"Skillful: one skill of your choice","source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]},{"id":"human-feat","kind":"feat","count":1,"label":"Versatile: one Origin feat","source":"race","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 4–7 feet tall) or Small (about 2–4 feet tall), chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
