-- Kenku (kenku)
update public.custom_races
   set data = $persona_content_migration${"id":"32cea74e-1a8c-4dff-bbf7-d0f49b342148","age":"Kenku have shorter lifespans than humans, reaching maturity at 12 and living to 60.","desc":["Kenku are avian humanoids who resemble crows. Their origins are shrouded in mystery, and they have a gift for mimicry and perfect recall of sounds and handwriting — a talent put to use by forgers, scouts, and thieves."],"name":"Kenku","size":"Small or Medium","index":"kenku","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["When you copy writing or craftwork produced by yourself or someone else, you have advantage on any ability check you make to produce an exact duplicate."],"name":"Expert Duplication","index":"expert-duplication","effects":[{"desc":"Advantage on checks to produce exact duplicates of writing or craftwork.","name":"Expert Duplication","type":"feature","description":"Advantage on checks to produce exact duplicates of writing or craftwork."}],"modifiers":[{"desc":"Advantage on checks to produce exact duplicates of writing or craftwork.","name":"Expert Duplication","type":"feature","description":"Advantage on checks to produce exact duplicates of writing or craftwork."}]},{"desc":["Thanks to your supernaturally good memory, you have proficiency in two skills of your choice. Moreover, when you make an ability check using any skill in which you have proficiency, you can give yourself advantage on the check before rolling the d20. You can give yourself advantage in this way a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Kenku Recall","index":"kenku-recall","effects":[{"desc":"Give yourself advantage on a check with a proficient skill. PB uses per Long Rest.","name":"Kenku Recall","type":"feature","description":"Give yourself advantage on a check with a proficient skill. PB uses per Long Rest."}],"modifiers":[{"desc":"Give yourself advantage on a check with a proficient skill. PB uses per Long Rest.","name":"Kenku Recall","type":"feature","description":"Give yourself advantage on a check with a proficient skill. PB uses per Long Rest."}]},{"desc":["You can accurately mimic sounds you have heard, including voices. A creature that hears the sounds can tell they are imitations only with a successful Wisdom (Insight) check against a DC of 8 + your proficiency bonus + your Charisma modifier."],"name":"Mimicry","index":"mimicry","effects":[{"desc":"Mimic any sound you have heard; Insight DC 8 + PB + CHA to detect.","name":"Mimicry","type":"feature","description":"Mimic any sound you have heard; Insight DC 8 + PB + CHA to detect."}],"modifiers":[{"desc":"Mimic any sound you have heard; Insight DC 8 + PB + CHA to detect.","name":"Mimicry","type":"feature","description":"Mimic any sound you have heard; Insight DC 8 + PB + CHA to detect."}]}],"choices":[{"id":"kenku-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kenku-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kenku-skills","kind":"skill","count":2,"label":"Kenku Recall skills","source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]},{"id":"kenku-training","kind":"skill","count":2,"source":"race","options":["Acrobatics","Deception","Stealth","Sleight of Hand"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; kenku are often chaotic neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'kenku'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '32cea74e-1a8c-4dff-bbf7-d0f49b342148';

-- Elf (elf)
update public.custom_races
   set data = $persona_content_migration${"id":"f8fab049-7c14-432c-a4c0-292f76e44e0c","age":"Elves reach physical maturity around 20 and can live to be 750 years old.","desc":["Created by the god Corellon, the first elves could change their forms at will. They lost this ability when Corellon cursed them for siding with Lolth, and the lineages — Drow, High Elf, and Wood Elf — reflect the magic that now runs through their blood. Elves are long-lived, graceful, and attuned to magic and the Feywild."],"name":"Elf","size":"Medium","index":"elf","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Darkvision with a range of 60 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You are part of a lineage that grants you supernatural abilities. Choose a lineage — Drow, High Elf, or Wood Elf (see lineages). You gain the level 1 benefit of that lineage. When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the Elven Lineages table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."],"name":"Elven Lineage","index":"elven-lineage","effects":[]},{"desc":["You have Advantage on saving throws you make to avoid or end the Charmed condition."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You have proficiency in the Insight, Perception, or Survival skill."],"name":"Keen Senses","index":"keen-senses","effects":[{"type":"proficiency","target":"Perception","category":"skill"}]},{"desc":["You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."],"name":"Trance","index":"trance","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long Rest in 4 hours of meditation; no sleep needed.","name":"Trance","type":"feature","description":"Long Rest in 4 hours of meditation; no sleep needed."}]}],"choices":[{"id":"elf-keen-senses","kind":"skill","count":1,"label":"Keen Senses: Insight, Perception, or Survival","source":"race","options":["Insight","Perception","Survival"]},{"id":"elf-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; elves love freedom and lean toward chaos.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[{"desc":["Drow trace their lineage to the Underdark, where their eyes and magic adapted to the dark."],"name":"Drow","index":"drow","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["The range of your Darkvision increases to 120 feet. You also know the Dancing Lights cantrip. At character level 3 you always have Faerie Fire prepared, and at level 5 you always have Darkness prepared; you can cast each once per Long Rest without a spell slot."],"name":"Drow Lineage","index":"drow-lineage","effects":[{"name":"Darkvision","type":"set","value":120,"target":"darkvision"},{"name":"Dancing Lights","type":"spell_access","spell":"Dancing Lights","condition":"Cantrip"},{"name":"Faerie Fire","type":"spell_access","spell":"Faerie Fire","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Darkness","type":"spell_access","spell":"Darkness","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["High elves have a keen affinity for arcane magic."],"name":"High Elf","index":"high-elf","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You know the Prestidigitation cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Wizard spell list. At character level 3 you always have Detect Magic prepared, and at level 5 you always have Misty Step prepared; you can cast each once per Long Rest without a spell slot."],"name":"High Elf Lineage","index":"high-elf-lineage","effects":[{"name":"Prestidigitation","type":"spell_access","spell":"Prestidigitation","condition":"Cantrip (swap for any Wizard cantrip after a Long Rest)"},{"name":"Detect Magic","type":"spell_access","spell":"Detect Magic","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Misty Step","type":"spell_access","spell":"Misty Step","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[{"id":"high-elf-cantrip","kind":"spell","count":1,"level":0,"sourceClass":"wizard","source":"subrace","options":[]}],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Wood elves are fleet and at home in forests, drawing on primal magic."],"name":"Wood Elf","index":"wood-elf","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["Your Speed increases to 35 feet. You also know the Druidcraft cantrip. At character level 3 you always have Longstrider prepared, and at level 5 you always have Pass without Trace prepared; you can cast each once per Long Rest without a spell slot."],"name":"Wood Elf Lineage","index":"wood-elf-lineage","effects":[{"name":"Speed","type":"bonus","value":5,"target":"speed"},{"name":"Druidcraft","type":"spell_access","spell":"Druidcraft","condition":"Cantrip"},{"name":"Longstrider","type":"spell_access","spell":"Longstrider","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Pass without Trace","type":"spell_access","spell":"Pass without Trace","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'elf'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'f8fab049-7c14-432c-a4c0-292f76e44e0c';

-- Tiefling (tiefling)
update public.custom_races
   set data = $persona_content_migration${"id":"c6424073-21b5-4212-9e05-93098917782d","age":"Tieflings mature at the same rate as humans and live a few years longer.","desc":["Tieflings are either born in the Lower Planes or have fiendish ancestors who originated there. A tiefling's fiendish legacy — Abyssal, Chthonic, or Infernal — manifests in horns, tails, and unusual eyes, and grants innate magic drawn from that plane."],"name":"Tiefling","size":"Small or Medium","index":"tiefling","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Darkvision with a range of 60 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You are the recipient of a legacy that grants you supernatural abilities. Choose a legacy — Abyssal, Chthonic, or Infernal (see legacies). You gain the level 1 benefit of the chosen legacy. When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the Fiendish Legacies table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy)."],"name":"Fiendish Legacy","index":"fiendish-legacy","effects":[]},{"desc":["You know the Thaumaturgy cantrip. When you cast it with this trait, the spell uses the same spellcasting ability you use for your Fiendish Legacy trait."],"name":"Otherworldly Presence","index":"otherworldly-presence","effects":[{"name":"Thaumaturgy","type":"spell_access","spell":"Thaumaturgy","condition":"Cantrip"}]}],"choices":[{"id":"tiefling-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 4–7 feet tall) or Small (about 3–4 feet tall), chosen when you select this species.","subraces_details":[{"desc":["Your legacy traces to the Abyss, the chaotic home of demons."],"name":"Abyssal","index":"abyssal","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You have Resistance to Poison damage. You also know the Poison Spray cantrip. At character level 3 you always have Ray of Sickness prepared, and at level 5 you always have Hold Person prepared; you can cast each once per Long Rest without a spell slot."],"name":"Abyssal Legacy","index":"abyssal-legacy","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Poison Spray","type":"spell_access","spell":"Poison Spray","condition":"Cantrip"},{"name":"Ray of Sickness","type":"spell_access","spell":"Ray of Sickness","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Hold Person","type":"spell_access","spell":"Hold Person","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your legacy traces to Carceri, Hades, or another plane of the dead."],"name":"Chthonic","index":"chthonic","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You have Resistance to Necrotic damage. You also know the Chill Touch cantrip. At character level 3 you always have False Life prepared, and at level 5 you always have Ray of Enfeeblement prepared; you can cast each once per Long Rest without a spell slot."],"name":"Chthonic Legacy","index":"chthonic-legacy","effects":[{"name":"Necrotic","type":"resistance","value":"Necrotic","condition":"","damage_type":"Necrotic"},{"name":"Chill Touch","type":"spell_access","spell":"Chill Touch","condition":"Cantrip"},{"name":"False Life","type":"spell_access","spell":"False Life","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Ray of Enfeeblement","type":"spell_access","spell":"Ray of Enfeeblement","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your legacy traces to the Nine Hells, the lawful home of devils."],"name":"Infernal","index":"infernal","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You have Resistance to Fire damage. You also know the Fire Bolt cantrip. At character level 3 you always have Hellish Rebuke prepared, and at level 5 you always have Darkness prepared; you can cast each once per Long Rest without a spell slot."],"name":"Infernal Legacy","index":"infernal-legacy","effects":[{"name":"Fire","type":"resistance","value":"Fire","condition":"","damage_type":"Fire"},{"name":"Fire Bolt","type":"spell_access","spell":"Fire Bolt","condition":"Cantrip"},{"name":"Hellish Rebuke","type":"spell_access","spell":"Hellish Rebuke","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Darkness","type":"spell_access","spell":"Darkness","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'tiefling'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'c6424073-21b5-4212-9e05-93098917782d';

-- Triton (triton)
update public.custom_races
   set data = $persona_content_migration${"id":"82b6966a-b5c4-4d6d-998b-d1ef89c9da19","age":"Tritons reach maturity around 15 and can live up to 200 years.","desc":["Tritons guard the ocean depths, having arrived from the Elemental Plane of Water ages ago to fight the horrors of the deep. Proud and a little aloof, they can breathe both air and water and call on elemental magic."],"name":"Triton","size":"Medium","index":"triton","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["You can breathe air and water."],"name":"Amphibious","index":"amphibious","effects":[{"desc":"Breathe air and water.","name":"Amphibious","type":"feature","description":"Breathe air and water."}]},{"desc":["You can cast Fog Cloud with this trait. Starting at 3rd level, you can cast the Gust of Wind spell with this trait. Starting at 5th level, you can also cast the Water Walk spell with it. Once you cast any of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Control Air and Water","index":"control-air-and-water","effects":[{"name":"Fog Cloud","type":"spell_access","spell":"Fog Cloud","condition":"1/Long Rest without a slot","free_casts":1,"free_cast_reset":"long"},{"name":"Gust of Wind","type":"spell_access","spell":"Gust of Wind","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Water Walk","type":"spell_access","spell":"Water Walk","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You can communicate simple ideas to any Beast, Elemental, or Monstrosity that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."],"name":"Emissary of the Sea","index":"emissary-of-the-sea","effects":[{"desc":"Communicate simple ideas to swimming Beasts, Elementals, and Monstrosities.","name":"Emissary of the Sea","type":"feature","description":"Communicate simple ideas to swimming Beasts, Elementals, and Monstrosities."}]},{"desc":["Adapted to the frigid ocean depths, you have resistance to cold damage."],"name":"Guardian of the Depths","index":"guardian-of-the-depths","effects":[{"name":"Cold","type":"resistance","value":"Cold","condition":"","damage_type":"Cold"}]}],"choices":[{"id":"triton-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"triton-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"triton-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; tritons tend toward lawful good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"swim_speed":30,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'triton'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '82b6966a-b5c4-4d6d-998b-d1ef89c9da19';

-- Lizardfolk (lizardfolk)
update public.custom_races
   set data = $persona_content_migration${"id":"d5b74ed3-42da-46ea-bdfb-06002ebb44b2","age":"Lizardfolk reach maturity around age 14 and rarely live longer than 60 years.","desc":["Lizardfolk possess an alien and inscrutable mindset, their desires and thoughts driven by a different set of basic principles than those of warm-blooded creatures. Hardy survivors, they are at home in swamps and marshes and can craft tools from the bones of their kills."],"name":"Lizardfolk","size":"Medium","index":"lizardfolk","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You have a fanged maw that you can use to make unarmed strikes. When you hit with it, the strike deals 1d6 + your Strength modifier piercing damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Bite","index":"bite","effects":[{"die":"1d6","name":"Bite","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Piercing"}],"modifiers":[{"die":"1d6","name":"Bite","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Piercing"}]},{"desc":["You can hold your breath for up to 15 minutes at a time."],"name":"Hold Breath","index":"hold-breath","effects":[{"desc":"Hold your breath for up to 15 minutes.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 15 minutes."}],"modifiers":[{"desc":"Hold your breath for up to 15 minutes.","name":"Hold Breath","type":"feature","description":"Hold your breath for up to 15 minutes."}]},{"desc":["You can throw yourself into a feeding frenzy. As a bonus action, you can make a special attack with your Bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Hungry Jaws","index":"hungry-jaws","effects":[{"desc":"Make a Bite attack; on a hit, gain PB temporary hit points. PB uses per Long Rest.","name":"Hungry Jaws","type":"bonus_action","description":"Make a Bite attack; on a hit, gain PB temporary hit points. PB uses per Long Rest."}],"modifiers":[{"desc":"Make a Bite attack; on a hit, gain PB temporary hit points. PB uses per Long Rest.","name":"Hungry Jaws","type":"bonus_action","description":"Make a Bite attack; on a hit, gain PB temporary hit points. PB uses per Long Rest."}]},{"desc":["You have tough, scaly skin. When you aren't wearing armor, your base AC is 13 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."],"name":"Natural Armor","index":"natural-armor","effects":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"}],"modifiers":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"}]},{"desc":["Thanks to your connection to the natural world, you gain proficiency with two of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."],"name":"Nature's Intuition","index":"nature's-intuition","effects":[],"modifiers":[]}],"choices":[{"id":"lizardfolk-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"lizardfolk-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"lizardfolk-skills","kind":"skill","count":2,"label":"Nature's Intuition skills","source":"race","options":["Animal Handling","Medicine","Nature","Perception","Stealth","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most lizardfolk are neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"swim_speed":30,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'lizardfolk'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'd5b74ed3-42da-46ea-bdfb-06002ebb44b2';

-- Kalashtar (kalashtar)
update public.custom_races
   set data = $persona_content_migration${"id":"19a83786-3922-4ef0-a843-31c874d133df","age":"Kalashtar mature and age at the same rate as humans.","desc":["The kalashtar are a compound people, created when renegade spirits from the plane of dreams merged with human monks. Each kalashtar shares a bond with a quori spirit, granting psychic resilience, telepathy, and a serene, otherworldly bearing."],"name":"Kalashtar","size":"Medium","index":"kalashtar","speed":30,"source":"Eberron: Rising from the Last War","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You have advantage on all Wisdom saving throws."],"name":"Dual Mind","index":"dual-mind","effects":[{"name":"Advantage on saves: Wisdom","type":"advantage","value":1,"filter":"Wisdom","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Wisdom","type":"advantage","value":1,"filter":"Wisdom","target":"saves"}]},{"desc":["You have resistance to psychic damage."],"name":"Mental Discipline","index":"mental-discipline","effects":[{"name":"Psychic","type":"resistance","value":"Psychic","condition":"","damage_type":"Psychic"}],"modifiers":[{"name":"Psychic","type":"resistance","value":"Psychic","condition":"","damage_type":"Psychic"}]},{"desc":["You can speak telepathically to any creature you can see, provided the creature is within a number of feet of you equal to 10 times your level. You don't need to share a language with the creature for it to understand your telepathic utterances, but the creature must be able to understand at least one language. When you're using this trait to speak telepathically to a creature, you can use your action to give that creature the ability to speak telepathically with you for 1 hour or until you end this effect as an action. To use this ability, the creature must be able to see you and must be within this trait's range. You can give this ability to only one creature at a time; giving it to a creature takes it away from another creature who has it."],"name":"Mind Link","index":"mind-link","effects":[{"desc":"Telepathy with a creature you can see within 10 × level feet; action to let it reply for 1 hour.","name":"Mind Link","type":"feature","description":"Telepathy with a creature you can see within 10 × level feet; action to let it reply for 1 hour."}],"modifiers":[{"desc":"Telepathy with a creature you can see within 10 × level feet; action to let it reply for 1 hour.","name":"Mind Link","type":"feature","description":"Telepathy with a creature you can see within 10 × level feet; action to let it reply for 1 hour."}]},{"desc":["Kalashtar sleep, but they don't connect to the plane of dreams as other creatures do. Instead, their minds draw from the memories of their otherworldly spirit while they sleep. As such, you are immune to spells and other magical effects that require you to dream, like Dream, but not to spells and other magical effects that put you to sleep, like Sleep."],"name":"Severed from Dreams","index":"severed-from-dreams","effects":[{"desc":"Immune to magic that requires you to dream (e.g. Dream).","name":"Severed from Dreams","type":"feature","description":"Immune to magic that requires you to dream (e.g. Dream)."}],"modifiers":[{"desc":"Immune to magic that requires you to dream (e.g. Dream).","name":"Severed from Dreams","type":"feature","description":"Immune to magic that requires you to dream (e.g. Dream)."}]}],"choices":[{"id":"kalashtar-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"kalashtar-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most kalashtar are lawful good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Quori","index":"quori"}],"is_homebrew":false,"language_desc":"Common, Quori and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'kalashtar'),
       source = 'Eberron: Rising from the Last War',
       migrated_at = now()
 where id = '19a83786-3922-4ef0-a843-31c874d133df';

-- Changeling (changeling)
update public.custom_races
   set data = $persona_content_migration${"id":"95dbf83b-4748-4f19-a431-a723e59c95a7","age":"Changelings mature slightly faster than humans and live about as long.","desc":["With ever-changing appearances, changelings reside in many societies undetected. Each changeling can supernaturally adopt any face they like, and many become spies, performers, or diplomats who are never quite what they seem."],"name":"Changeling","size":"Small or Medium","index":"changeling","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Fey."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}]},{"desc":["Thanks to your connection to the fey, you gain proficiency with two of the following skills of your choice: Deception, Insight, Intimidation, Performance, or Persuasion."],"name":"Changeling Instincts","index":"changeling-instincts","effects":[],"modifiers":[]},{"desc":["As an action, you can change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight and can change your size between Medium and Small. You can make yourself appear as a member of another race, though none of your game statistics change. You can't duplicate the appearance of an individual you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren't changed by this trait. You stay in the new form until you use an action to revert to your true form or until you die."],"name":"Shapechanger","index":"shapechanger","effects":[{"desc":"Change your appearance, voice, and size (Small/Medium) until you revert or die.","name":"Shapechanger","type":"action","description":"Change your appearance, voice, and size (Small/Medium) until you revert or die."}],"modifiers":[{"desc":"Change your appearance, voice, and size (Small/Medium) until you revert or die.","name":"Shapechanger","type":"action","description":"Change your appearance, voice, and size (Small/Medium) until you revert or die."}]}],"choices":[{"id":"changeling-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"changeling-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"changeling-skills","kind":"skill","count":2,"label":"Changeling Instincts skills","source":"race","options":["Deception","Insight","Intimidation","Performance","Persuasion"]},{"id":"changeling-instincts","kind":"skill","count":2,"source":"race","options":["Deception","Insight","Intimidation","Persuasion"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'changeling'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '95dbf83b-4748-4f19-a431-a723e59c95a7';

-- Fairy (fairy)
update public.custom_races
   set data = $persona_content_migration${"id":"9fd750f7-a2ae-436d-8c21-cd3fb894cd6b","age":"Fairies mature at the same rate as humans but can live much longer.","desc":["The Feywild is home to many fantastic peoples, including fairies. Fairies are a wee folk — but not nearly as much as their pixie and sprite friends — and their bodies thrum with the magic of the Feywild, granting them flight and innate glamours."],"name":"Fairy","size":"Small","index":"fairy","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Fey."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}]},{"desc":["You know the Druidcraft cantrip. Starting at 3rd level, you can cast the Faerie Fire spell with this trait. Starting at 5th level, you can also cast the Enlarge/Reduce spell with this trait. Once you cast Faerie Fire or Enlarge/Reduce with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast either of those spells using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."],"name":"Fairy Magic","index":"fairy-magic","effects":[{"name":"Druidcraft","type":"spell_access","spell":"Druidcraft","condition":"Cantrip"},{"name":"Faerie Fire","type":"spell_access","spell":"Faerie Fire","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Enlarge/Reduce","type":"spell_access","spell":"Enlarge/Reduce","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]},{"desc":["Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."],"name":"Flight","index":"flight","effects":[{"desc":"Fly Speed equal to your walking speed; not usable in medium or heavy armor.","name":"Flight","type":"feature","description":"Fly Speed equal to your walking speed; not usable in medium or heavy armor."}]}],"choices":[{"id":"fairy-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"fairy-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"fairy-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","fly_speed":30,"is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Small (about 3 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'fairy'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '9fd750f7-a2ae-436d-8c21-cd3fb894cd6b';

-- Thri-kreen (thri-kreen)
update public.custom_races
   set data = $persona_content_migration${"id":"b4b47bf5-69c8-4a32-a32a-318ee3dddc77","age":"Thri-kreen mature quickly and live about 30 years.","desc":["Thri-kreen are insectile humanoids with four arms and a chitinous carapace that can shift color to match their surroundings. They never sleep, communicate telepathically, and are formidable hunters across many worlds and the void between them."],"name":"Thri-kreen","size":"Small or Medium","index":"thri-kreen","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Monstrosity."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Monstrosity (not Humanoid).","name":"Monstrosity","type":"feature","description":"Your creature type is Monstrosity (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Monstrosity (not Humanoid).","name":"Monstrosity","type":"feature","description":"Your creature type is Monstrosity (not Humanoid)."}]},{"desc":["While you aren't wearing armor, your carapace gives you a base Armor Class of 13 + your Dexterity modifier. As an action, you can change the color of your carapace to match the color and texture of your surroundings, giving you advantage on Dexterity (Stealth) checks made to hide in those surroundings."],"name":"Chameleon Carapace","index":"chameleon-carapace","effects":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"},{"desc":"Match your surroundings for advantage on Stealth checks to hide.","name":"Chameleon Carapace","type":"action","description":"Match your surroundings for advantage on Stealth checks to hide."}],"modifiers":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"},{"desc":"Match your surroundings for advantage on Stealth checks to hide.","name":"Chameleon Carapace","type":"action","description":"Match your surroundings for advantage on Stealth checks to hide."}]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have two slightly smaller secondary arms below your primary pair of arms. The secondary arms can manipulate an object, open or close a door or container, pick up or set down a Tiny object, or wield a weapon that has the light property."],"name":"Secondary Arms","index":"secondary-arms","effects":[{"desc":"Two extra arms that can manipulate objects or wield light weapons.","name":"Secondary Arms","type":"feature","description":"Two extra arms that can manipulate objects or wield light weapons."}],"modifiers":[{"desc":"Two extra arms that can manipulate objects or wield light weapons.","name":"Secondary Arms","type":"feature","description":"Two extra arms that can manipulate objects or wield light weapons."}]},{"desc":["You don't require sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a tranquil, motionless state, during which you remain conscious."],"name":"Sleepless","index":"sleepless","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours of motionless rest; no sleep needed.","name":"Sleepless","type":"feature","description":"Long rest in 4 hours of motionless rest; no sleep needed."}],"modifiers":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long rest in 4 hours of motionless rest; no sleep needed.","name":"Sleepless","type":"feature","description":"Long rest in 4 hours of motionless rest; no sleep needed."}]},{"desc":["You can telepathically speak to any creature you can see within 120 feet of you. You don't need to share a language with the creature for it to understand your telepathic utterances, but the creature must be able to understand at least one language. As a bonus action, you can give a creature the ability to telepathically speak with you for 1 hour or until you end this effect as a bonus action; the creature must be able to see you and must be within 120 feet of you. You can give this ability to only one creature at a time."],"name":"Thri-kreen Telepathy","index":"thri-kreen-telepathy","effects":[{"desc":"Telepathy with creatures you can see within 120 ft.","name":"Thri-kreen Telepathy","type":"feature","description":"Telepathy with creatures you can see within 120 ft."},{"desc":"Let one creature within 120 ft. speak telepathically with you for 1 hour.","name":"Share Telepathy","type":"bonus_action","description":"Let one creature within 120 ft. speak telepathically with you for 1 hour."}],"modifiers":[{"desc":"Telepathy with creatures you can see within 120 ft.","name":"Thri-kreen Telepathy","type":"feature","description":"Telepathy with creatures you can see within 120 ft."},{"desc":"Let one creature within 120 ft. speak telepathically with you for 1 hour.","name":"Share Telepathy","type":"bonus_action","description":"Let one creature within 120 ft. speak telepathically with you for 1 hour."}]}],"choices":[{"id":"thri-kreen-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"thri-kreen-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Thri-kreen can understand Common and one language of your choice, but they communicate through telepathy and can't speak those languages.","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'thri-kreen'),
       source = 'Spelljammer: Adventures in Space',
       migrated_at = now()
 where id = 'b4b47bf5-69c8-4a32-a32a-318ee3dddc77';

-- Leonin (leonin)
update public.custom_races
   set data = $persona_content_migration${"id":"099c101e-37ad-48a1-900b-f1f354fb068c","age":"Leonin mature and age at about the same rate as humans.","desc":["Leonin are proud, lion-like humanoids from the savannas of Theros. Fierce hunters and devoted protectors of their prides, they roar with a terror that scatters their enemies."],"name":"Leonin","size":"Medium","index":"leonin","speed":35,"source":"Mythic Odysseys of Theros","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Claws","index":"claws","effects":[{"die":"1d4","name":"Claws","type":"unarmed_strike","value":"1d4","damage_die":"1d4","damage_type":"Slashing"}],"modifiers":[{"die":"1d4","name":"Claws","type":"unarmed_strike","value":"1d4","damage_die":"1d4","damage_type":"Slashing"}]},{"desc":["You have proficiency in one of the following skills of your choice: Athletics, Intimidation, Perception, or Survival."],"name":"Hunter's Instincts","index":"hunter's-instincts","effects":[],"modifiers":[]},{"desc":["As a bonus action, you can let out an especially menacing roar. Creatures of your choice within 10 feet of you that can hear you must succeed on a Wisdom saving throw or become frightened of you until the end of your next turn. The DC of the save equals 8 + your proficiency bonus + your Constitution modifier. Once you use this trait, you can't use it again until you finish a Short or Long Rest."],"name":"Daunting Roar","index":"daunting-roar","effects":[{"desc":"Creatures within 10 ft. make a WIS save (8 + PB + CON) or are frightened until the end of your next turn. 1/Short or Long Rest.","name":"Daunting Roar","type":"bonus_action","description":"Creatures within 10 ft. make a WIS save (8 + PB + CON) or are frightened until the end of your next turn. 1/Short or Long Rest."}],"modifiers":[{"desc":"Creatures within 10 ft. make a WIS save (8 + PB + CON) or are frightened until the end of your next turn. 1/Short or Long Rest.","name":"Daunting Roar","type":"bonus_action","description":"Creatures within 10 ft. make a WIS save (8 + PB + CON) or are frightened until the end of your next turn. 1/Short or Long Rest."}]}],"choices":[{"id":"leonin-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"leonin-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"leonin-skill","kind":"skill","count":1,"label":"Hunter's Instincts skill","source":"race","options":["Athletics","Intimidation","Perception","Survival"]},{"id":"leonin-hunter-instincts","kind":"skill","count":1,"source":"race","options":["Athletics","Intimidation","Perception","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; leonin tend toward good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Leonin","index":"leonin"}],"is_homebrew":false,"language_desc":"Common, Leonin","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'leonin'),
       source = 'Mythic Odysseys of Theros',
       migrated_at = now()
 where id = '099c101e-37ad-48a1-900b-f1f354fb068c';

-- Gnome (gnome)
update public.custom_races
   set data = $persona_content_migration${"id":"e29a38c4-df03-46b1-a162-5dd84af0d144","age":"Gnomes mature at the same rate as humans and can live 425 years.","desc":["Gnomes are magical folk created by gods of invention, illusion, and life underground. Small and tireless, they are brimming with curiosity and ingenuity, and every gnome traces their magic to either the forest or the rock."],"name":"Gnome","size":"Small","index":"gnome","speed":30,"source":"Player's Handbook (2024)","traits":[{"desc":["You have Darkvision with a range of 60 feet."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have Advantage on Intelligence, Wisdom, and Charisma saving throws."],"name":"Gnomish Cunning","index":"gnomish-cunning","effects":[{"name":"Advantage on saves: Intelligence","type":"advantage","value":1,"filter":"Intelligence","target":"saves"},{"name":"Advantage on saves: Wisdom","type":"advantage","value":1,"filter":"Wisdom","target":"saves"},{"name":"Advantage on saves: Charisma","type":"advantage","value":1,"filter":"Charisma","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Intelligence","type":"advantage","value":1,"filter":"Intelligence","target":"saves"},{"name":"Advantage on saves: Wisdom","type":"advantage","value":1,"filter":"Wisdom","target":"saves"},{"name":"Advantage on saves: Charisma","type":"advantage","value":1,"filter":"Charisma","target":"saves"}]},{"desc":["You are part of a lineage that grants you supernatural abilities. Choose Forest Gnome or Rock Gnome (see lineages). Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."],"name":"Gnomish Lineage","index":"gnomish-lineage","effects":[],"modifiers":[]}],"choices":[{"id":"gnome-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most gnomes are good.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Small (about 3–4 feet tall).","subraces_details":[{"desc":["Forest gnomes have a natural knack for illusion and a kinship with small animals."],"name":"Forest Gnome","index":"forest-gnome","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You know the Minor Illusion cantrip. You also always have the Speak with Animals spell prepared. You can cast it without a spell slot a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. You can also use any spell slots you have to cast the spell."],"name":"Forest Gnome Lineage","index":"forest-gnome-lineage","effects":[{"name":"Minor Illusion","type":"spell_access","spell":"Minor Illusion","condition":"Cantrip (INT, WIS, or CHA)"},{"name":"Speak with Animals","type":"spell_access","spell":"Speak with Animals","condition":"PB uses per Long Rest without a slot"}],"modifiers":[{"name":"Minor Illusion","type":"spell_access","spell":"Minor Illusion","condition":"Cantrip (INT, WIS, or CHA)"},{"name":"Speak with Animals","type":"spell_access","spell":"Speak with Animals","condition":"PB uses per Long Rest without a slot"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Rock gnomes are inventors and tinkerers with a gift for small, clever devices."],"name":"Rock Gnome","index":"rock-gnome","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["You know the Mending and Prestidigitation cantrips. In addition, you can spend 10 minutes casting Prestidigitation to create a Tiny clockwork device (AC 5, 1 HP), such as a toy, fire starter, or music box. When you create the device, you determine its function by choosing one effect from Prestidigitation; the device produces that effect whenever you or another creature takes a Bonus Action to activate it with a touch. If the chosen effect has options within it, you choose one of those options for the device when you create it. You can have three such devices in existence at a time, and each falls apart 8 hours after its creation or when you dismantle it with a touch as a Utilize action."],"name":"Rock Gnome Lineage","index":"rock-gnome-lineage","effects":[{"name":"Mending","type":"spell_access","spell":"Mending","condition":"Cantrip (INT, WIS, or CHA)"},{"name":"Prestidigitation","type":"spell_access","spell":"Prestidigitation","condition":"Cantrip (INT, WIS, or CHA)"}],"modifiers":[{"name":"Mending","type":"spell_access","spell":"Mending","condition":"Cantrip (INT, WIS, or CHA)"},{"name":"Prestidigitation","type":"spell_access","spell":"Prestidigitation","condition":"Cantrip (INT, WIS, or CHA)"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'gnome'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'e29a38c4-df03-46b1-a162-5dd84af0d144';

-- Warforged (warforged)
update public.custom_races
   set data = $persona_content_migration${"id":"effb3361-b9c5-48c7-8b44-2df44f165453","age":"A warforged reaches maturity about two years after being built; the oldest are around 30 and show no signs of aging.","desc":["Warforged are living constructs, built for the Last War and awakened to a life beyond it. Their bodies of wood, metal, and stone need no food or sleep, and each warforged chooses how to integrate armor into their very being."],"name":"Warforged","size":"Medium","index":"warforged","speed":30,"source":"Eberron: Rising from the Last War","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You were created to have remarkable fortitude, represented by the following benefits: you have advantage on saving throws against being poisoned, and you have resistance to poison damage; you don't need to eat, drink, or breathe; you are immune to disease; and you don't need to sleep, and magic can't put you to sleep."],"name":"Constructed Resilience","index":"constructed-resilience","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"name":"Disease","type":"immunity","value":"Disease","condition":"","damage_type":"Disease"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"No need to eat, drink, breathe, or sleep.","name":"Constructed Resilience","type":"feature","description":"No need to eat, drink, breathe, or sleep."}],"modifiers":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"name":"Disease","type":"immunity","value":"Disease","condition":"","damage_type":"Disease"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"No need to eat, drink, breathe, or sleep.","name":"Constructed Resilience","type":"feature","description":"No need to eat, drink, breathe, or sleep."}]},{"desc":["When you take a long rest, you must spend at least six hours in an inactive, motionless state, rather than sleeping. In this state, you appear inert, but it doesn't render you unconscious, and you can see and hear as normal."],"name":"Sentry's Rest","index":"sentry's-rest","effects":[{"desc":"Long rest is 6 hours of motionless inactivity; you remain aware.","name":"Sentry's Rest","type":"feature","description":"Long rest is 6 hours of motionless inactivity; you remain aware."}],"modifiers":[{"desc":"Long rest is 6 hours of motionless inactivity; you remain aware.","name":"Sentry's Rest","type":"feature","description":"Long rest is 6 hours of motionless inactivity; you remain aware."}]},{"desc":["Your body has built-in defensive layers, which can be enhanced with armor: you gain a +1 bonus to Armor Class; you can don only armor with which you have proficiency, and to don armor other than a shield you must incorporate it into your body over the course of 1 hour, during which you remain in contact with the armor; to doff armor you must spend 1 hour removing it; while you live, the armor incorporated into your body can't be removed against your will."],"name":"Integrated Protection","index":"integrated-protection","effects":[{"name":"Integrated Protection","type":"bonus","value":1,"target":"ac"}],"modifiers":[{"name":"Integrated Protection","type":"bonus","value":1,"target":"ac"}]},{"desc":["You gain one skill proficiency and one tool proficiency of your choice."],"name":"Specialized Design","index":"specialized-design","effects":[],"modifiers":[]}],"choices":[{"id":"warforged-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"warforged-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"warforged-skill","kind":"skill","count":1,"source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]},{"id":"warforged-tool","kind":"tool","count":1,"source":"race","options":["Alchemist's supplies","Brewer's supplies","Calligrapher's supplies","Carpenter's tools","Cartographer's tools","Cobbler's tools","Cook's utensils","Glassblower's tools","Jeweler's tools","Leatherworker's tools","Mason's tools","Painter's supplies","Potter's tools","Smith's tools","Tinker's tools","Weaver's tools","Woodcarver's tools"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most warforged are neutral.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'warforged'),
       source = 'Eberron: Rising from the Last War',
       migrated_at = now()
 where id = 'effb3361-b9c5-48c7-8b44-2df44f165453';

-- Loxodon (loxodon)
update public.custom_races
   set data = $persona_content_migration${"id":"d42ce979-6d24-422a-81e5-cd96ad494dc3","age":"Loxodons physically mature at the same rate as humans but live about 450 years.","desc":["Loxodons are elephantine humanoids from Ravnica, wise and serene, with thick hides and a prehensile trunk. They are slow to anger but immovable once roused, and their memories are as long as their lives."],"name":"Loxodon","size":"Medium","index":"loxodon","speed":30,"source":"Guildmasters' Guide to Ravnica","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."],"name":"Powerful Build","index":"powerful-build","effects":[{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}],"modifiers":[{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}]},{"desc":["You have advantage on saving throws against being charmed or frightened."],"name":"Loxodon Serenity","index":"loxodon-serenity","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"},{"name":"Advantage on saves: Frightened","type":"advantage","value":1,"filter":"Frightened","target":"saves"}]},{"desc":["You have thick, leathery skin. When you aren't wearing armor, your AC is 12 + your Constitution modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."],"name":"Natural Armor","index":"natural-armor","effects":[{"name":"Natural Armor","type":"set","value":12,"target":"ac"},{"name":"Natural Armor","stat":"ac","type":"stat_bonus_attribute","target":"ac","attribute":"con"}],"modifiers":[{"name":"Natural Armor","type":"set","value":12,"target":"ac"},{"name":"Natural Armor","stat":"ac","type":"stat_bonus_attribute","target":"ac","attribute":"con"}]},{"desc":["You can grasp things with your trunk, and you can use it as a snorkel. It has a reach of 5 feet, and it can lift a number of pounds equal to five times your Strength score. You can use it to do the following simple tasks: lift, drop, hold, push, or pull an object or a creature; open or close a door or a container; grapple someone; or make an unarmed strike. Your DM might allow other simple tasks to be added to that list of options. Your trunk can't wield weapons or shields or do anything that requires manual precision, such as using tools or magic items or performing the somatic components of a spell."],"name":"Trunk","index":"trunk","effects":[{"desc":"5-ft. reach prehensile trunk for simple tasks, grappling, or unarmed strikes; lifts 5 × STR pounds.","name":"Trunk","type":"feature","description":"5-ft. reach prehensile trunk for simple tasks, grappling, or unarmed strikes; lifts 5 × STR pounds."}],"modifiers":[{"desc":"5-ft. reach prehensile trunk for simple tasks, grappling, or unarmed strikes; lifts 5 × STR pounds.","name":"Trunk","type":"feature","description":"5-ft. reach prehensile trunk for simple tasks, grappling, or unarmed strikes; lifts 5 × STR pounds."}]},{"desc":["Thanks to your sensitive trunk, you have advantage on Wisdom (Perception), Wisdom (Survival), and Intelligence (Investigation) checks that involve smell."],"name":"Keen Smell","index":"keen-smell","effects":[{"desc":"Advantage on Perception, Survival, and Investigation checks involving smell.","name":"Keen Smell","type":"feature","description":"Advantage on Perception, Survival, and Investigation checks involving smell."}],"modifiers":[{"desc":"Advantage on Perception, Survival, and Investigation checks involving smell.","name":"Keen Smell","type":"feature","description":"Advantage on Perception, Survival, and Investigation checks involving smell."}]}],"choices":[{"id":"loxodon-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"loxodon-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; most loxodons are lawful.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Loxodon","index":"loxodon"}],"is_homebrew":false,"language_desc":"Common, Loxodon","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 7–8 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'loxodon'),
       source = 'Guildmasters'' Guide to Ravnica',
       migrated_at = now()
 where id = 'd42ce979-6d24-422a-81e5-cd96ad494dc3';

-- Harengon (harengon)
update public.custom_races
   set data = $persona_content_migration${"id":"df1cdd03-c40e-45c3-8c5d-4fa3cb66ddaf","age":"Harengons mature and age at about the same rate as humans.","desc":["Harengons are rabbitfolk who originated in the Feywild and have since spread to many worlds. Quick-witted and quicker on their feet, they are blessed with a little fey luck and an irrepressible hop."],"name":"Harengon","size":"Small or Medium","index":"harengon","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can add your proficiency bonus to your initiative rolls."],"name":"Hare-Trigger","index":"hare-trigger","effects":[{"name":"Hare-Trigger","type":"stat_bonus","target":"initiative","scaling":"proficiency","description":"Add your Proficiency Bonus to initiative rolls."}],"modifiers":[{"name":"Hare-Trigger","type":"stat_bonus","target":"initiative","scaling":"proficiency","description":"Add your Proficiency Bonus to initiative rolls."}]},{"desc":["You have proficiency in the Perception skill."],"name":"Leporine Senses","index":"leporine-senses","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}]},{"desc":["When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're prone or your speed is 0."],"name":"Lucky Footwork","index":"lucky-footwork","effects":[{"desc":"Add 1d4 to a failed Dexterity saving throw (not while prone or at speed 0).","name":"Lucky Footwork","type":"reaction","description":"Add 1d4 to a failed Dexterity saving throw (not while prone or at speed 0)."}],"modifiers":[{"desc":"Add 1d4 to a failed Dexterity saving throw (not while prone or at speed 0).","name":"Lucky Footwork","type":"reaction","description":"Add 1d4 to a failed Dexterity saving throw (not while prone or at speed 0)."}]},{"desc":["As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Rabbit Hop","index":"rabbit-hop","effects":[{"desc":"Jump 5 × PB feet without provoking. PB uses per Long Rest.","name":"Rabbit Hop","type":"bonus_action","description":"Jump 5 × PB feet without provoking. PB uses per Long Rest."}],"modifiers":[{"desc":"Jump 5 × PB feet without provoking. PB uses per Long Rest.","name":"Rabbit Hop","type":"bonus_action","description":"Jump 5 × PB feet without provoking. PB uses per Long Rest."}]}],"choices":[{"id":"harengon-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"harengon-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small (about 2–4 feet tall), chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'harengon'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = 'df1cdd03-c40e-45c3-8c5d-4fa3cb66ddaf';

-- Chromatic Dragonborn (chromatic-dragonborn)
update public.custom_races
   set data = $persona_content_migration${"id":"35a326a4-402c-46a8-9691-d7ae9d7b645b","age":"Dragonborn reach adulthood by 15 and live about 80 years.","desc":["Chromatic dragonborn carry the blood of black, blue, green, red, and white dragons. Their scales gleam in a single hue, and the raw elemental power of their ancestors lets them exhale destruction and, in time, ward themselves against it entirely."],"name":"Chromatic Dragonborn","size":"Medium","index":"chromatic-dragonborn","speed":30,"source":"Fizban's Treasury of Dragons","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You trace your ancestry to a chromatic dragon. Choose your ancestor (see ancestries); its damage type determines your Breath Weapon and Draconic Resistance."],"name":"Chromatic Ancestry","index":"chromatic-ancestry","effects":[],"modifiers":[]},{"desc":["When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Breath Weapon","index":"breath-weapon","effects":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}],"modifiers":[{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest.","name":"Breath Weapon","type":"feature","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 ancestry damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th). PB uses per Long Rest."}]},{"desc":["You have resistance to the damage type associated with your ancestry."],"name":"Draconic Resistance","index":"draconic-resistance","effects":[],"modifiers":[]},{"desc":["Starting at 5th level, as an action, you can channel your draconic energy to protect yourself. For 1 minute, you become immune to the damage type associated with your Chromatic Ancestry. Once you use this trait, you can't do so again until you finish a Long Rest."],"name":"Chromatic Warding","index":"chromatic-warding","effects":[{"desc":"From level 5: immunity to your ancestry's damage type for 1 minute. 1/Long Rest.","name":"Chromatic Warding","type":"action","description":"From level 5: immunity to your ancestry's damage type for 1 minute. 1/Long Rest."}],"modifiers":[{"desc":"From level 5: immunity to your ancestry's damage type for 1 minute. 1/Long Rest.","name":"Chromatic Warding","type":"action","description":"From level 5: immunity to your ancestry's damage type for 1 minute. 1/Long Rest."}]}],"choices":[{"id":"chromatic-dragonborn-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"chromatic-dragonborn-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"chromatic-ancestry","kind":"ancestry","count":1,"label":"Draconic Ancestry","source":"race","options":[{"desc":"Black dragon ancestry: Acid breath weapon and resistance.","name":"Black (Acid)","effects":[{"name":"Acid Resistance","type":"resistance","value":"Acid","damage_type":"Acid"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Acid damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Acid)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Acid damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Blue dragon ancestry: Lightning breath weapon and resistance.","name":"Blue (Lightning)","effects":[{"name":"Lightning Resistance","type":"resistance","value":"Lightning","damage_type":"Lightning"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Lightning damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Lightning)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Lightning damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Green dragon ancestry: Poison breath weapon and resistance.","name":"Green (Poison)","effects":[{"name":"Poison Resistance","type":"resistance","value":"Poison","damage_type":"Poison"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Poison damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Poison)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Poison damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"Red dragon ancestry: Fire breath weapon and resistance.","name":"Red (Fire)","effects":[{"name":"Fire Resistance","type":"resistance","value":"Fire","damage_type":"Fire"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Fire)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Fire damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]},{"desc":"White dragon ancestry: Cold breath weapon and resistance.","name":"White (Cold)","effects":[{"name":"Cold Resistance","type":"resistance","value":"Cold","damage_type":"Cold"},{"desc":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Cold damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest.","name":"Breath Weapon (Cold)","type":"action","description":"Replace one attack with a 15-ft. cone: DEX save (8 + CON + PB) or 1d10 Cold damage (2d10 at 5th, 3d10 at 11th, 4d10 at 17th), half on a success. PB uses per Long Rest."}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"},{"url":"","name":"Draconic","index":"draconic"}],"is_homebrew":false,"language_desc":"Common, Draconic","schema_version":2,"ability_bonuses":[],"language_options":0,"size_description":"Medium (about 6–7 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
