-- Genasi (genasi)
update public.custom_races
   set data = $persona_content_migration${"id":"2b5c4608-cc07-4c09-aab6-c39c057d386d","age":"Genasi mature at the same rate as humans and live about 120 years.","desc":["Genasi carry the power of the Elemental Planes in their blood. Each is tied to one of the four elements — air, earth, fire, or water — and that heritage shows in their appearance and in the elemental magic they can call upon."],"name":"Genasi","size":"Small or Medium","index":"genasi","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["Choose the element of your heritage: Air, Earth, Fire, or Water Genasi (see subraces). Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with your genasi traits (choose when you select this race)."],"name":"Elemental Heritage","index":"elemental-heritage","effects":[]}],"choices":[{"id":"genasi-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"genasi-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"genasi-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 4–7 feet tall) or Small (about 3–4 feet tall), chosen when you select this species.","subraces_details":[{"desc":["Air genasi are descended from djinn, and their blood carries the power of the winds."],"name":"Air Genasi","index":"air-genasi","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Your walking speed is 35 feet. Unending Breath: you can hold your breath indefinitely while you're not incapacitated. Lightning Resistance: you have resistance to lightning damage. Mingle with the Wind: you know the Shocking Grasp cantrip. Starting at 3rd level, you can cast the Feather Fall spell with this trait, without a material component. Starting at 5th level, you can also cast the Levitate spell with this trait, without a material component. Once you cast Feather Fall or Levitate with this trait, you can't cast that spell with it again until you finish a Long Rest."],"name":"Air Genasi Traits","index":"air-genasi-traits","effects":[{"name":"Speed","type":"bonus","value":5,"target":"speed"},{"name":"Lightning","type":"resistance","value":"Lightning","condition":"","damage_type":"Lightning"},{"name":"Shocking Grasp","type":"spell_access","spell":"Shocking Grasp","condition":"Cantrip"},{"name":"Feather Fall","type":"spell_access","spell":"Feather Fall","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Levitate","type":"spell_access","spell":"Levitate","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"},{"desc":"Hold your breath indefinitely while not incapacitated.","name":"Unending Breath","type":"feature","description":"Hold your breath indefinitely while not incapacitated."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Earth genasi are descended from dao, with the strength and patience of stone."],"name":"Earth Genasi","index":"earth-genasi","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Earth Walk: you can move across difficult terrain without expending extra movement if you are using your walking speed on the ground or a floor. Merge with Stone: you know the Blade Ward cantrip; you can cast it as a bonus action a number of times equal to your proficiency bonus, regaining all uses when you finish a Long Rest. Starting at 5th level, you can cast the Pass without Trace spell with this trait, without a material component; once you cast it with this trait, you can't do so again until you finish a Long Rest."],"name":"Earth Genasi Traits","index":"earth-genasi-traits","effects":[{"name":"Blade Ward","type":"spell_access","spell":"Blade Ward","condition":"Cantrip; cast as a bonus action PB times per Long Rest"},{"name":"Pass without Trace","type":"spell_access","spell":"Pass without Trace","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"},{"desc":"Ignore difficult terrain when walking on the ground.","name":"Earth Walk","type":"feature","description":"Ignore difficult terrain when walking on the ground."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Fire genasi are descended from efreet, their bodies kindled with elemental flame."],"name":"Fire Genasi","index":"fire-genasi","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Darkvision: you can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. Fire Resistance: you have resistance to fire damage. Reach to the Blaze: you know the Produce Flame cantrip. Starting at 3rd level, you can cast the Burning Hands spell with this trait. Starting at 5th level, you can also cast the Flame Blade spell with this trait, without a material component. Once you cast Burning Hands or Flame Blade with this trait, you can't cast that spell with it again until you finish a Long Rest."],"name":"Fire Genasi Traits","index":"fire-genasi-traits","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"},{"name":"Fire","type":"resistance","value":"Fire","condition":"","damage_type":"Fire"},{"name":"Produce Flame","type":"spell_access","spell":"Produce Flame","condition":"Cantrip"},{"name":"Burning Hands","type":"spell_access","spell":"Burning Hands","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Flame Blade","type":"spell_access","spell":"Flame Blade","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Water genasi are descended from marids, and the sea answers their call."],"name":"Water Genasi","index":"water-genasi","source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"url":"","desc":["Acid Resistance: you have resistance to acid damage. Amphibious: you can breathe air and water. Swim: you have a swimming speed equal to your walking speed. Call to the Wave: you know the Acid Splash cantrip. Starting at 3rd level, you can cast the Create or Destroy Water spell with this trait. Starting at 5th level, you can also cast the Water Walk spell with this trait, without a material component. Once you cast Create or Destroy Water or Water Walk with this trait, you can't cast that spell with it again until you finish a Long Rest."],"name":"Water Genasi Traits","index":"water-genasi-traits","effects":[{"name":"Acid","type":"resistance","value":"Acid","condition":"","damage_type":"Acid"},{"name":"Swim","type":"set","value":30,"target":"swim_speed"},{"name":"Acid Splash","type":"spell_access","spell":"Acid Splash","condition":"Cantrip"},{"name":"Create or Destroy Water","type":"spell_access","spell":"Create or Destroy Water","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"},{"name":"Water Walk","type":"spell_access","spell":"Water Walk","condition":"From level 5; 1/Long Rest without a slot","min_level":5,"free_casts":1,"free_cast_reset":"long"},{"desc":"Breathe air and water.","name":"Amphibious","type":"feature","description":"Breathe air and water."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'genasi'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '2b5c4608-cc07-4c09-aab6-c39c057d386d';

-- Aarakocra (aarakocra)
update public.custom_races
   set data = $persona_content_migration${"id":"7f5977b3-ee07-443d-8019-6b4bf47f82d7","age":"Aarakocra reach maturity by age 3 and can live to be 30.","desc":["Aarakocra are winged people who originated on the Elemental Plane of Air. Their feathered bodies, keen eyes, and talons mark them as creatures of the open sky, and many serve the wind dukes or wander the Material Plane as scouts and messengers."],"name":"Aarakocra","size":"Medium","index":"aarakocra","speed":30,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[]},{"desc":["Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."],"name":"Flight","index":"flight","effects":[{"desc":"Fly Speed equal to your walking speed (30 ft.); not usable in medium or heavy armor.","name":"Flight","type":"feature","description":"Fly Speed equal to your walking speed (30 ft.); not usable in medium or heavy armor."}]},{"desc":["You have talons that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Talons","index":"talons","effects":[{"die":"1d6","name":"Talons","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Slashing"}]},{"desc":["Starting at 3rd level, you can cast the Gust of Wind spell with this trait, without requiring a material component. Once you cast the spell with this trait, you can't do so again until you finish a Long Rest. You can also cast the spell using any spell slots you have of 2nd level or higher. Intelligence, Wisdom, or Charisma is your spellcasting ability for it when you cast it with this trait (choose when you select this race)."],"name":"Wind Caller","index":"wind-caller","effects":[{"name":"Gust of Wind","type":"spell_access","spell":"Gust of Wind","condition":"From level 3; 1/Long Rest without a slot","min_level":3,"free_casts":1,"free_cast_reset":"long"}]}],"choices":[{"id":"aarakocra-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"aarakocra-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"aarakocra-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; many aarakocra are good.","fly_speed":30,"is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5 feet tall), with a 20-foot wingspan.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'aarakocra'),
       source = 'Mordenkainen Presents: Monsters of the Multiverse',
       migrated_at = now()
 where id = '7f5977b3-ee07-443d-8019-6b4bf47f82d7';

-- Reborn (reborn)
update public.custom_races
   set data = $persona_content_migration${"id":"5663d2f2-f8b4-4d9e-83ba-01bd42220bf0","age":"Reborn don't age the way the living do and might persist for centuries.","desc":["Reborn are people who have died and returned — stitched back together, raised by strange magic, or simply awoken in a grave with no memory of before. Their deathless bodies need no food or sleep, and fragments of a past life sometimes surface to guide them."],"name":"Reborn","size":"Small or Medium","index":"reborn","speed":30,"source":"Van Richten's Guide to Ravenloft","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."],"name":"Ancestral Legacy","index":"ancestral-legacy","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have escaped death, a fact represented by the following benefits: you have advantage on saving throws against disease and being poisoned, and you have resistance to poison damage; you have advantage on death saving throws; you don't need to eat, drink, or breathe; and you don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."],"name":"Deathless Nature","index":"deathless-nature","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"name":"Advantage on saves: Disease","type":"advantage","value":1,"filter":"Disease","target":"saves"},{"name":"Advantage on saves: Death saves","type":"advantage","value":1,"filter":"Death saves","target":"saves"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"No need to eat, drink, breathe, or sleep; long rest in 4 motionless hours.","name":"Deathless Nature","type":"feature","description":"No need to eat, drink, breathe, or sleep; long rest in 4 motionless hours."}],"modifiers":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"name":"Advantage on saves: Disease","type":"advantage","value":1,"filter":"Disease","target":"saves"},{"name":"Advantage on saves: Death saves","type":"advantage","value":1,"filter":"Death saves","target":"saves"},{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"No need to eat, drink, breathe, or sleep; long rest in 4 motionless hours.","name":"Deathless Nature","type":"feature","description":"No need to eat, drink, breathe, or sleep; long rest in 4 motionless hours."}]},{"desc":["You temporarily remember glimpses of the past, perhaps faded memories from ages ago or a previous life. When you make an ability check that uses a skill, you can roll a d6 immediately after seeing the number on the d20 and add the number on the d6 to the check. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Knowledge from a Past Life","index":"knowledge-from-a-past-life","effects":[{"desc":"Add 1d6 to a skill check after seeing the d20. PB uses per Long Rest.","name":"Knowledge from a Past Life","type":"feature","description":"Add 1d6 to a skill check after seeing the d20. PB uses per Long Rest."}],"modifiers":[{"desc":"Add 1d6 to a skill check after seeing the d20. PB uses per Long Rest.","name":"Knowledge from a Past Life","type":"feature","description":"Add 1d6 to a skill check after seeing the d20. PB uses per Long Rest."}]}],"choices":[{"id":"reborn-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"reborn-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"reborn-skills","kind":"skill","count":2,"label":"Ancestral Legacy skills","source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium or Small, chosen when you select this lineage.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'reborn'),
       source = 'Van Richten''s Guide to Ravenloft',
       migrated_at = now()
 where id = '5663d2f2-f8b4-4d9e-83ba-01bd42220bf0';

-- Astral Elf (astral-elf)
update public.custom_races
   set data = $persona_content_migration${"id":"879be107-9bb4-43fe-bc00-1ec50bcb61a4","age":"Astral elves on the Astral Plane don't age; elsewhere they can live to be 750.","desc":["Long ago, groups of elves left the Feywild and settled on the Astral Plane, where the plane's timelessness and their god Corellon's influence transformed them. Astral elves have star-bright eyes and can step through space in a flash of starlight."],"name":"Astral Elf","size":"Medium","index":"astral-elf","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You know one of the following cantrips of your choice: Dancing Lights, Light, or Sacred Flame. Intelligence, Wisdom, or Charisma is your spellcasting ability for it (choose when you select this race)."],"name":"Astral Fire","index":"astral-fire","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You have advantage on saving throws you make to avoid or end the charmed condition on yourself."],"name":"Fey Ancestry","index":"fey-ancestry","effects":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Charmed","type":"advantage","value":1,"filter":"Charmed","target":"saves"}]},{"desc":["You have proficiency in the Perception skill."],"name":"Keen Senses","index":"keen-senses","effects":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"},{"type":"proficiency","target":"Perception","category":"skill"}],"modifiers":[{"name":"Perception","type":"proficiency","value":"Perception","target":"Perception","category":"skill"}]},{"desc":["As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Starlight Step","index":"starlight-step","effects":[{"desc":"Teleport up to 30 ft. PB uses per Long Rest.","name":"Starlight Step","type":"bonus_action","description":"Teleport up to 30 ft. PB uses per Long Rest."}],"modifiers":[{"desc":"Teleport up to 30 ft. PB uses per Long Rest.","name":"Starlight Step","type":"bonus_action","description":"Teleport up to 30 ft. PB uses per Long Rest."}]},{"desc":["You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in a trancelike meditation, during which you remain conscious. Whenever you finish this trance, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next Long Rest."],"name":"Astral Trance","index":"astral-trance","effects":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long Rest in 4 hours; afterwards gain one skill and one weapon/tool proficiency until your next Long Rest.","name":"Astral Trance","type":"feature","description":"Long Rest in 4 hours; afterwards gain one skill and one weapon/tool proficiency until your next Long Rest."}],"modifiers":[{"name":"Magical Sleep","type":"immunity","value":"Magical Sleep","condition":"Magic can't put you to sleep","damage_type":"Magical Sleep"},{"desc":"Long Rest in 4 hours; afterwards gain one skill and one weapon/tool proficiency until your next Long Rest.","name":"Astral Trance","type":"feature","description":"Long Rest in 4 hours; afterwards gain one skill and one weapon/tool proficiency until your next Long Rest."}]}],"choices":[{"id":"astral-elf-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"astral-elf-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"astral-elf-cantrip","kind":"ancestry","count":1,"label":"Astral Fire cantrip","source":"race","options":[{"desc":"You know the Dancing Lights cantrip.","name":"Dancing Lights","effects":[{"name":"Dancing Lights","type":"spell_access","spell":"Dancing Lights","condition":"Cantrip"}]},{"desc":"You know the Light cantrip.","name":"Light","effects":[{"name":"Light","type":"spell_access","spell":"Light","condition":"Cantrip"}]},{"desc":"You know the Sacred Flame cantrip.","name":"Sacred Flame","effects":[{"name":"Sacred Flame","type":"spell_access","spell":"Sacred Flame","condition":"Cantrip"}]}]},{"id":"astral-elf-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'astral-elf'),
       source = 'Spelljammer: Adventures in Space',
       migrated_at = now()
 where id = '879be107-9bb4-43fe-bc00-1ec50bcb61a4';

-- Hexblood (hexblood)
update public.custom_races
   set data = $persona_content_migration${"id":"89c662df-54a8-4ff1-8c09-8f38144e9579","age":"Hexbloods age at the rate of their original race but often live longer.","desc":["Hexbloods are individuals infused with eldritch magic, fey energy, or hag power. Often created by a bargain with a hag, they bear the marks of their origin — long ears, vivid eyes, and an eerie magic that lets them scry and whisper through tokens of hair and nail."],"name":"Hexblood","size":"Small or Medium","index":"hexblood","speed":30,"source":"Van Richten's Guide to Ravenloft","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[]},{"desc":["If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."],"name":"Ancestral Legacy","index":"ancestral-legacy","effects":[]},{"desc":["You are a Fey."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["As a bonus action, you can harmlessly remove a lock of your hair, one of your nails, or one of your teeth. This token is imbued with magic until you finish a Long Rest. While the token is imbued in this way, you can take these actions: Telepathic Message — as an action, you can send a telepathic message to the creature holding or carrying the token, as long as you are within 10 miles of it; the message can contain up to twenty-five words. Remote Viewing — if you are within 10 miles of the token, you can enter a trance as an action, remaining in the trance for 1 minute or until your concentration is broken; during the trance you can see and hear from the token as if you were located where it is, and you are blinded and deafened to your own surroundings. Once you create a token using this feature, you can't do so again until you finish a Long Rest, at which point your missing part regrows."],"name":"Eerie Token","index":"eerie-token","effects":[{"desc":"Create a magic token (hair, nail, or tooth) that lets you send a 25-word telepathic message or scry through it from up to 10 miles. 1/Long Rest.","name":"Eerie Token","type":"bonus_action","description":"Create a magic token (hair, nail, or tooth) that lets you send a 25-word telepathic message or scry through it from up to 10 miles. 1/Long Rest."}]},{"desc":["You can cast the Disguise Self and Hex spells with this trait. Once you cast either spell with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast these spells using spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this lineage)."],"name":"Hex Magic","index":"hex-magic","effects":[{"name":"Disguise Self","type":"spell_access","spell":"Disguise Self","condition":"1/Long Rest without a slot","free_casts":1,"free_cast_reset":"long"},{"name":"Hex","type":"spell_access","spell":"Hex","condition":"1/Long Rest without a slot","free_casts":1,"free_cast_reset":"long"}]}],"choices":[{"id":"hexblood-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"hexblood-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"hexblood-skills","kind":"skill","count":2,"label":"Ancestral Legacy skills","source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]},{"id":"hexblood-spellcasting-ability","kind":"spellcasting_ability","count":1,"label":"Spellcasting ability for your racial spells","source":"race","options":["int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium or Small, chosen when you select this lineage.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'hexblood'),
       source = 'Van Richten''s Guide to Ravenloft',
       migrated_at = now()
 where id = '89c662df-54a8-4ff1-8c09-8f38144e9579';

-- Autognome (autognome)
update public.custom_races
   set data = $persona_content_migration${"id":"321152b9-a4cb-4e35-bf33-f9dbd627b0de","age":"Autognomes don't age and don't die of old age.","desc":["Autognomes are mechanical beings built by rock gnomes in their own image. Each is a living construct with an armored casing, a built-in instinct for success, and an inner workshop that lets it mend itself."],"name":"Autognome","size":"Small","index":"autognome","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Construct."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Construct (not Humanoid).","name":"Construct","type":"feature","description":"Your creature type is Construct (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Construct (not Humanoid).","name":"Construct","type":"feature","description":"Your creature type is Construct (not Humanoid)."}]},{"desc":["You are encased in thin metal or some other durable material. While you aren't wearing armor, your base Armor Class is 13 + your Dexterity modifier."],"name":"Armored Casing","index":"armored-casing","effects":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"}],"modifiers":[{"name":"Natural Armor","type":"set","value":13,"target":"ac"}]},{"desc":["You can add a d4 to one attack roll, ability check, or saving throw you make, and you can do so after seeing the d20 roll but before the effects of the roll are resolved. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Built for Success","index":"built-for-success","effects":[{"desc":"Add 1d4 to an attack roll, check, or save after seeing the d20. PB uses per Long Rest.","name":"Built for Success","type":"feature","description":"Add 1d4 to an attack roll, check, or save after seeing the d20. PB uses per Long Rest."}],"modifiers":[{"desc":"Add 1d4 to an attack roll, check, or save after seeing the d20. PB uses per Long Rest.","name":"Built for Success","type":"feature","description":"Add 1d4 to an attack roll, check, or save after seeing the d20. PB uses per Long Rest."}]},{"desc":["If the Mending spell is cast on you, you can spend a Hit Die, roll it, and regain a number of hit points equal to the roll plus your Constitution modifier (minimum of 1 hit point). In addition, your creator designed you to benefit from several spells that preserve life but that normally don't affect Constructs: Cure Wounds, Healing Word, Mass Cure Wounds, Mass Healing Word, and Spare the Dying."],"name":"Healing Machine","index":"healing-machine","effects":[{"desc":"Mending lets you spend a Hit Die to heal; healing spells affect you normally.","name":"Healing Machine","type":"feature","description":"Mending lets you spend a Hit Die to heal; healing spells affect you normally."}],"modifiers":[{"desc":"Mending lets you spend a Hit Die to heal; healing spells affect you normally.","name":"Healing Machine","type":"feature","description":"Mending lets you spend a Hit Die to heal; healing spells affect you normally."}]},{"desc":["You have resistance to poison damage and immunity to disease, and you have advantage on saving throws against being paralyzed or poisoned. You don't need to eat, drink, or breathe."],"name":"Mechanical Nature","index":"mechanical-nature","effects":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Disease","type":"immunity","value":"Disease","condition":"","damage_type":"Disease"},{"name":"Advantage on saves: Paralyzed","type":"advantage","value":1,"filter":"Paralyzed","target":"saves"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"desc":"No need to eat, drink, or breathe.","name":"Mechanical Nature","type":"feature","description":"No need to eat, drink, or breathe."}],"modifiers":[{"name":"Poison","type":"resistance","value":"Poison","condition":"","damage_type":"Poison"},{"name":"Disease","type":"immunity","value":"Disease","condition":"","damage_type":"Disease"},{"name":"Advantage on saves: Paralyzed","type":"advantage","value":1,"filter":"Paralyzed","target":"saves"},{"name":"Advantage on saves: Poisoned","type":"advantage","value":1,"filter":"Poisoned","target":"saves"},{"desc":"No need to eat, drink, or breathe.","name":"Mechanical Nature","type":"feature","description":"No need to eat, drink, or breathe."}]},{"desc":["When you take a long rest, you spend at least six hours in an inactive, motionless state, instead of sleeping. In this state, you appear inert, but you aren't unconscious, and you can see and hear as normal."],"name":"Sentry's Rest","index":"sentry's-rest","effects":[{"desc":"Long rest is 6 hours of motionless inactivity; you remain aware.","name":"Sentry's Rest","type":"feature","description":"Long rest is 6 hours of motionless inactivity; you remain aware."}],"modifiers":[{"desc":"Long rest is 6 hours of motionless inactivity; you remain aware.","name":"Sentry's Rest","type":"feature","description":"Long rest is 6 hours of motionless inactivity; you remain aware."}]},{"desc":["You gain two tool proficiencies of your choice, selected from the Player's Handbook."],"name":"Specialized Design","index":"specialized-design","effects":[],"modifiers":[]}],"choices":[{"id":"autognome-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"autognome-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"autognome-tools","kind":"tool","count":2,"label":"Specialized Design tools","source":"race","options":["Alchemist's Supplies","Brewer's Supplies","Calligrapher's Supplies","Carpenter's Tools","Cartographer's Tools","Cobbler's Tools","Cook's Utensils","Glassblower's Tools","Jeweler's Tools","Leatherworker's Tools","Mason's Tools","Painter's Supplies","Potter's Tools","Smith's Tools","Tinker's Tools","Weaver's Tools","Woodcarver's Tools","Disguise Kit","Forgery Kit","Herbalism Kit","Navigator's Tools","Poisoner's Kit","Thieves' Tools","Gaming Set","Musical Instrument","Vehicles (Land)","Vehicles (Water)"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Small (about 3 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'autognome'),
       source = 'Spelljammer: Adventures in Space',
       migrated_at = now()
 where id = '321152b9-a4cb-4e35-bf33-f9dbd627b0de';

-- Dhampir (dhampir)
update public.custom_races
   set data = $persona_content_migration${"id":"2ff57fb1-e8f3-4f1f-a36c-2f5db958b4e5","age":"Dhampirs mature like humans but can live far longer.","desc":["Poised between the worlds of the living and the dead, dhampirs retain their grip on life yet are cursed with vampiric hunger. Whatever their origin, they walk on walls, see in the dark, and can drink the blood of the living to empower themselves."],"name":"Dhampir","size":"Small or Medium","index":"dhampir","speed":35,"source":"Van Richten's Guide to Ravenloft","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."],"name":"Ancestral Legacy","index":"ancestral-legacy","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."],"name":"Darkvision","index":"darkvision","effects":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}],"modifiers":[{"name":"Darkvision","type":"set","value":60,"target":"darkvision"}]},{"desc":["You don't need to breathe."],"name":"Deathless Nature","index":"deathless-nature","effects":[{"desc":"You don't need to breathe.","name":"Deathless Nature","type":"feature","description":"You don't need to breathe."}],"modifiers":[{"desc":"You don't need to breathe.","name":"Deathless Nature","type":"feature","description":"You don't need to breathe."}]},{"desc":["You have a climbing speed equal to your walking speed. In addition, at 3rd level, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free."],"name":"Spider Climb","index":"spider-climb","effects":[{"desc":"Climb Speed equal to your walking speed; from level 3, climb walls and ceilings hands-free.","name":"Spider Climb","type":"feature","description":"Climb Speed equal to your walking speed; from level 3, climb walls and ceilings hands-free."}],"modifiers":[{"desc":"Climb Speed equal to your walking speed; from level 3, climb walls and ceilings hands-free.","name":"Spider Climb","type":"feature","description":"Climb Speed equal to your walking speed; from level 3, climb walls and ceilings hands-free."}]},{"desc":["Your fanged bite is a natural weapon, which counts as a simple melee weapon with which you are proficient. You add your Constitution modifier, instead of your Strength modifier, to the attack and damage rolls when you attack with this bite. It deals 1d4 piercing damage on a hit. While you are missing at least half your hit points, you have advantage on attack rolls you make with this bite. When you attack with this bite and hit a creature that isn't a construct or an undead, you can empower yourself in one of the following ways of your choice: regain hit points equal to the piercing damage dealt by the bite; or gain a bonus to the next ability check or attack roll you make equal to the piercing damage dealt by the bite. You can empower yourself with this bite a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Vampiric Bite","index":"vampiric-bite","effects":[{"desc":"1d4 + CON piercing bite (simple weapon); advantage when below half HP; on a hit, heal or gain a bonus equal to the damage. PB empowered uses per Long Rest.","name":"Vampiric Bite","type":"feature","description":"1d4 + CON piercing bite (simple weapon); advantage when below half HP; on a hit, heal or gain a bonus equal to the damage. PB empowered uses per Long Rest."},{"die":"1d4","name":"Vampiric Bite","type":"unarmed_strike","value":"1d4","ability":"con","damage_die":"1d4","damage_type":"Piercing"}],"modifiers":[{"desc":"1d4 + CON piercing bite (simple weapon); advantage when below half HP; on a hit, heal or gain a bonus equal to the damage. PB empowered uses per Long Rest.","name":"Vampiric Bite","type":"feature","description":"1d4 + CON piercing bite (simple weapon); advantage when below half HP; on a hit, heal or gain a bonus equal to the damage. PB empowered uses per Long Rest."},{"die":"1d4","name":"Vampiric Bite","type":"unarmed_strike","value":"1d4","ability":"con","damage_die":"1d4","damage_type":"Piercing"}]}],"choices":[{"id":"dhampir-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"dhampir-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"dhampir-skills","kind":"skill","count":2,"label":"Ancestral Legacy skills","source":"race","options":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"climb_speed":35,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium or Small, chosen when you select this lineage.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
