-- Goliath (goliath)
update public.custom_races
   set data = $persona_content_migration${"id":"2d960328-7fbe-45a0-a9ad-47d25ea20a8e","age":"Goliaths have lifespans comparable to humans.","desc":["Goliaths are distant descendants of giants, and each carries the legacy of one of the giant kinds — cloud, fire, frost, hill, stone, or storm. Towering and powerfully built, they are at home in the high mountains and harsh places where only the strong endure."],"name":"Goliath","size":"Medium","index":"goliath","speed":35,"source":"Player's Handbook (2024)","traits":[{"desc":["You are descended from Giants. Choose one of the supernatural boons from your ancestry (see ancestries). You can use the chosen boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."],"name":"Giant Ancestry","index":"giant-ancestry","effects":[],"modifiers":[]},{"desc":["Starting at character level 5, you can change your size to Large as a Bonus Action if you're in a big enough space. This transformation lasts for 10 minutes or until you end it (no action required). For that duration, you have Advantage on Strength checks, and your Speed increases by 10 feet. Once you use this trait, you can't use it again until you finish a Long Rest."],"name":"Large Form","index":"large-form","effects":[{"desc":"From level 5: become Large for 10 minutes, with Advantage on Strength checks and +10 ft. Speed. 1/Long Rest.","name":"Large Form","type":"bonus_action","description":"From level 5: become Large for 10 minutes, with Advantage on Strength checks and +10 ft. Speed. 1/Long Rest."}],"modifiers":[{"desc":"From level 5: become Large for 10 minutes, with Advantage on Strength checks and +10 ft. Speed. 1/Long Rest.","name":"Large Form","type":"bonus_action","description":"From level 5: become Large for 10 minutes, with Advantage on Strength checks and +10 ft. Speed. 1/Long Rest."}]},{"desc":["You have Advantage on any saving throw you make to end the Grappled condition. You also count as one size larger when determining your carrying capacity."],"name":"Powerful Build","index":"powerful-build","effects":[{"name":"Advantage on saves: Grappled","type":"advantage","value":1,"filter":"Grappled","target":"saves"},{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}],"modifiers":[{"name":"Advantage on saves: Grappled","type":"advantage","value":1,"filter":"Grappled","target":"saves"},{"desc":"Count as one size larger for carrying capacity.","name":"Powerful Build","type":"feature","description":"Count as one size larger for carrying capacity."}]}],"choices":[{"id":"goliath-giant-ancestry","kind":"ancestry","count":1,"label":"Giant Ancestry","level":1,"source":"race","options":[{"desc":"Teleport up to 30 feet as a Bonus Action.","name":"Cloud's Jaunt","effects":[{"name":"Cloud's Jaunt","type":"bonus_action","description":"Teleport up to 30 feet as a Bonus Action."}]},{"desc":"Once per turn, deal an extra 1d10 Fire damage on a hit.","name":"Fire's Burn","effects":[{"name":"Fire's Burn","type":"attack_rider","damage":"1d10","condition":"weapon","damage_type":"Fire","description":"Once per turn, deal an extra 1d10 Fire damage on a hit."}]},{"desc":"Once per turn, deal an extra 1d6 Cold damage and reduce the target’s Speed by 10 feet.","name":"Frost's Chill","effects":[{"name":"Frost's Chill","type":"attack_rider","damage":"1d6","condition":"weapon","damage_type":"Cold","description":"Once per turn, deal an extra 1d6 Cold damage and reduce the target’s Speed by 10 feet."}]},{"desc":"Once per turn, knock a Large or smaller target Prone on a hit.","name":"Hill's Tumble","effects":[{"name":"Hill's Tumble","type":"attack_rider","condition":"weapon","description":"Once per turn, knock a Large or smaller target Prone on a hit."}]},{"desc":"Use your Reaction to reduce damage by 1d12 + Constitution modifier.","name":"Stone's Endurance","effects":[{"name":"Stone's Endurance","type":"reaction","description":"Use your Reaction to reduce damage by 1d12 + Constitution modifier."}]},{"desc":"Use your Reaction to deal 1d8 Thunder damage to a creature that hits you.","name":"Storm's Thunder","effects":[{"name":"Storm's Thunder","type":"reaction","description":"Use your Reaction to deal 1d8 Thunder damage to a creature that hits you."}]}]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 2 other languages of your choice","schema_version":2,"ability_bonuses":[],"language_options":2,"size_description":"Medium (about 7–8 feet tall).","subraces_details":[{"desc":["Your ancestor was a cloud giant, master of misty, magical flight."],"name":"Cloud Giant Ancestry","index":"cloud-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["As a Bonus Action, you magically teleport up to 30 feet to an unoccupied space you can see. PB uses per Long Rest."],"name":"Cloud's Jaunt","index":"cloud-s-jaunt","effects":[{"desc":"Teleport up to 30 ft. PB uses per Long Rest.","name":"Cloud's Jaunt","type":"bonus_action","description":"Teleport up to 30 ft. PB uses per Long Rest."}],"modifiers":[{"desc":"Teleport up to 30 ft. PB uses per Long Rest.","name":"Cloud's Jaunt","type":"bonus_action","description":"Teleport up to 30 ft. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your ancestor was a fire giant, forged in flame."],"name":"Fire Giant Ancestry","index":"fire-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["When you hit a target with an attack roll and deal damage to it, you can also deal 1d10 Fire damage to that target. PB uses per Long Rest."],"name":"Fire's Burn","index":"fire-s-burn","effects":[{"desc":"+1d10 Fire damage on a hit. PB uses per Long Rest.","name":"Fire's Burn","type":"feature","description":"+1d10 Fire damage on a hit. PB uses per Long Rest."}],"modifiers":[{"desc":"+1d10 Fire damage on a hit. PB uses per Long Rest.","name":"Fire's Burn","type":"feature","description":"+1d10 Fire damage on a hit. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your ancestor was a frost giant of the frozen wastes."],"name":"Frost Giant Ancestry","index":"frost-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["When you hit a target with an attack roll and deal damage to it, you can also deal 1d6 Cold damage to that target and reduce its Speed by 10 feet until the start of your next turn. PB uses per Long Rest."],"name":"Frost's Chill","index":"frost-s-chill","effects":[{"desc":"+1d6 Cold damage and −10 ft. Speed on a hit. PB uses per Long Rest.","name":"Frost's Chill","type":"feature","description":"+1d6 Cold damage and −10 ft. Speed on a hit. PB uses per Long Rest."}],"modifiers":[{"desc":"+1d6 Cold damage and −10 ft. Speed on a hit. PB uses per Long Rest.","name":"Frost's Chill","type":"feature","description":"+1d6 Cold damage and −10 ft. Speed on a hit. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your ancestor was a hill giant, brutish and overwhelming."],"name":"Hill Giant Ancestry","index":"hill-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["When you hit a Large or smaller creature with an attack roll and deal damage to it, you can give that target the Prone condition. PB uses per Long Rest."],"name":"Hill's Tumble","index":"hill-s-tumble","effects":[{"desc":"Knock a Large or smaller creature Prone on a hit. PB uses per Long Rest.","name":"Hill's Tumble","type":"feature","description":"Knock a Large or smaller creature Prone on a hit. PB uses per Long Rest."}],"modifiers":[{"desc":"Knock a Large or smaller creature Prone on a hit. PB uses per Long Rest.","name":"Hill's Tumble","type":"feature","description":"Knock a Large or smaller creature Prone on a hit. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your ancestor was a stone giant, unyielding as the mountain."],"name":"Stone Giant Ancestry","index":"stone-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["When you take damage, you can take a Reaction to roll 1d12. Add your Constitution modifier to the number rolled and reduce the damage by that total. PB uses per Long Rest."],"name":"Stone's Endurance","index":"stone-s-endurance","effects":[{"desc":"Reduce damage taken by 1d12 + CON. PB uses per Long Rest.","name":"Stone's Endurance","type":"reaction","description":"Reduce damage taken by 1d12 + CON. PB uses per Long Rest."}],"modifiers":[{"desc":"Reduce damage taken by 1d12 + CON. PB uses per Long Rest.","name":"Stone's Endurance","type":"reaction","description":"Reduce damage taken by 1d12 + CON. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]},{"desc":["Your ancestor was a storm giant, wreathed in thunder."],"name":"Storm Giant Ancestry","index":"storm-giant-ancestry","source":"Player's Handbook (2024)","traits":[{"url":"","desc":["When you take damage from a creature within 60 feet of you, you can take a Reaction to deal 1d8 Thunder damage to that creature. PB uses per Long Rest."],"name":"Storm's Thunder","index":"storm-s-thunder","effects":[{"desc":"Deal 1d8 Thunder damage to a creature within 60 ft. that damaged you. PB uses per Long Rest.","name":"Storm's Thunder","type":"reaction","description":"Deal 1d8 Thunder damage to a creature within 60 ft. that damaged you. PB uses per Long Rest."}],"modifiers":[{"desc":"Deal 1d8 Thunder damage to a creature within 60 ft. that damaged you. PB uses per Long Rest.","name":"Storm's Thunder","type":"reaction","description":"Deal 1d8 Thunder damage to a creature within 60 ft. that damaged you. PB uses per Long Rest."}]}],"choices":[],"languages":[],"ability_bonuses":[],"starting_proficiencies":[]}],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
