-- Hadozee (hadozee)
update public.custom_races
   set data = $persona_content_migration${"id":"c1c5586d-fa33-403c-9a24-2382a6c1ecfd","age":"Hadozee mature and age at about the same rate as humans.","desc":["Hadozee are simian humanoids with membranes of skin between their limbs that let them glide. Agile and resilient, they are prized crew aboard spelljamming ships, climbing rigging with their dexterous feet."],"name":"Hadozee","size":"Small or Medium","index":"hadozee","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["As a bonus action, you can use your feet to manipulate an object, open or close a door or container, or pick up or set down a Tiny object."],"name":"Dexterous Feet","index":"dexterous-feet","effects":[{"desc":"Manipulate an object, door, or container with your feet.","name":"Dexterous Feet","type":"bonus_action","description":"Manipulate an object, door, or container with your feet."}],"modifiers":[{"desc":"Manipulate an object, door, or container with your feet.","name":"Dexterous Feet","type":"bonus_action","description":"Manipulate an object, door, or container with your feet."}]},{"desc":["When you fall at least 10 feet above the ground, you can use your reaction to extend your skin membranes to glide horizontally a number of feet equal to your walking speed, and you take 0 damage from the fall. You determine the direction of the glide."],"name":"Glide","index":"glide","effects":[{"desc":"When falling 10+ ft., glide horizontally a distance equal to your speed and take no fall damage.","name":"Glide","type":"reaction","description":"When falling 10+ ft., glide horizontally a distance equal to your speed and take no fall damage."}],"modifiers":[{"desc":"When falling 10+ ft., glide horizontally a distance equal to your speed and take no fall damage.","name":"Glide","type":"reaction","description":"When falling 10+ ft., glide horizontally a distance equal to your speed and take no fall damage."}]},{"desc":["The magic that criminals used to create your ancestors makes you more resilient than other humanoids. When you take damage, you can use your reaction to roll a d6. Add your proficiency bonus to the number rolled and reduce the damage by that total. After you use this trait, you can't use it again until you finish a Long Rest."],"name":"Hadozee Resilience","index":"hadozee-resilience","effects":[{"desc":"Reduce damage taken by 1d6 + PB. 1/Long Rest.","name":"Hadozee Resilience","type":"reaction","description":"Reduce damage taken by 1d6 + PB. 1/Long Rest."}],"modifiers":[{"desc":"Reduce damage taken by 1d6 + PB. 1/Long Rest.","name":"Hadozee Resilience","type":"reaction","description":"Reduce damage taken by 1d6 + PB. 1/Long Rest."}]}],"choices":[{"id":"hadozee-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"hadozee-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"climb_speed":30,"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall) or Small, chosen when you select this species.","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'hadozee'),
       source = 'Spelljammer: Adventures in Space',
       migrated_at = now()
 where id = 'c1c5586d-fa33-403c-9a24-2382a6c1ecfd';

-- Satyr (satyr)
update public.custom_races
   set data = $persona_content_migration${"id":"05d96380-bf36-4dd9-af01-6b7b0780ba97","age":"Satyrs mature and age at about the same rate as humans.","desc":["Satyrs are raucous fey that resemble humans with the legs and horns of goats. Born of the Feywild's revelry, they are natural performers, nimble leapers, and surprisingly resistant to magic."],"name":"Satyr","size":"Medium","index":"satyr","speed":35,"source":"Mordenkainen Presents: Monsters of the Multiverse","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Fey."],"name":"Creature Type","index":"creature-type","effects":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}],"modifiers":[{"desc":"Your creature type is Fey (not Humanoid).","name":"Fey","type":"feature","description":"Your creature type is Fey (not Humanoid)."}]},{"desc":["You have a head and horns you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."],"name":"Ram","index":"ram","effects":[{"die":"1d6","name":"Ram","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Bludgeoning"}],"modifiers":[{"die":"1d6","name":"Ram","type":"unarmed_strike","value":"1d6","damage_die":"1d6","damage_type":"Bludgeoning"}]},{"desc":["You have advantage on saving throws against spells."],"name":"Magic Resistance","index":"magic-resistance","effects":[{"name":"Advantage on saves: Spells","type":"advantage","value":1,"filter":"Spells","target":"saves"}],"modifiers":[{"name":"Advantage on saves: Spells","type":"advantage","value":1,"filter":"Spells","target":"saves"}]},{"desc":["Whenever you make a long or high jump, you can roll a d8 and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as normal."],"name":"Mirthful Leaps","index":"mirthful-leaps","effects":[{"desc":"+1d8 feet on long and high jumps.","name":"Mirthful Leaps","type":"feature","description":"+1d8 feet on long and high jumps."}],"modifiers":[{"desc":"+1d8 feet on long and high jumps.","name":"Mirthful Leaps","type":"feature","description":"+1d8 feet on long and high jumps."}]},{"desc":["As an embodiment of revelry, you have proficiency in the Performance and Persuasion skills, and you have proficiency with one musical instrument of your choice."],"name":"Reveler","index":"reveler","effects":[{"name":"Performance","type":"proficiency","value":"Performance","target":"Performance","category":"skill"},{"name":"Persuasion","type":"proficiency","value":"Persuasion","target":"Persuasion","category":"skill"}],"modifiers":[{"name":"Performance","type":"proficiency","value":"Performance","target":"Performance","category":"skill"},{"name":"Persuasion","type":"proficiency","value":"Persuasion","target":"Persuasion","category":"skill"}]}],"choices":[{"id":"satyr-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"satyr-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"satyr-instrument","kind":"tool","count":1,"label":"Reveler: one musical instrument","source":"race","options":["Bagpipes","Drum","Dulcimer","Flute","Horn","Lute","Lyre","Pan Flute","Shawm","Viol"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; satyrs are usually chaotic.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 5–6 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
