-- Giff (giff)
update public.custom_races
   set data = $persona_content_migration${"id":"30f20da3-8175-4fff-9207-4da906a11d78","age":"Giff mature and age at about the same rate as humans.","desc":["Giff are hippopotamus-headed humanoids who travel the Astral Sea as mercenaries, soldiers, and gunners. Broad, strong, and fond of firearms, they are known for their military bearing and their love of a good explosion."],"name":"Giff","size":"Medium","index":"giff","speed":30,"source":"Spelljammer: Adventures in Space","traits":[{"desc":["When determining your character's ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."],"name":"Ability Score Increase","index":"ability-score-increase","effects":[],"modifiers":[]},{"desc":["You are a Humanoid."],"name":"Creature Type","index":"creature-type","effects":[],"modifiers":[]},{"desc":["Your psychic connection to the Astral Plane enables you to mystically access a spark of divine power, which you can channel through your weapons. When you hit a target with a simple or martial weapon, you can cause the target to take extra force damage equal to your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, but you can use it no more than once per turn. You regain all expended uses when you finish a Long Rest."],"name":"Astral Spark","index":"astral-spark","effects":[{"desc":"Once per turn, +PB force damage on a weapon hit. PB uses per Long Rest.","name":"Astral Spark","type":"feature","description":"Once per turn, +PB force damage on a weapon hit. PB uses per Long Rest."}],"modifiers":[{"desc":"Once per turn, +PB force damage on a weapon hit. PB uses per Long Rest.","name":"Astral Spark","type":"feature","description":"Once per turn, +PB force damage on a weapon hit. PB uses per Long Rest."}]},{"desc":["You have a mystical connection to firearms that traces back to the gods of the giff. You have proficiency with all firearms and ignore the loading property of any firearm. In addition, attacking at long range with a firearm doesn't impose disadvantage on your attack roll."],"name":"Firearms Mastery","index":"firearms-mastery","effects":[{"name":"Firearms","type":"proficiency","value":"Firearms","target":"Firearms","category":"weapon"},{"desc":"Ignore the loading property of firearms; no disadvantage at long range with firearms.","name":"Firearms Mastery","type":"feature","description":"Ignore the loading property of firearms; no disadvantage at long range with firearms."}],"modifiers":[{"name":"Firearms","type":"proficiency","value":"Firearms","target":"Firearms","category":"weapon"},{"desc":"Ignore the loading property of firearms; no disadvantage at long range with firearms.","name":"Firearms Mastery","type":"feature","description":"Ignore the loading property of firearms; no disadvantage at long range with firearms."}]},{"desc":["You have advantage on Strength-based ability checks and Strength saving throws. In addition, you count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."],"name":"Hippo Build","index":"hippo-build","effects":[{"name":"Advantage on saves: Strength","type":"advantage","value":1,"filter":"Strength","target":"saves"},{"desc":"Advantage on Strength checks; count as one size larger for carrying capacity.","name":"Hippo Build","type":"feature","description":"Advantage on Strength checks; count as one size larger for carrying capacity."}],"modifiers":[{"name":"Advantage on saves: Strength","type":"advantage","value":1,"filter":"Strength","target":"saves"},{"desc":"Advantage on Strength checks; count as one size larger for carrying capacity.","name":"Hippo Build","type":"feature","description":"Advantage on Strength checks; count as one size larger for carrying capacity."}]}],"choices":[{"id":"giff-asi-2","kind":"ability","count":1,"label":"+2 to 1 ability score","amount":2,"source":"race","options":["str","dex","con","int","wis","cha"]},{"id":"giff-asi-1","kind":"ability","count":1,"label":"+1 to 1 ability score","amount":1,"source":"race","options":["str","dex","con","int","wis","cha"]}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"alignment":"Any alignment; giff tend toward lawful.","is_public":true,"languages":[{"url":"","name":"Common","index":"common"}],"is_homebrew":false,"language_desc":"Common and 1 other language of your choice","schema_version":2,"ability_bonuses":[],"language_options":1,"size_description":"Medium (about 7–8 feet tall).","subraces_details":[],"starting_proficiencies":[]}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'giff'),
       source = 'Spelljammer: Adventures in Space',
       migrated_at = now()
 where id = '30f20da3-8175-4fff-9207-4da906a11d78';


