-- Spy (Criminal Variant) (spy-(criminal-variant))
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"5174be21-f402-47ab-bc60-61c6e7466363","desc":["Although your capabilities are not much different from those of a burglar or smuggler, you learned and practiced them in a very different context: as an espionage agent. You might have been an officially sanctioned agent of the crown, or perhaps you sold the secrets you uncovered to the highest bidder. Spy Contact: you have a reliable and trustworthy contact who acts as your liaison to a network of other spies. You know how to get messages to and from your contact, even over great distances; specifically, you know the local messengers, corrupt caravan masters, and seedy sailors who can deliver messages for you. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Spy (Criminal Variant)","index":"spy-(criminal-variant)","source":"Player's Handbook (2014)","choices":[{"id":"spy-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"spy-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"spy-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"spy-gaming-set","kind":"tool","count":1,"label":"Gaming Set (one of your choice)","source":"background","options":["Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set"]}],"effects":[],"feature":{"desc":["you have a reliable and trustworthy contact who acts as your liaison to a network of other spies. You know how to get messages to and from your contact, even over great distances; specifically, you know the local messengers, corrupt caravan masters, and seedy sailors who can deliver messages for you."],"name":"Spy Contact","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":15,"pp":0,"sp":0},"isCustom":true,"equipment":["Crowbar","Dark Common Clothes with a hood"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"tool_proficiencies":["Thieves' Tools"],"proficiency_choices":[],"skill_proficiencies":["Deception","Stealth"]}$persona_content_migration$::jsonb,
