       slug = coalesce(slug, 'spy-(criminal-variant)'),
       source = 'Player''s Handbook (2014)',
       migrated_at = now()
 where id = '5174be21-f402-47ab-bc60-61c6e7466363';

-- Pirate (Sailor Variant) (pirate-(sailor-variant))
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"4d978611-7d0e-416d-8f06-754bffa6c4c9","desc":["You spent your youth under the sway of a dread pirate, a ruthless cutthroat who taught you how to survive in a world of sharks and savages. You've indulged in larceny on the high seas and sent more than one deserving soul to a briny grave. Bad Reputation: no matter where you go, people are afraid of you due to your reputation. When you are in a civilized settlement, you can get away with minor criminal offenses, such as refusing to pay for food at a tavern or breaking down doors at a local shop, since most people will not report your activity to the authorities. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Pirate (Sailor Variant)","index":"pirate-(sailor-variant)","source":"Player's Handbook (2014)","choices":[{"id":"pirate-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"pirate-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"pirate-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]}],"effects":[],"feature":{"desc":["no matter where you go, people are afraid of you due to your reputation. When you are in a civilized settlement, you can get away with minor criminal offenses, such as refusing to pay for food at a tavern or breaking down doors at a local shop, since most people will not report your activity to the authorities."],"name":"Bad Reputation","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5