-- Archaeologist (archaeologist)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"0f69d081-4020-4c92-a8fc-126dcd81ce56","desc":["An archaeologist learns about the long-lost and fallen cultures of the past by studying their remains — their bones, their ruins, their surviving masterworks, and their tombs. Those who practice archaeology travel to the far corners of the world to root through crumbled cities and lost dungeons, digging in search of artifacts that might tell the stories of monarchs and high priests, wars and cataclysms. Historical Knowledge: when you enter a ruin or dungeon, you can correctly ascertain its original purpose and determine its builders, whether those were dwarves, elves, humans, yuan-ti, or some other known race. In addition, you can determine the monetary value of art objects more than a century old. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Archaeologist","index":"archaeologist","source":"Tomb of Annihilation","choices":[{"id":"archaeologist-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"archaeologist-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"archaeologist-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"archaeologist-tool","kind":"tool","count":1,"label":"Cartographer's Tools or Navigator's Tools","source":"background","options":["Cartographer's Tools","Navigator's Tools"]}],"effects":[],"feature":{"desc":["when you enter a ruin or dungeon, you can correctly ascertain its original purpose and determine its builders, whether those were dwarves, elves, humans, yuan-ti, or some other known race. In addition, you can determine the monetary value of art objects more than a century old."],"name":"Historical Knowledge","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":25,"pp":0,"sp":0},"isCustom":true,"equipment":["Wooden case containing a map to a ruin or dungeon","Bullseye Lantern","Miner's Pick","Traveler's Clothes","Shovel","Two-person Tent","Trinket recovered from a dig site"],"is_public":true,"languages":1,"is_homebrew":false,"schema_version":2,"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":["History","Survival"]}$persona_content_migration$::jsonb,
