-- Acolyte (acolyte)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"5ff0ca28-59a9-4353-8fb8-4cb8d5f6886a","desc":["You devoted yourself to service in a temple, either nestled in a town or secluded in a sacred grove. There you performed rites in honor of a god or pantheon. You served under a priest and studied religion. Thanks to your priest's instruction and your own devotion, you also learned how to channel a modicum of divine power in service to your place of worship and the people who prayed there. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Intelligence, Wisdom, Charisma. Feat: Magic Initiate (Cleric). Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Acolyte","index":"acolyte","source":"Player's Handbook (2024)","choices":[{"id":"acolyte-asi-2","kind":"ability","count":1,"label":"+2 to one of: Intelligence, Wisdom, Charisma","amount":2,"source":"background","options":["int","wis","cha"]},{"id":"acolyte-asi-1","kind":"ability","count":1,"label":"+1 to another of: Intelligence, Wisdom, Charisma","amount":1,"source":"background","options":["int","wis","cha"]},{"id":"acolyte-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Magic Initiate"]}],"effects":[],"feature":{"desc":["Ability Scores: Intelligence, Wisdom, Charisma — increase one by 2 and another by 1, or all three by 1. Origin Feat: Magic Initiate (Cleric). Skill Proficiencies: Insight, Religion. Tool Proficiency: Calligrapher's Supplies. Equipment: choose Option A — Calligrapher's Supplies, Book (prayers), Holy Symbol, Parchment (10 sheets), Robe and 8 GP — or Option B: 50 GP."],"name":"Acolyte Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":8,"pp":0,"sp":0},"isCustom":true,"equipment":["Calligrapher's Supplies","Book (prayers)","Holy Symbol","Parchment (10 sheets)","Robe