-- Haunted One (haunted-one)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"96c72c9e-4f32-4314-b678-ef53d3dc4f7b","desc":["You are haunted by something so terrible that you dare not speak of it. You've tried to bury it and run away from it, to no avail. Whatever this thing is that haunts you can't be slain with a sword or banished with a spell. It might come to you as a shadow on the wall, a bloodcurdling nightmare, a memory that refuses to die, or a demonic whisper in the dark. Heart of Darkness: those who look into your eyes can see that you have faced unimaginable horror and that you are no stranger to darkness. Though they might fear you, commoners will extend you every courtesy and do their utmost to help you. Unless you have shown yourself to be a danger to them, they will even take up arms to fight alongside you, should you find yourself facing an enemy alone. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Haunted One","index":"haunted-one","source":"Curse of Strahd","choices":[{"id":"haunted-one-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"haunted-one-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"haunted-one-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"haunted-skills","kind":"skill","count":2,"label":"Two of: Arcana, Investigation, Religion, Survival","source":"background","options":["Arcana","Investigation","Religion","Survival"]},{"id":"haunted-language","kind":"language","count":1,"label":"One exotic language","source":"background","options":["Abyssal","Celestial","Deep Speech","Draconic","Infernal","Primordial","Sylvan","Undercommon"]}],"effects":[],"feature":{"desc":["those who look into your eyes can see that you have faced unimaginable horror and that you are no stranger to darkness. Though they might fear you, commoners will extend you every courtesy and do their utmost to help you. Unless you have shown yourself to be a danger to them, they will even take up arms to fight alongside you, should you find yourself facing an enemy alone."],"name":"Heart of Darkness","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":0,"pp":0,"sp":1},"isCustom":true,"equipment":["Monster Hunter's Pack (chest","crowbar","hammer","3 wooden stakes","holy symbol","flask of holy water","set of manacles","steel mirror","flask of oil","tinderbox","3 torches)","Common Clothes"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":[]}$persona_content_migration$::jsonb,
