-- Outlander (outlander)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"a7bc61ae-fb98-44da-82ca-1ef939569586","desc":["You grew up in the wilds, far from civilization and the comforts of town and technology. You've witnessed the migration of herds larger than forests, survived weather more extreme than any city-dweller could comprehend, and enjoyed the solitude of being the only thinking creature for miles in any direction. Wanderer: you have an excellent memory for maps and geography, and you can always recall the general layout of terrain, settlements, and other features around you. In addition, you can find food and fresh water for yourself and up to five other people each day, provided that the land offers berries, small game, water, and so forth. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Outlander","index":"outlander","source":"Player's Handbook (2014)","choices":[{"id":"outlander-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"outlander-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"outlander-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"outlander-instrument","kind":"tool","count":1,"label":"Musical Instrument (one of your choice)","source":"background","options":["Bagpipes","Drum","Dulcimer","Flute","Horn","Lute","Lyre","Pan Flute","Shawm","Viol"]}],"effects":[],"feature":{"desc":["you have an excellent memory for maps and geography, and you can always recall the general layout of terrain, sett