   set data = $persona_content_migration${"id":"93302280-c040-4eb0-8f0b-af38b5f70fbe","desc":["You come from a distant place, one so remote that few people in the land where you now live have ever heard of it. Your customs, your gear, and your way of speaking mark you as a foreigner. All Eyes on You: your accent, mannerisms, figures of speech, and perhaps even your appearance all mark you as foreign. Curious glances are directed your way wherever you go, which can be a nuisance, but you also gain the friendly interest of scholars and others intrigued by far-off lands, to say nothing of everyday folk who are eager to hear stories of your homeland. You can parlay this attention into access to people and places you might not otherwise have. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Far Traveler","index":"far-traveler","source":"Sword Coast Adventurer's Guide","choices":[{"id":"far-traveler-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"far-traveler-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"far-traveler-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"far-traveler-tool","kind":"tool","count":1,"label":"Musical Instrument or Gaming Set","source":"background","options":["Bagpipes","Drum","Dulcimer","Flute","Horn","Lute","Lyre","Pan Flute","Shawm","Viol","Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set"]}],"effects":[],"feature":{"desc":["your accent, manneris