-- Gladiator (Entertainer Variant) (gladiator-(entertainer-variant))
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"70fe24fa-d01f-4f70-bc10-ad8a7d062090","desc":["A gladiator is as much an entertainer as any minstrel or circus performer, trained to make the arts of combat into a spectacle the crowd can enjoy. This kind of flashy combat is your entertainer routine. By Popular Demand: you can always find a place to perform. At such a place, you receive free lodging and food of a modest or comfortable standard, as long as you perform each night. In addition, your performance makes you something of a local figure; when strangers recognize you in a town where you have performed, they typically take a liking to you. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Gladiator (Entertainer Variant)","index":"gladiator-(entertainer-variant)","source":"Player's Handbook (2014)","choices":[{"id":"gladiator-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"gladiator-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"gladiator-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"gladiator-weapon","kind":"proficiency","count":1,"label":"One unusual weapon of your choice","source":"background","options":["Trident","Net","Whip","Scimitar","Flail","Glaive"]}],"effects":[],"feature":{"desc":["you can always find a place to perform. At such a place, you receive free lodging and food of a modest or comfortable standard, as long as you perform each night. In addition, your performance 