-- Guide (guide)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"dea37635-b124-4c3a-921e-264d8ce4a98a","desc":["You came of age in the outdoors, far from settled lands. Your home was anywhere you chose to spread your bedroll. There are wonders in the wilderness — strange monsters, pristine forests and streams, overgrown ruins of great halls once trod by giants — and you learned to fend for yourself as you explored them. From time to time, you guided friendly nature priests who instructed you in the fundamentals of channeling the magic of the wild. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Dexterity, Constitution, Wisdom. Feat: Magic Initiate (Druid). Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Guide","index":"guide","source":"Player's Handbook (2024)","choices":[{"id":"guide-asi-2","kind":"ability","count":1,"label":"+2 to one of: Dexterity, Constitution, Wisdom","amount":2,"source":"background","options":["dex","con","wis"]},{"id":"guide-asi-1","kind":"ability","count":1,"label":"+1 to another of: Dexterity, Constitution, Wisdom","amount":1,"source":"background","options":["dex","con","wis"]},{"id":"guide-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Magic Initiate"]}],"effects":[],"feature":{"desc":["Ability Scores: Dexterity, Constitution, Wisdom — increase one by 2 and another by 1, or all three by 1. Origin Feat: Magic Initiate (Druid). Skill Proficiencies: Stealth, Survival. Tool Proficiency: Cartographer's Tools. Equipment: choose Option A — Shortbow, Arrow (20), Cartographer's Tools, Bedroll, Quiver, Tent, Traveler's Clothes and 3 GP — or Option B: 50 GP."],"name":"Guide Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":3,"pp":0,"sp":0},"isCustom":true,"equipment":["Shortbow","Arrow (20)","Cartographer's Tools","Bedroll","Quiver","Tent","Traveler's Clothes","or 50 GP instead of this gear"],"is_public":true,"languages":0,"is_homebrew":false,"equipment_options":[{"label":"Equipment Pack","currency":{"cp":0,"ep":0,"gp":3,"pp":0,"sp":0},"equipment":["Shortbow","Arrow (20)","Cartographer's Tools","Bedroll","Quiver","Tent","Traveler's Clothes"]},{"label":"50 GP","currency":{"cp":0,"gp":50,"sp":0},"equipment":[]}],"tool_proficiencies":["Cartographer's Tools"],"proficiency_choices":[],"skill_proficiencies":["Stealth","Survival"],"schema_version":2}$persona_content_migration$::jsonb,
