   set data = $persona_content_migration${"id":"d2312c45-1f11-49a1-8a91-16ffb9f2d7c3","desc":["You eked out a living in dark alleyways, cutting purses or burgling shops. Perhaps you were part of a small gang of like-minded wrongdoers who looked out for each other. Or maybe you were a lone wolf, fending for yourself against the local thieves' guild and more fearsome lawbreakers. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Dexterity, Constitution, Intelligence. Feat: Alert. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Criminal","index":"criminal","source":"Player's Handbook (2024)","choices":[{"id":"criminal-asi-2","kind":"ability","count":1,"label":"+2 to one of: Dexterity, Constitution, Intelligence","amount":2,"source":"background","options":["dex","con","int"]},{"id":"criminal-asi-1","kind":"ability","count":1,"label":"+1 to another of: Dexterity, Constitution, Intelligence","amount":1,"source":"background","options":["dex","con","int"]},{"id":"criminal-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Alert"]}],"effects":[],"feature":{"desc":["Ability Scores: Dexterity, Constitution, Intelligence — increase one by 2 and another by 1, or all three by 1. Origin Feat: Alert. Skill Proficiencies: Sleight of Hand, Stealth. Tool Proficiency: Thieves' Tools. Equipment: choose Option A — Dagger (2), Thieves' Tools, Crowbar, Pouch (2), Traveler's Clothes and 16 GP — or Option B: 50 GP."],"name":"Criminal Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":16,"pp":0,"sp":0},"isCustom":true,"equipment":["Dagger (2)","Thieves' Tools","Crowbar","Pouch (2)","Traveler's Clothes","or 50 GP instead of this gear"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"equipment_options":[{"label":"Equipment P