-- Knight (Noble Variant) (knight-(noble-variant))
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"f66c697d-af3b-4af6-ae15-73053ad79630","desc":["A knighthood is among the lowest noble titles in most societies, but it can be a path to higher status. As an emblem of chivalry and the ideals of courtly love, you might include among your retainers a noble youth who serves as your squire. Retainers: you have the service of three retainers loyal to your family — a squire and two commoners. They are commoners who can perform mundane tasks for you, but they do not fight for you, will not follow you into obviously dangerous areas, and will leave if they are frequently endangered or abused. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Knight (Noble Variant)","index":"knight-(noble-variant)","source":"Player's Handbook (2014)","choices":[{"id":"knight-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"knight-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"knight-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"knight-gaming-set","kind":"tool","count":1,"label":"Gaming Set (one of your choice)","source":"background","options":["Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set"]}],"effects":[],"feature":{"desc":["you have the service of three retainers loyal to your family — a squire and two commoners. They are commoners who can perform mundane tasks for you, but they do not fight for you, will not follow you into obviously dangerous areas, and will leave if they are frequently endangered or abused."],"name":"Retainers","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":25,"pp":0,"sp":0},"isCustom":true,"equipment":["Fine Clothes","Signet Ring","Scroll of Pedigree"],"is_public":true,"languages":1,"is_homebrew":false,"schema_version":2,"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":["History","Persuasion"]}$persona_content_migration$::jsonb,
