-- Scribe (scribe)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"2e3103be-617d-4ca0-8d89-6ca29aa3b9aa","desc":["You spent formative years in a scriptorium, a monastery dedicated to the preservation of knowledge, or a government agency, where you learned to write with a clear hand and produce finely written texts. Perhaps you scribed government documents or copied tomes of literature. You might have some basic knowledge of the subject matter of the texts you copied, and you have a keen eye for detail. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Dexterity, Intelligence, Wisdom. Feat: Skilled. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Scribe","index":"scribe","source":"Player's Handbook (2024)","choices":[{"id":"scribe-asi-2","kind":"ability","count":1,"label":"+2 to one of: Dexterity, Intelligence, Wisdom","amount":2,"source":"background","options":["dex","int","wis"]},{"id":"scribe-asi-1","kind":"ability","count":1,"label":"+1 to another of: Dexterity, Intelligence, Wisdom","amount":1,"source":"background","options":["dex","int","wis"]},{"id":"scribe-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Skilled"]}],"effects":[],"feature":{"desc":["Ability Scores: Dexterity, Intelligence, Wisdom — increase one by 2 and another by 1, or all three by 1. Origin Feat: Skilled. Skill Proficiencies: Investigation, Perception. Tool Proficiency: Calligrapher's Supplies. Equipment: choose Option A — Calligrapher's Supplies, Fine Clothes, Lamp, Oil (3 flasks), Parchment (12 sheets) and 23 GP — or Option B: 50 GP."],"name":"Scribe Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":23,"pp":0,"sp":0},"isCustom":true,"equipment":["Calligrapher's Supplies","Fine Clothes","Lamp","Oil (3 flasks)","Parchment (12 sheets)","or 50 GP instead of this