-- Anthropologist (anthropologist)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"02810d74-7774-455f-88fc-194ea4255afd","desc":["You have always been fascinated by other cultures, from the most ancient and primeval lost lands to the most modern civilizations. By studying other cultures' customs, philosophies, laws, rituals, religious beliefs, languages, and art, you have learned how tribes, empires, and all forms of society in between craft their own destinies and doom. Adept Linguist: you can communicate with humanoids who don't speak any language you know. You must observe the humanoids interacting with one another for at least 1 day, after which you learn a handful of important words, expressions, and gestures — enough to communicate on a rudimentary level. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Anthropologist","index":"anthropologist","source":"Tomb of Annihilation","choices":[{"id":"anthropologist-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"anthropologist-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"anthropologist-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]}],"effects":[],"feature":{"desc":["you can communicate with humanoids who don't speak any language you know. You must observe the humanoids interacting with one another for at least 1 day, after which you learn a handful of important words, expressions, and gestures — enough to communicate on a rudimentary level."],"name":"Adept Linguist","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":10,"pp":0,"sp":0},"isCustom":true,"equipment":["Leather-bound Diary","Bottle of Ink","Ink Pen","Traveler's Clothes","Trinket of special significance"],"is_public":true,"languages":2,"is_homebrew":false,"schema_version":2,"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":["Insight","Religion"]}$persona_content_migration$::jsonb,
