   set data = $persona_content_migration${"id":"ccc66464-c108-4868-bc69-da2b47d03265","desc":["You began mopping floors and scrubbing counters in an artisan's workshop for a few coppers per day as soon as you were strong enough to carry a bucket. When you were old enough to apprentice, you learned to create basic crafts of your own, as well as how to sweet-talk the occasional demanding customer. Your trade has also given you a keen eye for detail. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Strength, Dexterity, Intelligence. Feat: Crafter. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Artisan","index":"artisan","source":"Player's Handbook (2024)","choices":[{"id":"artisan-asi-2","kind":"ability","count":1,"label":"+2 to one of: Strength, Dexterity, Intelligence","amount":2,"source":"background","options":["str","dex","int"]},{"id":"artisan-asi-1","kind":"ability","count":1,"label":"+1 to another of: Strength, Dexterity, Intelligence","amount":1,"source":"background","options":["str","dex","int"]},{"id":"artisan-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Crafter"]},{"id":"artisan-tools","kind":"tool","count":1,"label":"Artisan's Tools (one of your choice)","source":"background","options":["Alchemist's Supplies","Brewer's Supplies","Calligrapher's Supplies","Carpenter's Tools","Cartographer's Tools","Cobbler's Tools","Cook's Utensils","Glassblower's Tools","Jeweler's Tools","Leatherworker's Tools","Mason's Tools","Painter's Supplies","Potter's Tools","Smith's Tools","Tinker's Tools","Weaver's Tools","Woodcarver's Tools"]}],"effects":[],"feature":{"desc":["Ability Scores: Strength, Dexterity, Intelligence — increase one by 2 and another by 1, or all three by 1. Origin Feat: Crafter. Skill Proficiencies: Investigation, Persuasion. Tool Proficiency: one of your choice (see choices). Equipment: choose Option A — Artisan's Tools (same as the ones chosen), Pouch (2), Traveler's Clothes and 32 GP — or Option B: 50 GP."],"name":"Artisan Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":32,"pp":0,"sp":0},"isCustom":true,"equipment":["Artisan's Tools (same as the ones chosen)","Pouch (2)","Traveler's Clothes","or 50 GP instead of this gear"],"is_public":true,"languages":0,"is_homebrew":false,"equipment_options":[{"label":"Equipment Pack","currency":{"cp":0,"ep":0,"gp":32,"pp":0,"sp":0},"equipment":["Artisan's Tools (same as the ones chosen)","Pouch (2)","Traveler's Clothes"]},{"label":"50 GP","currency":{"cp":0,"gp":50,"sp":0},"equipment":[]}],"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":["Investigation","Persuasion"],"schema_version":2}$persona_content_migration$::jsonb,
