-- Urchin (urchin)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"e29a6f9f-f084-4884-8f45-70d13c859509","desc":["You grew up on the streets alone, orphaned, and poor. You had no one to watch over you or to provide for you, so you learned to provide for yourself. You fought fiercely over food and kept a constant watch out for other desperate souls who might steal from you. City Secrets: you know the secret patterns and flow to cities and can find passages through the urban sprawl that others would miss. When you are not in combat, you (and companions you lead) can travel between any two locations in the city twice as fast as your speed would normally allow. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Urchin","index":"urchin","source":"Player's Handbook (2014)","choices":[{"id":"urchin-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"urchin-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"urchin-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]}],"effects":[],"feature":{"desc":["you know the secret patterns and flow to cities and can find passages through the urban sprawl that others would miss. When you are not in combat, you (and companions you lead) can travel between any two locations in the city twice as fast as your speed would normally allow."],"name":"City Secrets","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":10,"pp":0,"sp":0},"isCustom":true,"equipment":["Small Knife","Map of the city you grew up in","Pet mouse","Token to remember your parents by","Common Clothes"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"tool_proficiencies":["Disguise Kit","Thieves' Tools"],"proficiency_choices":[],"skill_proficiencies":["Sleight of Hand","Stealth"]}$persona_content_migration$::jsonb,
