-- Folk Hero (folk-hero)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"3e68d080-0299-486e-8979-90ad1539b982","desc":["You come from a humble social rank, but you are destined for so much more. Already the people of your home village regard you as their champion, and your destiny calls you to stand against the tyrants and monsters that threaten the common folk everywhere. Rustic Hospitality: since you come from the ranks of the common folk, you fit in among them with ease. You can find a place to hide, rest, or recuperate among other commoners, unless you have shown yourself to be a danger to them. They will shield you from the law or anyone else searching for you, though they will not risk their lives for you. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Folk Hero","index":"folk-hero","source":"Player's Handbook (2014)","choices":[{"id":"folk-hero-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"folk-hero-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"folk-hero-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"folk-hero-tool","kind":"tool","count":1,"label":"Artisan's Tools (one of your choice)","source":"background","options":["Alchemist's Supplies","Brewer's Supplies","Calligrapher's Supplies","Carpenter's Tools","Cartographer's Tools","Cobbler's Tools","Cook's Utensils","Glassblower's Tools","Jeweler's Tools","Leatherworker's Tools","Mason's Tools","Painter's Supplies","Potter's Tools","Smith's Tools","Tinker's Tools","Weaver's Tools","Woodcarver's Tools"]}],"effects":[],"feature":{"desc":["since you come from the ranks of the common folk, you fit in among them with ease. You can find a place to hide, rest, or recuperate among other commoners, unless you have shown yourself to be a danger to them. They will shield you from the law or anyone else searching for you, though they will not risk their lives for you."],"name":"Rustic Hospitality","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":10,"pp":0,"sp":0},"isCustom":true,"equipment":["Artisan's Tools (as chosen)","Shovel","Iron Pot","Common Clothes"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"tool_proficiencies":["Vehicles (Land)"],"proficiency_choices":[],"skill_proficiencies":["Animal Handling","Survival"]}$persona_content_migration$::jsonb,
