-- Urban Bounty Hunter (urban-bounty-hunter)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"4da19a39-d550-4a29-9a22-7d3315b8745a","desc":["Before you became an adventurer, your life was already full of conflict and excitement, because you made a living tracking down people for pay. Unlike some people who collect bounties, though, you aren't a savage who follows quarry into or through the wilderness. You're involved in a lucrative trade in the place where you live that routinely tests your skills and survival instincts. Ear to the Ground: you are in frequent contact with people in the segment of society that your chosen quarries move through. These people might be associated with the criminal underworld, the rough-and-tumble folk of the streets, or members of high society. This connection comes in the form of a contact in any city you visit, a person who provides information about the people and places of the local area. Legacy background (2014 rules): under the 2024 rules you choose any three ability scores (+2/+1 or +1/+1/+1) and any Origin feat; the original background feature is kept below for tables that still use it."],"name":"Urban Bounty Hunter","index":"urban-bounty-hunter","source":"Sword Coast Adventurer's Guide","choices":[{"id":"urban-bounty-hunter-asi-2","kind":"ability","count":1,"label":"+2 to one ability score (legacy background: any ability)","amount":2,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"urban-bounty-hunter-asi-1","kind":"ability","count":1,"label":"+1 to another ability score","amount":1,"source":"background","options":["str","dex","con","int","wis","cha"]},{"id":"urban-bounty-hunter-feat","kind":"feat","count":1,"label":"Origin Feat (any)","source":"background","options":["Alert","Crafter","Healer","Lucky","Magic Initiate","Musician","Savage Attacker","Skilled","Tavern Brawler","Tough"]},{"id":"ubh-skills","kind":"skill","count":2,"label":"Two of: Deception, Insight, Persuasion, Stealth","source":"background","options":["Deception","Insight","Persuasion","Stealth"]},{"id":"ubh-tools","kind":"tool","count":2,"label":"Two of: a Gaming Set, a Musical Instrument, Thieves' Tools","source":"background","options":["Thieves' Tools","Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set","Bagpipes","Drum","Dulcimer","Flute","Horn","Lute","Lyre","Pan Flute","Shawm","Viol"]}],"effects":[],"feature":{"desc":["you are in frequent contact with people in the segment of society that your chosen quarries move through. These people might be associated with the criminal underworld, the rough-and-tumble folk of the streets, or members of high society. This connection comes in the form of a contact in any city you visit, a person who provides information about the people and places of the local area."],"name":"Ear to the Ground","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":20,"pp":0,"sp":0},"isCustom":true,"equipment":["Set of clothes appropriate to your duties"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"tool_proficiencies":[],"proficiency_choices":[],"skill_proficiencies":[]}$persona_content_migration$::jsonb,
