   set data = $persona_content_migration${"id":"6d9a8bab-f525-45b8-8fed-ceb399c0d0e2","desc":["Once you were old enough to order an ale, you soon had a favorite stool in every tavern within ten miles of where you were born. As you traveled the circuit from public house to watering hole, you learned to prey on unfortunates who were in the market for a comforting lie or two — perhaps a sham potion or forged ancestry records. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Dexterity, Constitution, Charisma. Feat: Skilled. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Charlatan","index":"charlatan","source":"Player's Handbook (2024)","choices":[{"id":"charlatan-asi-2","kind":"ability","count":1,"label":"+2 to one of: Dexterity, Constitution, Charisma","amount":2,"source":"background","options":["dex","con","cha"]},{"id":"charlatan-asi-1","kind":"ability","count":1,"label":"+1 to another of: Dexterity, Constitution, Charisma","amount":1,"source":"background","options":["dex","con","cha"]},{"id":"charlatan-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Skilled"]}],"effects":[],"feature":{"desc":["Ability Scores: Dexterity, Constitution, Charisma — increase one by 2 and another by 1, or all three by 1. Origin Feat: Skilled. Skill Proficiencies: Deception, Sleight of Hand. Tool Proficiency: Forgery Kit. Equipment: choose Option A — Forgery Kit, Costume, Fine Clothes and 15 GP — or Option B: 50 GP."],"name":"Charlatan Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":15,"pp":0,"sp":0},"isCustom":true,"equipment":["Forgery Kit","Costume","Fine Clothes","or 50 GP instead of this gear"],"is_public":true,"languages":0,"is_homebrew":false,"schema_version":2,"equipment_options":[{"label":"Equipment Pack","currency":{"cp":0,"