-- Noble (noble)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"e6aa1001-a22e-4ad7-b309-93c8061a0219","desc":["You were raised in a castle, surrounded by wealth, power, and privilege. Your family of minor aristocrats ensured that you received a first-class education, some of which you appreciated and some of which you resented. Your time in the castle, especially the many hours you spent observing your family at court, also taught you a great deal about leadership. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Strength, Intelligence, Charisma. Feat: Skilled. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Noble","index":"noble","source":"Player's Handbook (2024)","choices":[{"id":"noble-asi-2","kind":"ability","count":1,"label":"+2 to one of: Strength, Intelligence, Charisma","amount":2,"source":"background","options":["str","int","cha"]},{"id":"noble-asi-1","kind":"ability","count":1,"label":"+1 to another of: Strength, Intelligence, Charisma","amount":1,"source":"background","options":["str","int","cha"]},{"id":"noble-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Skilled"]},{"id":"noble-gaming-set","kind":"tool","count":1,"label":"Gaming Set (one of your choice)","source":"background","options":["Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set"]}],"effects":[],"feature":{"desc":["Ability Scores: Strength, Intelligence, Charisma — increase one by 2 and another by 1, or all three by 1. Origin Feat: Skilled. Skill Proficiencies: History, Persuasion. Tool Proficiency: one of your choice (see choices). Equipment: choose Option A — Gaming Set (same as the one chosen), Fine Clothes, Perfume and 29 GP — or Option B: 50 GP."],"name":"Noble Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":29,"pp":0,"sp":0},"is