-- Sage (sage)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"cd27983a-4c3a-4683-bfd1-1b3d9685fa3f","desc":["You spent your formative years traveling between manors and monasteries, performing various odd jobs and services in exchange for access to their libraries. You whiled away many a long evening studying books and scrolls, learning the lore of the multiverse — even the rudiments of magic — and your mind yearns for more. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Constitution, Intelligence, Wisdom. Feat: Magic Initiate (Wizard). Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Sage","index":"sage","source":"Player's Handbook (2024)","choices":[{"id":"sage-asi-2","kind":"ability","count":1,"label":"+2 to one of: Constitution, Intelligence, Wisdom","amount":2,"source":"background","options":["con","int","wis"]},{"id":"sage-asi-1","kind":"ability","count":1,"label":"+1 to another of: Constitution, Intelligence, Wisdom","amount":1,"source":"background","options":["con","int","wis"]},{"id":"sage-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Magic Initiate"]}],"effects":[],"feature":{"desc":["Ability Scores: Constitution, Intelligence, Wisdom — increase one by 2 and another by 1, or all three by 1. Origin Feat: Magic Initiate (Wizard). Skill Proficiencies: Arcana, History. Tool Proficiency: Calligrapher's Supplies. Equipment: choose Option A — Quarterstaff, Calligrapher's Supplies, Book (history), Parchment (8 sheets), Robe and 8 GP — or Option B: 50 GP."],"name":"Sage Origin","effects":[]},"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","currency":{"cp":0,"ep":0,"gp":8,"pp":0,"sp":0},"isCustom":true,"equipment":["Quarterstaff","Calligrapher's Supplies","Book (history)","Parchment (8 sheets)","Robe","or 50 GP instead of this gear"],"is_public":true,"languages":0,"is_homebr