-- Soldier (soldier)
update public.custom_backgrounds
   set data = $persona_content_migration${"id":"6d51fc4a-4c45-44e6-8d99-4b82c7960e25","desc":["You began training for war as soon as you reached adulthood and carry precious few memories of life before you took up arms. Battle is in your blood. Sometimes you catch yourself reflexively performing the basic fighting exercises you learned first. Eventually, you put that training to use on the battlefield, protecting the realm by waging war. Ability Scores: increase one of the listed scores by 2 and another by 1, or increase all three by 1 (if you take the +1/+1/+1 option, set the +2 pick to +1 manually). Ability Scores: Strength, Dexterity, Constitution. Feat: Savage Attacker. Choose Option A (the listed gear and coin) or Option B: 50 GP instead."],"name":"Soldier","index":"soldier","source":"Player's Handbook (2024)","choices":[{"id":"soldier-asi-2","kind":"ability","count":1,"label":"+2 to one of: Strength, Dexterity, Constitution","amount":2,"source":"background","options":["str","dex","con"]},{"id":"soldier-asi-1","kind":"ability","count":1,"label":"+1 to another of: Strength, Dexterity, Constitution","amount":1,"source":"background","options":["str","dex","con"]},{"id":"soldier-feat","kind":"feat","count":1,"label":"Origin Feat","source":"background","options":["Savage Attacker"]},{"id":"soldier-gaming-set","kind":"tool","count":1,"label":"Gaming Set (one of your choice)","source":"background","options":["Dice Set","Dragonchess Set","Playing Card Set","Three-Dragon Ante Set"]}],"effects":[],"feature":{"desc":["Ability Scores: Strength, Dexterity, Constitution — increase one by 2 and another by 1, or all three by 1. Origin Feat: Savage Attacker. Skill Proficiencies: Athletics, Intimidation. Tool Proficiency: one of your choice (see choices). Equipment: choose Option A — Spear, Shortbow, Arrow (20), Gaming Set (same as the one chosen), Healer's Kit, Quiver, Traveler's Clothes and 14 GP — or Option B: 50 GP."],"name":"Soldier Origin","effects":[]},"user_id":"b0027d9e