-- Healer (healer)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793709353044-fxsg4","desc":["Origin Feat (2024). You gain the following benefits. Battle Medic: if you have a Healer's Kit, you can expend one use of it and take the Utilize action to heal a creature within 5 feet of yourself. That creature can expend one of its Hit Point Dice, and you then roll that die. The creature regains a number of Hit Points equal to the roll plus your Proficiency Bonus. Healing Rerolls: whenever you roll a die to determine the number of Hit Points you restore with a spell or with this feat's Battle Medic benefit, you can reroll the die if it rolls a 1, and you must use the new roll."],"name":"Healer","index":"healer","source":"Player's Handbook (2024)","choices":[],"effects":[{"desc":"Expend a Healer's Kit use: a creature within 5 ft. spends a Hit Die and regains the roll + your PB.","name":"Battle Medic","type":"action","description":"Expend a Healer's Kit use: a creature within 5 ft. spends a Hit Die and regains the roll + your PB."},{"desc":"Reroll 1s on healing dice from spells or Battle Medic.","name":"Healing Rerolls","type":"feature","description":"Reroll 1s on healing dice from spells or Battle Medic."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
