-- Musician (musician)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793709355055-gms4y","desc":["Origin Feat (2024). You gain the following benefits. Instrument Training: you gain proficiency with three Musical Instruments of your choice. Encouraging Song: as you finish a Short or Long Rest, you can play a song on a Musical Instrument with which you have proficiency and give Heroic Inspiration to allies who hear the song. The number of allies you can affect in this way equals your Proficiency Bonus."],"name":"Musician","index":"musician","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Instrument Training","type":"proficiency_choice","count":3,"options":["Bagpipes","Drum","Dulcimer","Flute","Horn","Lute","Lyre","Pan Flute","Shawm","Viol"],"category":"tool"},{"desc":"After a Short or Long Rest, give Heroic Inspiration to up to PB allies who hear you play.","name":"Encouraging Song","type":"feature","description":"After a Short or Long Rest, give Heroic Inspiration to up to PB allies who hear you play."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
