   set data = $persona_content_migration${"id":"hb-1793709356810-t3s5g","desc":["Origin Feat (2024). You've trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon's damage dice twice and use either roll against the target."],"name":"Savage Attacker","index":"savage-attacker","source":"Player's Handbook (2024)","choices":[],"effects":[{"desc":"Once per turn on a weapon hit, roll the weapon damage dice twice and use either result.","name":"Savage Attacker","type":"feature","description":"Once per turn on a weapon hit, roll the weapon damage dice twice and use either result."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
