-- Crafter (crafter)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793709370287-rkd6k","desc":["Origin Feat (2024). You gain the following benefits. Tool Proficiency: you gain proficiency with three different Artisan's Tools of your choice. Discount: whenever you buy a nonmagical item, you receive a 20 percent discount on it. Fast Crafting: when you finish a Long Rest, you can craft one piece of gear from the Fast Crafting table, provided you have the Artisan's Tools associated with that item and are proficient with those tools. The item lasts until you finish another Long Rest, at which point the item falls apart."],"name":"Crafter","index":"crafter","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Crafter Tool Proficiency","type":"proficiency_choice","count":3,"options":["Alchemist's Supplies","Brewer's Supplies","Calligrapher's Supplies","Carpenter's Tools","Cartographer's Tools","Cobbler's Tools","Cook's Utensils","Glassblower's Tools","Jeweler's Tools","Leatherworker's Tools","Mason's Tools","Painter's Supplies","Potter's Tools","Smith's Tools","Tinker's Tools","Weaver's Tools","Woodcarver's Tools"],"category":"tool"},{"desc":"20 percent discount on nonmagical items.","name":"Discount","type":"feature","description":"20 percent discount on nonmagical items."},{"desc":"After a Long Rest, craft one temporary item from the Fast Crafting table with tools you are proficient in.","name":"Fast Crafting","type":"feature","description":"After a Long Rest, craft one temporary item from the Fast Crafting table with tools you are proficient in."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
