-- Chef (chef)
update public.custom_feats
   set data = $persona_content_migration${"id":"62a23e18-c59b-4eb7-82ed-cd298b7242fa","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Constitution or Wisdom score by 1, to a maximum of 20. Cook's Utensils: you gain proficiency with Cook's Utensils if you don't already have it. Replenishing Meal: as part of a Short Rest, you can cook special food if you have ingredients and Cook's Utensils on hand. You can prepare enough of this food for a number of creatures equal to 4 plus your Proficiency Bonus. At the end of the Short Rest, any creature who eats the food and spends one or more Hit Dice to regain Hit Points regains an extra 1d8 Hit Points. Bolstering Treats: with 1 hour of work or when you finish a Long Rest, you can cook a number of treats equal to your Proficiency Bonus if you have ingredients and Cook's Utensils on hand. These special treats last 8 hours after being made. A creature can use a Bonus Action to eat one of those treats to gain 1d8 Temporary Hit Points."],"name":"Chef","index":"chef","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["con","wis"]},{"name":"Cook's Utensils","type":"proficiency","value":"Cook's Utensils","target":"Cook's Utensils","category":"tool"},{"desc":"Short Rest food: creatures spending Hit Dice regain +1d8 HP (4 + PB servings).","name":"Replenishing Meal","type":"feature","description":"Short Rest food: creatures spending Hit Dice regain +1d8 HP (4 + PB servings)."},{"desc":"PB treats per Long Rest; Bonus Action to eat for 1d8 Temp HP.","name":"Bolstering Treats","type":"feature","description":"PB treats per Long Rest; Bonus Action to eat for 1d8 Temp HP."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
