-- Lucky (lucky)
update public.custom_feats
   set data = $persona_content_migration${"id":"41de49bc-1f69-4e2c-988f-b85a372e0327","desc":["Origin Feat. You gain the following benefits. Luck Points: you have a number of Luck Points equal to your Proficiency Bonus and can spend the points on the benefits below. You regain your expended Luck Points when you finish a Long Rest. Advantage: when you roll a d20 for a D20 Test, you can spend 1 Luck Point to give yourself Advantage on the roll. Disadvantage: when a creature rolls a d20 for an attack roll against you, you can spend 1 Luck Point to impose Disadvantage on that roll."],"name":"Lucky","index":"lucky","source":"Player's Handbook (2024)","choices":[],"effects":[{"desc":"PB Luck Points per Long Rest: spend 1 for Advantage on a D20 Test, or to impose Disadvantage on an attack against you.","name":"Luck Points","type":"feature","description":"PB Luck Points per Long Rest: spend 1 for Advantage on a D20 Test, or to impose Disadvantage on an attack against you."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"resources":[{"key":"luck_points","max":{"type":"proficiency"},"name":"Luck Points","level":1,"reset":"long"}],"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
