-- Tavern Brawler (tavern-brawler)
update public.custom_feats
   set data = $persona_content_migration${"id":"0ad061c3-dba5-43d1-96ff-472749e7364f","desc":["Origin Feat. You gain the following benefits. Enhanced Unarmed Strike: when you hit with your Unarmed Strike and deal damage, you can deal Bludgeoning damage equal to 1d4 plus your Strength modifier instead of the normal damage of an Unarmed Strike. Damage Rerolls: whenever you roll a damage die for your Unarmed Strike, you can reroll the die if it rolls a 1, and you must use the new roll. Improvised Weaponry: you have proficiency with improvised weapons. Push: when you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can deal damage to the target and also push it 5 feet away from you. You can use this benefit only once per turn."],"name":"Tavern Brawler","index":"tavern-brawler","source":"Player's Handbook (2024)","choices":[],"effects":[{"die":"1d4","name":"Enhanced Unarmed Strike","type":"unarmed_strike","value":"1d4","damage_die":"1d4","damage_type":"Bludgeoning"},{"name":"Improvised Weapons","type":"proficiency","value":"Improvised Weapons","target":"Improvised Weapons","category":"weapon"},{"desc":"Reroll 1s on Unarmed Strike damage dice.","name":"Damage Rerolls","type":"feature","description":"Reroll 1s on Unarmed Strike damage dice."},{"desc":"Once per turn, push a creature 5 ft. when you hit it with an Unarmed Strike during the Attack action.","name":"Push","type":"feature","description":"Once per turn, push a creature 5 ft. when you hit it with an Unarmed Strike during the Attack action."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
