update public.custom_feats
   set data = $persona_content_migration${"id":"82759d69-da05-477b-8c52-069a32ddce3e","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Charisma score by 1, to a maximum of 20. Impersonation: while you're disguised as a real or fictional person, you have Advantage on Charisma (Deception or Performance) checks to convince others that you are that person. Mimicry: you can mimic the sounds of other creatures, including speech. To mimic a sound or a way of speaking, you must have heard it for at least 1 minute. A creature that hears the mimicry can tell it is a mimicry only with a successful Wisdom (Insight) check against a DC equal to 8 plus your Charisma modifier and Proficiency Bonus."],"name":"Actor","index":"actor","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase (CHA)","type":"asi","amount":1,"attributes":["cha"]},{"key":"deception_mimicry","name":"Impersonation","type":"advantage","label":"Deception/Performance (Impersonation)","filter":"Deception","target":"skills"},{"desc":"Mimic sounds and speech you have heard for 1 minute; Insight DC 8 + CHA + PB to detect.","name":"Mimicry","type":"feature","description":"Mimic sounds and speech you have heard for 1 minute; Insight DC 8 + CHA + PB to detect."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
