-- Dual Wielder (dual-wielder)
update public.custom_feats
   set data = $persona_content_migration${"id":"d7ff13f4-8306-413c-9941-00ef8f73e040","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 20. Enhanced Dual Wielding: when you take the Attack action on your turn and attack with a weapon that has the Light property, you can make one extra attack as a Bonus Action later on the same turn with a different weapon, which must be a Melee weapon that lacks the Two-Handed property. You don't add your ability modifier to the extra attack's damage unless that modifier is negative. Quick Draw: you can draw or stow two weapons that lack the Two-Handed property when you would normally be able to draw or stow only one."],"name":"Dual Wielder","index":"dual-wielder","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"After attacking with a Light weapon, make one extra attack with a different one-handed melee weapon.","name":"Enhanced Dual Wielding","type":"bonus_action","description":"After attacking with a Light weapon, make one extra attack with a different one-handed melee weapon."},{"desc":"Draw or stow two one-handed weapons at once.","name":"Quick Draw","type":"feature","description":"Draw or stow two one-handed weapons at once."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
