-- Mobile (mobile)
update public.custom_feats
   set data = $persona_content_migration${"id":"479d1687-892c-4069-8183-00299b3e4df1","desc":["Feat (Player's Handbook 2014; replaced by Speedy in the 2024 rules). You are exceptionally speedy and agile. Your speed increases by 10 feet. When you use the Dash action, difficult terrain doesn't cost you extra movement on that turn. When you make a melee attack against a creature, you don't provoke opportunity attacks from that creature for the rest of the turn, whether you hit or not."],"name":"Mobile","index":"mobile","source":"Player's Handbook (2014)","choices":[],"effects":[{"stat":"speed","type":"stat_bonus","value":10,"target":"speed"},{"desc":"Dash ignores difficult terrain; no opportunity attacks from creatures you melee attack this turn.","name":"Mobile","type":"feature","description":"Dash ignores difficult terrain; no opportunity attacks from creatures you melee attack this turn."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"","schema_version":2}$persona_content_migration$::jsonb,
