-- Charger (charger)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714360309-1z0rb","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 20. Improved Dash: when you take the Dash action, your Speed increases by 10 feet for that action. Charge Attack: if you move at least 10 feet in a straight line immediately before hitting with an attack using a Melee weapon or an Unarmed Strike as part of the Attack action on your turn, choose one of the following effects: gain a 1d8 bonus to the attack's damage roll, or push the target up to 10 feet away if it is no more than one size larger than you. You can use this benefit only once per turn."],"name":"Charger","index":"charger","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"+10 ft. Speed when you Dash.","name":"Improved Dash","type":"feature","description":"+10 ft. Speed when you Dash."},{"desc":"Once per turn after moving 10+ ft. straight before a melee hit: +1d8 damage or push the target 10 ft.","name":"Charge Attack","type":"feature","description":"Once per turn after moving 10+ ft. straight before a melee hit: +1d8 damage or push the target 10 ft."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
