-- Sentinel (sentinel)
update public.custom_feats
   set data = $persona_content_migration${"id":"fe73efd4-8282-451c-8730-9f6046c0be4c","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 20. Punish Mobility: immediately after a creature within 5 feet of you takes the Disengage action or makes an attack against a target other than you, you can make an Opportunity Attack against that creature. Halt: when you hit a creature with an Opportunity Attack, the creature's Speed is reduced to 0 until the end of the current turn."],"name":"Sentinel","index":"sentinel","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"Opportunity Attack against a creature within 5 ft. that Disengages or attacks someone other than you.","name":"Punish Mobility","type":"reaction","description":"Opportunity Attack against a creature within 5 ft. that Disengages or attacks someone other than you."},{"desc":"Creatures hit by your Opportunity Attacks have Speed 0 until the end of the turn.","name":"Halt","type":"feature","description":"Creatures hit by your Opportunity Attacks have Speed 0 until the end of the turn."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
