 where id = 'fe73efd4-8282-451c-8730-9f6046c0be4c';

-- Shield Master (shield-master)
update public.custom_feats
   set data = $persona_content_migration${"id":"e7410e14-771e-4889-9c68-971ec7e8350c","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength score by 1, to a maximum of 20. Shield Bash: if you attack a creature within 5 feet of you as part of the Attack action and hit with a Melee weapon or Unarmed Strike, you can immediately bash the target with your Shield if it's equipped, forcing the target to make a Strength saving throw (DC 8 plus your Strength modifier and Proficiency Bonus). On a failed save, you either push the target 5 feet from you or cause it to have the Prone condition (your choice). You can use this benefit only once per turn. Interpose Shield: if you're subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you can take a Reaction to take no damage if you succeed on the saving throw and are holding a Shield."],"name":"Shield Master","index":"shield-master","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase (STR)","type":"asi","amount":1,"attributes":["str"]},{"desc":"Once per turn after a melee hit, the target makes a STR save (8 + STR + PB) or is pushed 5 ft. or knocked Prone.","name":"Shield Bash","type":"feature","description":"Once per turn after a melee hit, the target makes a STR save (8 + STR + PB) or is pushed 5 ft. or knocked Prone."},{"desc":"Take no damage on a successful Dexterity save for half damage while holding a Shield.","name":"Interpose Shield","type":"reaction","description":"Take no damage on a successful Dexterity save for half damage while holding a Shield."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
