update public.custom_feats
   set data = $persona_content_migration${"id":"b5dc8435-7cb8-4278-aeaf-205ea803f665","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 20. Pole Strike: immediately after you take the Attack action and attack with a Quarterstaff, a Spear, or a weapon that has the Heavy and Reach properties, you can use a Bonus Action to make a melee attack with the opposite end of the weapon. The weapon deals Bludgeoning damage, and the weapon's damage die for this attack is a d4. Reactive Strike: while you're holding a Quarterstaff, a Spear, or a weapon that has the Heavy and Reach properties, you can take a Reaction to make one melee attack against a creature that enters the reach you have with that weapon."],"name":"Polearm Master","index":"polearm-master","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"After attacking with a quarterstaff, spear, or Heavy+Reach weapon, make a 1d4 bludgeoning attack with the butt end.","name":"Pole Strike","type":"bonus_action","description":"After attacking with a quarterstaff, spear, or Heavy+Reach weapon, make a 1d4 bludgeoning attack with the butt end."},{"desc":"Make a melee attack against a creature that enters your reach with a quarterstaff, spear, or Heavy+Reach weapon.","name":"Reactive Strike","type":"reaction","description":"Make a melee attack against a creature that enters your reach with a quarterstaff, spear, or Heavy+Reach weapon."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
