-- War Caster (war-caster)
update public.custom_feats
   set data = $persona_content_migration${"id":"0c557753-1d0c-43b3-92dc-45cf816026cc","desc":["General Feat (Prerequisite: Level 4+). Prerequisite: Spellcasting or Pact Magic feature. You gain the following benefits. Ability Score Increase: increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Concentration: you have Advantage on Constitution saving throws that you make to maintain Concentration. Reactive Spell: when a creature provokes an Opportunity Attack from you by leaving your reach, you can take a Reaction to cast a spell at the creature rather than making an Opportunity Attack. The spell must have a casting time of one action and must target only that creature. Somatic Components: you can perform the Somatic components of spells even when you have weapons or a Shield in one or both hands."],"name":"War Caster","index":"war-caster","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["int","wis","cha"]},{"key":"concentration","name":"Concentration","type":"advantage","label":"Con Saves (Concentration)","filter":"Concentration","target":"saves"},{"desc":"Cast a single-target action spell instead of an Opportunity Attack.","name":"Reactive Spell","type":"reaction","description":"Cast a single-target action spell instead of an Opportunity Attack."},{"desc":"Perform somatic components with weapons or a Shield in hand.","name":"Somatic Components","type":"feature","description":"Perform somatic components with weapons or a Shield in hand."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+, Spellcasting or Pact Magic feature","schema_version":2}$persona_content_migration$::jsonb,
