update public.custom_feats
   set data = $persona_content_migration${"id":"439aa8a6-437b-406f-aebb-2f13756c1a43","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Dexterity score by 1, to a maximum of 20. Ignore Loading: you ignore the Loading property of the Hand Crossbow, Heavy Crossbow, and Light Crossbow (all called crossbows elsewhere in this feat). If you're holding one of them, you can load a piece of ammunition into it even if you lack a free hand. Firing in Melee: being within 5 feet of an enemy doesn't impose Disadvantage on your attack rolls with crossbows. Dual Wielding: when you make the extra attack of the Light property, you can add your ability modifier to the damage of that attack if that attack is with a crossbow."],"name":"Crossbow Expert","index":"crossbow-expert","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase (DEX)","type":"asi","amount":1,"attributes":["dex"]},{"desc":"Ignore the Loading property of crossbows; load without a free hand.","name":"Ignore Loading","type":"feature","description":"Ignore the Loading property of crossbows; load without a free hand."},{"desc":"No Disadvantage on crossbow attacks within 5 ft. of an enemy.","name":"Firing in Melee","type":"feature","description":"No Disadvantage on crossbow attacks within 5 ft. of an enemy."},{"desc":"Add your ability modifier to the Light-property extra attack with a crossbow.","name":"Dual Wielding","type":"feature","description":"Add your ability modifier to the Light-property extra attack with a crossbow."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
