-- Telekinetic (telekinetic)
update public.custom_feats
   set data = $persona_content_migration${"id":"fb21bf7d-3287-488f-ac4a-6e7891726be7","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Minor Telekinesis: you learn the Mage Hand spell. You can cast it without Verbal or Somatic components, you can make the spectral hand Invisible, and its range increases by 30 feet when you cast it. Your spellcasting ability for the spell is the ability increased by this feat. Telekinetic Shove: as a Bonus Action, you can target one creature you can see within 30 feet of yourself. The target must succeed on a Strength saving throw (DC 8 plus your Proficiency Bonus and the ability modifier of the score increased by this feat) or be moved 5 feet toward or away from you."],"name":"Telekinetic","index":"telekinetic","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["int","wis","cha"]},{"name":"Mage Hand (no V/S, invisible, +30 ft. range)","type":"spell_access","count":1,"spell":"Mage Hand"},{"desc":"A creature within 30 ft. makes a STR save or is moved 5 ft. toward or away from you.","name":"Telekinetic Shove","type":"bonus_action","description":"A creature within 30 ft. makes a STR save or is moved 5 ft. toward or away from you."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
