-- Poisoner (poisoner)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714418370-pyzsd","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Dexterity or Intelligence score by 1, to a maximum of 20. Potent Poison: when you make a damage roll that deals Poison damage, it ignores Resistance to Poison damage. Brew Poison: you gain proficiency with the Poisoner's Kit. With 1 hour of work using such a kit and expending 50 GP worth of materials, you can create a number of poison doses equal to your Proficiency Bonus. As a Bonus Action, you can apply a poison dose to a weapon or piece of ammunition. Once applied, the poison retains its potency for 1 minute or until you hit with the poisoned item, whichever comes first. When a creature takes damage from the poisoned item, that creature must succeed on a Constitution saving throw (DC 8 plus the modifier of the ability increased by this feat and your Proficiency Bonus) or take 2d8 Poison damage and have the Poisoned condition until the end of your next turn."],"name":"Poisoner","index":"poisoner","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["dex","int"]},{"name":"Poisoner's Kit","type":"proficiency","value":"Poisoner's Kit","target":"Poisoner's Kit","category":"tool"},{"desc":"Your Poison damage ignores Poison Resistance.","name":"Potent Poison","type":"feature","description":"Your Poison damage ignores Poison Resistance."},{"desc":"Apply a brewed poison dose: on a hit, CON save or 2d8 Poison damage and Poisoned until your next turn.","name":"Apply Poison","type":"bonus_action","description":"Apply a brewed poison dose: on a hit, CON save or 2d8 Poison damage and Poisoned until your next turn."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
