-- Ritual Caster (ritual-caster)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714420130-fp14c","desc":["General Feat (Prerequisite: Level 4+). Prerequisite: Intelligence, Wisdom, or Charisma 13+. You gain the following benefits. Ability Score Increase: increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Ritual Spells: choose two level 1 spells that have the Ritual tag. You always have those spells prepared, and you can cast them with any spell slots you have. Your spellcasting ability for them is the ability increased by this feat. Whenever you gain a new level, you can replace one of the chosen spells with another level 1 Ritual spell. Quick Ritual: with this benefit, you can cast a Ritual spell that you have prepared using its regular casting time rather than the extended time for a Ritual. Doing so doesn't require a spell slot. Once you use this benefit, you can't do so again until you finish a Long Rest."],"name":"Ritual Caster","index":"ritual-caster","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["int","wis","cha"]},{"name":"Two level 1 Ritual spells (always prepared)","type":"spell_access","count":2,"level":1},{"desc":"Cast a prepared Ritual spell at its normal casting time without a slot. 1/Long Rest.","name":"Quick Ritual","type":"feature","description":"Cast a prepared Ritual spell at its normal casting time without a slot. 1/Long Rest."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+, Intelligence, Wisdom, or Charisma 13+","schema_version":2}$persona_content_migration$::jsonb,
