-- Speedy (speedy)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714465953-51g0u","desc":["General Feat (Prerequisite: Level 4+). Prerequisite: Dexterity or Constitution 13+. You gain the following benefits. Ability Score Increase: increase your Dexterity or Constitution score by 1, to a maximum of 20. Speed Increase: your Speed increases by 10 feet. Dash over Difficult Terrain: when you take the Dash action, Difficult Terrain doesn't cost you extra movement for the rest of the current turn. Agile Movement: Opportunity Attacks have Disadvantage against you."],"name":"Speedy","index":"speedy","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["dex","con"]},{"stat":"speed","type":"stat_bonus","value":10,"target":"speed"},{"desc":"Dash ignores difficult terrain this turn.","name":"Dash over Difficult Terrain","type":"feature","description":"Dash ignores difficult terrain this turn."},{"desc":"Opportunity Attacks against you have Disadvantage.","name":"Agile Movement","type":"feature","description":"Opportunity Attacks against you have Disadvantage."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+, Dexterity or Constitution 13+","schema_version":2}$persona_content_migration$::jsonb,
