-- Spell Sniper (spell-sniper)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714467711-drokv","desc":["General Feat (Prerequisite: Level 4+). Prerequisite: Spellcasting or Pact Magic feature. You gain the following benefits. Ability Score Increase: increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Bypass Cover: your attack rolls for spells ignore Half Cover and Three-Quarters Cover. Casting in Melee: being within 5 feet of an enemy doesn't impose Disadvantage on your attack rolls with spells. Increased Range: when you cast a spell that has a range of at least 10 feet and requires an attack roll, you can increase the spell's range by 60 feet."],"name":"Spell Sniper","index":"spell-sniper","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["int","wis","cha"]},{"desc":"Spell attacks ignore Half and Three-Quarters Cover.","name":"Bypass Cover","type":"feature","description":"Spell attacks ignore Half and Three-Quarters Cover."},{"desc":"No Disadvantage on spell attacks within 5 ft. of an enemy.","name":"Casting in Melee","type":"feature","description":"No Disadvantage on spell attacks within 5 ft. of an enemy."},{"desc":"+60 ft. range on attack-roll spells with a range of 10+ ft.","name":"Increased Range","type":"feature","description":"+60 ft. range on attack-roll spells with a range of 10+ ft."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+, Spellcasting or Pact Magic feature","schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'spell-sniper'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = 'e9e3a5ef-8df2-4025-9e79-6d9e73177450';

-- Weapon Master (weapon-master)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714469471-co47n","desc":["General Feat (Prerequisite: Level 4+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 20. Mastery Property: your training with weapons allows you to use the mastery property of one kind of Simple or Martial weapon of your choice, provided you have proficiency with it. Whenever you finish a Long Rest, you can change the kind of weapon to another eligible kind."],"name":"Weapon Master","index":"weapon-master","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"Use the mastery property of one weapon you are proficient with; change it after a Long Rest.","name":"Mastery Property","type":"feature","description":"Use the mastery property of one weapon you are proficient with; change it after a Long Rest."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 4+","schema_version":2}$persona_content_migration$::jsonb,
