-- Boon of Dimensional Travel (boon-of-dimensional-travel)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714472991-j21fj","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Blink Steps: immediately after you take the Attack action or the Magic action, you can teleport up to 30 feet to an unoccupied space you can see."],"name":"Boon of Dimensional Travel","index":"boon-of-dimensional-travel","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"desc":"After the Attack or Magic action, teleport up to 30 ft.","name":"Blink Steps","type":"feature","description":"After the Attack or Magic action, teleport up to 30 ft."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
