-- Boon of Energy Resistance (boon-of-energy-resistance)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714474754-dc8uz","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Energy Resistances: you gain Resistance to two of the following damage types of your choice: Acid, Cold, Fire, Lightning, Necrotic, Poison, Psychic, Radiant, or Thunder. Whenever you finish a Long Rest, you can change your choices. Energy Redirection: when you take damage of one of the types chosen for the Energy Resistances benefit, you can take a Reaction to direct damage of the same type toward another creature you can see within 60 feet of yourself that isn't behind Total Cover. If you do so, that creature must succeed on a Dexterity saving throw (DC 8 plus your Proficiency Bonus and Constitution modifier) or take damage equal to 2d12 plus your Constitution modifier."],"name":"Boon of Energy Resistance","index":"boon-of-energy-resistance","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"name":"Energy Resistances","type":"feature_choice","count":2,"options":[{"desc":"Resistance to Acid damage.","name":"Acid","effects":[{"name":"Acid","type":"resistance","value":"Acid","damage_type":"Acid"}]},{"desc":"Resistance to Cold damage.","name":"Cold","effects":[{"name":"Cold","type":"resistance","value":"Cold","damage_type":"Cold"}]},{"desc":"Resistance to Fire damage.","name":"Fire","effects":[{"name":"Fire","type":"resistance","value":"Fire","damage_type":"Fire"}]},{"desc":"Resistance to Lightning damage.","name":"Lightning","effects":[{"name":"Lightning","type":"resistance","value":"Lightning","damage_type":"Lightning"}]},{"desc":"Resistance to Necrotic damage.","name":"Necrotic","effects":[{"name":"Necrotic","type":"resistance","value":"Necrotic","damage_type":"Necrotic"}]},{"desc":"Resistance to Poison damage.","name":"Poison","effects":[{"name":"Poison","type":"resistance","value":"Poison","damage_type":"Poison"}]},{"desc":"Resistance to Psychic damage.","name":"Psychic","effects":[{"name":"Psychic","type":"resistance","value":"Psychic","damage_type":"Psychic"}]},{"desc":"Resistance to Radiant damage.","name":"Radiant","effects":[{"name":"Radiant","type":"resistance","value":"Radiant","damage_type":"Radiant"}]},{"desc":"Resistance to Thunder damage.","name":"Thunder","effects":[{"name":"Thunder","type":"resistance","value":"Thunder","damage_type":"Thunder"}]}]},{"desc":"Redirect damage of a resisted type: a creature within 60 ft. makes a DEX save or takes 2d12 + CON damage.","name":"Energy Redirection","type":"reaction","description":"Redirect damage of a resisted type: a creature within 60 ft. makes a DEX save or takes 2d12 + CON damage."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
       schema_version = 2,
       slug = coalesce(slug, 'boon-of-energy-resistance'),
       source = 'Player''s Handbook (2024)',
       migrated_at = now()
 where id = '1cc6da06-ddf1-4b53-8304-3f96af3e66f9';

-- Boon of Fate (boon-of-fate)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714476515-2rjf8","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Improved Fate: when you or another creature you can see within 60 feet of you succeeds on or fails a D20 Test, you can roll 2d4 and apply the total rolled as a bonus or penalty to the d20 roll. Once you use this benefit, you can't use it again until you finish a Short or Long Rest."],"name":"Boon of Fate","index":"boon-of-fate","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"desc":"Add or subtract 2d4 from a D20 Test by a creature within 60 ft. 1/Short or Long Rest.","name":"Improved Fate","type":"feature","description":"Add or subtract 2d4 from a D20 Test by a creature within 60 ft. 1/Short or Long Rest."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
