-- Boon of Fortitude (boon-of-fortitude)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714478273-nl5ab","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Fortified Health: your Hit Point maximum increases by 40. In addition, whenever you regain Hit Points, you can regain additional Hit Points equal to your Constitution modifier. Once you've regained these additional Hit Points, you can't do so again until the start of your next turn."],"name":"Boon of Fortitude","index":"boon-of-fortitude","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"stat":"max_hp","type":"stat_bonus","value":40,"target":"max_hp"},{"desc":"+40 max HP; once per turn, add your CON modifier whenever you regain HP.","name":"Fortified Health","type":"feature","description":"+40 max HP; once per turn, add your CON modifier whenever you regain HP."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
