update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714480034-c9lby","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase your Strength or Dexterity score by 1, to a maximum of 30. Overcome Defenses: the Bludgeoning, Piercing, and Slashing damage you deal always ignores Resistance. Overwhelming Strike: when you roll a 20 on the d20 for an attack roll, you can deal extra damage to the target equal to the ability score increased by this feat. The extra damage's type is the same as the attack's type."],"name":"Boon of Irresistible Offense","index":"boon-of-irresistible-offense","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex"]},{"desc":"Your B/P/S damage ignores Resistance.","name":"Overcome Defenses","type":"feature","description":"Your B/P/S damage ignores Resistance."},{"desc":"On a natural 20, deal extra damage equal to your STR or DEX score.","name":"Overwhelming Strike","type":"feature","description":"On a natural 20, deal extra damage equal to your STR or DEX score."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
