-- Boon of Recovery (boon-of-recovery)
update public.custom_feats
   set data = $persona_content_migration${"id":"hb-1793714481797-5aevg","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Last Stand: when you would be reduced to 0 Hit Points, you can drop to 1 Hit Point instead and regain a number of Hit Points equal to half your Hit Point maximum. Once you use this benefit, you can't use it again until you finish a Long Rest. Recover Vitality: as a Bonus Action, you can regain a number of Hit Points equal to half your Hit Point maximum. Once you use this benefit, you can't use it again until you finish a Long Rest."],"name":"Boon of Recovery","index":"boon-of-recovery","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"desc":"Drop to 1 HP instead of 0 and regain half your max HP. 1/Long Rest.","name":"Last Stand","type":"feature","description":"Drop to 1 HP instead of 0 and regain half your max HP. 1/Long Rest."},{"desc":"Regain half your maximum HP. 1/Long Rest.","name":"Recover Vitality","type":"bonus_action","description":"Regain half your maximum HP. 1/Long Rest."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
