   set data = $persona_content_migration${"id":"hb-1793714488845-ndoxj","desc":["Epic Boon (Prerequisite: Level 19+). You gain the following benefits. Ability Score Increase: increase one ability score of your choice by 1, to a maximum of 30. Merge with Shadows: while within Dim Light or Darkness, you can give yourself the Invisible condition as a Bonus Action. The condition ends on you immediately after you take an action, a Bonus Action, or a Reaction. Shadowy Form: while within Dim Light or Darkness, you have Resistance to all damage except Psychic and Radiant."],"name":"Boon of the Night Spirit","index":"boon-of-the-night-spirit","source":"Player's Handbook (2024)","choices":[],"effects":[{"name":"Ability Score Increase","type":"asi_choice","count":1,"amount":1,"options":["str","dex","con","int","wis","cha"]},{"desc":"In dim light or darkness, become Invisible until you act.","name":"Merge with Shadows","type":"bonus_action","description":"In dim light or darkness, become Invisible until you act."},{"desc":"In dim light or darkness, Resistance to all damage except Psychic and Radiant.","name":"Shadowy Form","type":"feature","description":"In dim light or darkness, Resistance to all damage except Psychic and Radiant."}],"user_id":"b0027d9e-13eb-41a7-b3ee-1da5f52c9599","isCustom":true,"is_public":true,"is_homebrew":false,"prerequisite":"Level 19+","schema_version":2}$persona_content_migration$::jsonb,
